  (260, 2, '2 handfuls of spinach (optional)', '2 puñados de espinacas (opcional)'),
  (260, 3, '1 apple, peeled, cored, and chopped into small pieces', '1 manzana pelada, con el centro removido y picadita en trozos chicos'),
  (260, 4, '1 banana', '1 plátano'),
  (260, 5, '½ cup water', '½ taza de agua'),
  (260, 6, 'ice', 'hielo'),
  (261, 1, '1 zucchini, chopped into small pieces', '1 calabacita, picada en trozos chicos'),
  (261, 2, '1 banana, cut into small pieces', '1 plátano, partido en pedazos chicos'),
  (261, 3, '1 apple, peeled, cored, and chopped into small pieces', '1 manzana pelada, con el centro removido y picada en trozos chicos'),
  (261, 4, '½ cup water', '½ taza de agua'),
  (262, 1, '2 parsnips', '2 pastinacas/chirivías'),
  (262, 2, '1 apple, peeled, cored and cut into small pieces', '1 manzana pelada, con el centro removido y picadita en trozos chicos'),
