  (267, 1, '2 large baking potatoes', '2 papas grandes apropiadas para hornear'),
  (267, 2, '1 cup cooked broccoli (steamed, boiled, or Microwaved), chopped into small pieces', '1 taza de brócoli cocido (al vapor, hervido, o en un horno de microondas), picado en pedazos pequeños'),
  (267, 3, '2 large spoons of butter or margarine', '2 cucharadas grandes de mantequilla o margarina'),
  (267, 4, '1 green onion, including green part, finely chopped (optional)', '1 cebollita bien picadita, incluyendo el rabo verde (opcional)'),
