  (268, 1, '3 large potatoes or 6 small potatoes, peeled and cut into medium-size chunks', '3 papas grandes o 6 papas chicas, peladas y cortadas en trozos de tamaño mediano'),
  (268, 2, '3-4 carrots, peeled and cut into medium-size chunks', '3-4 zanahorias, peladas y rebanadas en trozos de tamaño mediano'),
  (268, 3, '4 chicken half-breasts, either boneless or with the bone', '4 medias pechugas de pollo, con hueso o sin hueso'),
  (268, 4, '1 can (10 ¾ ounce) condensed cream of chicken soup', '1 lata (10 ¾ onzas) de crema de pollo condensada'),
  (268, 5, '1 can (10 ¾ ounce) condensed cream of mushroom soup', '1 lata (10 ¾ onzas) de crema de hongos condensada'),
  (268, 6, 'pinch of salt, pepper, garlic salt, garlic powder, or other favorite seasonings (optional)', 'pizca de sal, pimienta, sal de ajo, ajo en polvo, u otros condimentos favoritos (opcional)'),
  (268, 7, 'frozen peas or other frozen vegetables (optional)', 'chícharos u otras verduras congeladas (opcional)'),
  (269, 1, '2½ pounds boneless chuck roast', '2½ libras de carne, corte espaldilla ("chuck roast") sin hueso'),
  (269, 2, '4 medium onions, peeled and sliced', '4 cebollas medianas, peladas y rebanadas'),
  (269, 3, '3 large spoons vegetable oil', '3 cucharadas grandes de aceite vegetal'),
  (269, 4, 'pinches of salt and pepper', 'pizcas de sal y pimienta'),
  (269, 5, '1 cup beef broth', '1 taza de consomé/caldo de res'),
  (269, 6, '½ cup apple juice', '½ taza de jugo de manzana'),
  (269, 7, '1 large spoon brown sugar', '1 cucharada grande de azúcar morena'),
  (269, 8, '1 large spoon vinegar', '1 cucharada grande de vinagre'),
  (269, 9, '2 large spoons mustard', '2 cucharadas grandes de mostaza'),
  (270, 1, '1½ pounds boneless pork, cut into 1 inch chunks', '1½ libras de puerco deshuesado y partido en trozos de 1 pulgada de tamaño'),
  (270, 2, '6 medium sweet potatoes, peeled and cut into 1 inch chunks', '6 camotes medianos, pelados y partidos en trozos de 1 pulgada de tamaño'),
  (270, 3, '1-2 large onions, peeled and cut into chunks', '1-2 cebollas grandes, peladas y partidas en trozos de 1 pulgada de tamaño'),
  (270, 4, '1 cup barbeque sauce (any flavor)', '1 taza de salsa estilo barbacoa ("barbeque") (de cualquier sabor)'),
