INSERT INTO recipe_step (recipe_id, position, text_en, text_es) VALUES
  (1, 1, 'Bring a large pot of water, with a pinch of salt, to a boil. Add broccoli pieces and cook for 1-2 minutes. Drain and immediately put pieces in a bowl of cold water and ice cubes to stop the cooking. Let cool and drain.', 'Ponga suficiente agua en una olla, agréguele una pizca de sal y déjela que hierva. Agréguele los pedazos de brócoli y cocínelos de 1-2 minutos. Vacié el agua e inmediatamente ponga el brócoli en un recipiente hondo con agua fría y hielos para evitar que se sigan cocinando. Déjelos que se enfríen para después colarlos.'),
  (1, 2, 'Combine broccoli, apple, celery, and chicken (optional).', 'Combina el brócoli, manzana, apio, y pollo (opcional).'),
  (1, 3, 'Mix mayonnaise or yogurt and sugar in a small bowl.', 'Mezcle la mayonesa, o yogur y azúcar en un tazón, para preparar el aderezo.'),
  (1, 4, 'Add dressing to the broccoli and mix well.', 'Añada el aderezo a la mezcla de brócoli, manzana y apio y mezcle bien.'),
  (1, 5, 'Chill if desired.', 'Ponga a enfriar, si lo desea.'),
  (2, 1, 'Steam or boil broccoli until tender and drain.', 'Cocine al vapor o hierva el brócoli hasta que quede tierno y luego cuélelo.'),
  (2, 2, 'Combine grated ginger, orange juice, soy sauce, and oil in a small bowl and mix.', 'Combine el jengibre rallado, jugo de naranja, salsa de soya, y aceite en un tazón chico y mezcle.'),
  (2, 3, 'Pour sauce over broccoli and toss well.', 'Vierta la salsa sobre el brócoli y revuelva bien.'),
  (3, 1, 'Steam or boil the broccoli pieces until tender, drain. Chop into small pieces.', 'Cocine al vapor o hierva los pedazos de brócoli hasta que estén tiernos. Cuélelos y córtelos en pedazos pequeños.'),
  (3, 2, 'Heat oil in a frying pan and cook onions for 3-4 minutes, until they are soft.', 'Caliente el aceite en un sartén y cocine las cebollas de 3-4 minutos, hasta que queden suaves.'),
  (3, 3, 'Combine all ingredients and mix well.', 'Combine todos los ingredientes y mezcle bien.'),
  (3, 4, 'Pour into a greased Crock­Pot.', 'Vierta todo en la olla eléctrica "Crock­Pot" despues de haberle untado aceite en la parte interior.'),
  (3, 5, 'Cook on low for 3 ½ -4 hours, or until a toothpick inserted into the center comes out clean.', 'Cocine a baja temperatura de 3 ½- 4 horas, o hasta que un palillo insertado en el centro salga limpio.'),
  (3, 6, 'Turn pot over, remove bread, and cut into wedges.', 'Voltee la olla de cabeza, saque el pan, y corte pedazos en forma de cuña.'),
  (4, 1, 'Preheat oven to 350 degrees. Lightly grease a baking dish.', 'Precaliente el horno a 350 grados. Usando el aceite, engrase ligeramente una charola para hornear.'),
  (4, 2, 'Steam or boil broccoli pieces until tender. Drain and chop into small pieces.', 'Cocine al vapor o hierva los pedazos de brócoli hasta que estén tiernos. Cuélelos y córtelos en pedazos pequeños.'),
  (4, 3, 'Combine milk, mustard, and pepper in a large bowl.', 'Combine la leche, mostaza, y pimienta en un tazón grande.'),
  (4, 4, 'Add broccoli, meat (optional), green onions (optional) and cream of mushroom soup and a ½ cup of cheese.', 'Añada el brócoli, carne (opcional), cebollitas (opcional), la crema de hongos y ½ taza de queso.'),
  (4, 5, 'Spoon about a half cup of the mixture into the center of a tortilla. Fold in sides and roll up.', 'Saque con una cuchara casi ½ taza de la mezcla y póngala en el centro de una tortilla. Doble los costados hacia adentro y enrolle.'),
  (4, 6, 'Place in a greased baking dish.', 'Coloque en la charola para hornear previamente engrasada.'),
  (4, 7, 'Bake for 15 minutes. Sprinkle with remaining cheese. Bake 10 minutes more.', 'Hornee por 15 minutos. Rocíe con lo que queda de queso. Hornee 10 minutos más.'),
  (5, 1, 'Put about 1 cup of water into a pot, and bring to a boil. Add the broccoli. Cover with a lid and reduce heat to medium.', 'Vacíe aproximadamente 1 taza de agua en una olla, y póngala a hervir. Añada el brócoli. Cubra con una tapa y reduzca el fuego a mediana intensidad.'),
  (5, 2, 'Cook for about 5 minutes, making sure that there is always some water in the pot. The broccoli should become bright green and remain firm.', 'Cocine por casi 5 minutos, asegurándose de que siempre haya agua en la olla. El brócoli deberá ponerse verde brilloso y mantenerse firme.'),
  (5, 3, 'Drain. Mix with pinch of salt and pepper, or lemon or lime juice, to taste.', 'Vacíe el agua que quede. Añada una pizca de sal y pimienta, o jugo de limón al gusto, y mezcle bien.'),
  (7, 1, 'Cook broccoli (either steam, boil, or microwave). Broccoli should turn bright green and stay firm.', 'Cocine el brócoli (ya sea al vapor, hervido, o en un horno de microondas). El brócoli deberá ponerse verde brilloso y mantenerse firme.'),
  (7, 2, 'Heat the oil in a pan on medium heat. Add the garlic, cook and stir until garlic starts to get soft.', 'Caliente el aceite en un sartén a fuego medio. Añada el ajo, guise y agite hasta que el ajo empiece a ponerse blandito.'),
  (7, 3, 'Add broccoli, with a pinch of salt and pepper. Turn heat to high, cook and stir for another 2-3 minutes.', 'Añada el brócoli y una pizca de sal y pimienta. Aumente la intensidad de la lumbre a una temperatura alta y siga guisando y agitando todo por otros 2-3 minutos.'),
  (8, 1, 'Preheat oven to 450 degrees.', 'Precaliente el horno a 450 grados.'),
  (8, 2, 'Mix broccoli pieces with Italian dressing or vegetable oil in a bowl.', 'Mezcle los pedazos de brócoli con el aderezo italiano o aceite vegetal en un tazón.'),
  (8, 3, 'Add a pinch of salt, pepper, or favorite seasonings and mix well, if using vegetable oil (optional).', 'Añada una pizca de sal, pimienta, o sazones favoritos y mezcle bien, si decidió usar aceite vegetal en vez de aderezo italiano (opcional).'),
  (8, 4, 'Coat baking sheet with a large spoon of vegetable oil. Bake the broccoli for 9-12 minutes, or until tender. Turn broccoli once or twice during cooking.', 'Cubra una charola para hornear usando una cucharada grande de aceite vegetal. Distribuya el brócoli en la charola y cocine en el horno de 9-12 minutos, o hasta que el brócoli este tierno. Voltee los pedazos de brócoli una o dos veces mientras se cocinan.'),
  (9, 1, 'Put broccoli pieces in a bowl with the other sliced vegetables. Mix with Italian dressing.', 'Ponga los pedazos de brócoli en un tazón junto con los otros vegetales ya cortados. Mezcle con el aderezo estilo italiano.'),
  (9, 2, 'Refrigerate for at least 3 hours, or even overnight. Stir once or twice during this time. Vegetables will become tender, almost like cooking them.', 'Refrigere por lo menos 3 horas, o incluso durante toda la noche. Revuelva todo con una cuchara una o dos veces durante este tiempo. Los vegetales se pondrán tiernos, casi como cuando uno los cocina.'),
  (9, 3, 'Boil noodles according to the directions on the package. Drain noodles, mix with a large spoon of Italian dressing, and cool.', 'Hierva los fideos de acuerdo con las instrucciones que están en el paquete. Cuele los fideos, mezcle con una cucharada grande de aderezo estilo italiano, y enfríe.'),
  (9, 4, 'Combine vegetables with noodles and stir.', 'Combine los vegetales con los fideos, y revuelva/agite algunas veces.'),
  (10, 1, 'Wash and peel carrots. Slice into rounds about as thick as a pencil.', 'Lave y pele las zanahorias. Corte en rodajas tan gruesas como un lápiz.'),
  (10, 2, 'Put about 2-3 cups of water or broth into a pot, and bring to a boil. Add carrot pieces. Cover with a lid and reduce heat to medium. Cook for about 5 minutes.', 'Ponga 2-3 tazas de agua o caldo en una olla, y deje que hierva. Añada las rodajas de zanahoria. Cubra con una tapa y reduzca el fuego a mediana intensidad. Cocine por aproximadamente 5 minutos.'),
  (10, 3, 'Add broccoli and cook for another 3 minutes.', 'Añada el brócoli y cocine por 3 minutos más.'),
  (10, 4, 'Drain. Mix with pinch of salt and pepper, or lemon or lime juice, to taste.', 'Cuele o filtre sobre el fregadero. Mezcle con una pizca de sal y pimienta, o jugo de limón al gusto.'),
  (11, 1, 'To bake the potatoes, first clean them and stab them several times with a fork or sharp knife. This will allow heat to be released as the potatoes bake.', 'Para hornear las papas, primero límpielas y hágales varios huecos con un tenedor o con un cuchillo filoso. Esto permitirá que el calor se libere cuando las papas se horneen.'),
  (11, 2, 'Bake the potatoes for 50-60 minutes at 350 degrees.', 'Hornee las papas de 50-60 minutos a una temperatura de 350 grados.'),
  (11, 3, 'Slice the potato in half, lengthwise. Scoop out the insides and mash in a bowl with the butter or margarine, until smooth.', 'Rebane la papa por la mitad, a lo largo. Saque con una cuchara el interior de estas y junto con la mantequilla o margarina, machaque en un tazón hasta que se suavice y quede como puré.'),
  (11, 4, 'Add the green onion, sour cream, or shredded cheese (optional).', 'Añada la cebollita picada, crema agria, o queso rallado (opcional).'),
  (11, 5, 'Mix in pinch of salt and pepper.', 'Mezcle con una pizca de sal y pimienta.'),
  (11, 6, 'Stir in the broccoli pieces.', 'Vierta los pedazos del brócoli a la mezcla.'),
  (11, 7, 'Stuff the potato-broccoli filling into the potato skins. Put any extra filling in an oven proof container.', 'Coloque el relleno de papa y brócoli dentro de las cáscaras de las papas. Ponga el relleno que le sobre en un recipiente ideal para el horno.'),
  (11, 8, 'Cook the stuffed potatoes (and any extra filling) for 10­-15 minutes at 350 degrees.', 'Hornee las papas rellenas (y cualquier relleno extra) de 10­-15 minutos a 350 grados.'),
  (12, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (12, 2, 'Mix broccoli with 1 large spoon of oil and pinch of salt and pepper.', 'Mezcle el brócoli con una cucharada grande de aceite y una pizca de sal y pimienta.'),
  (12, 3, 'Coat a baking sheet with 1 large spoon of oil. Bake the broccoli for 8 minutes, or until tender, turning once or twice.', 'Usando el aceite restante, únteselo a una charola para hornear. Coloque el brócoli sobre la charola y hornee por 8 minutos, o hasta que esté tierno, volteándolo una o dos veces.'),
  (12, 4, 'Melt butter or margarine in a pan over medium heat. Add garlic and lemon peel. Stir for about 1 minute.', 'Derrita la mantequilla o margarina en un sartén a fuego medio. Añada el ajo y la cáscara de limón. Agite por cerca de 1 minuto.'),
  (12, 5, 'Turn heat to low and add lemon juice. Cook another minute.', 'Disminuya el fuego al mínimo y añada el jugo de limón. Cocine durante un minuto más.'),
  (12, 6, 'Mix broccoli with the lemon sauce until all the pieces are coated. Top with nuts (optional).', 'Mezcle el brócoli con la salsa de limón, hasta que todos los pedazos queden bien cubiertos. Rocíe con nueces (opcional).'),
  (14, 1, 'Place the broccoli pieces into a microwaveable dish.', 'Coloque los pedazos de brócoli en un recipiente apropiado para un horno de microondas.'),
  (14, 2, 'Add water or broth and cover with plastic wrap. Microwave on high for 4-5 minutes.', 'Añada agua o caldo y cubra con una envoltura de plástico. Caliente en el horno de microondas a temperatura alta de 4-5 minutos.'),
  (14, 3, 'Add flavor with a pinch of salt or pepper, or lemon or lime juice to taste, or toss with some Italian dressing.', 'Añada sabor con una pizca de sal o pimienta, o jugo de limón al gusto, o mezcle con un poco de aderezo estilo italiano.'),
  (15, 1, 'Boil about 1 inch of water in a pot.', 'Hierva alrededor de 1 pulgada de agua en un olla.'),
  (15, 2, 'Place a steamer basket in the pot and place broccoli into the basket.', 'Coloque un vaporizador de vegetales plegable (tipo canastita) en la olla, y ponga el brócoli dentro del vaporizador.'),
  (15, 3, 'Cover, cook for 3-4 minutes. The broccoli should be a bright green and still firm. Test with a fork.', 'Cubra y cocine de 3-4 minutos. El brócoli deberá estar verde brilloso y firme. Pruebe con un tenedor.'),
  (15, 4, 'Add flavor with a pinch of salt or pepper, or lemon or lime juice to taste, or toss with some Italian dressing.', 'Añada sabor con una pizca de sal o pimienta, o jugo de limón al gusto, o mezcle con un poco de aderezo estilo italiano.'),
  (16, 1, 'Dry chicken breasts, sprinkle with pepper.', 'Seque las pechugas de pollo y rocíeles pimienta.'),
  (16, 2, 'Heat a large pan on medium and add butter, margarine, or oil. Cook chicken 5-10 minutes or until browned, turning several times. Set chicken aside.', 'Caliente un sartén grande a fuego medio, añada mantequilla, margarina o aceite. Cocine el pollo de 5-10 minutos o hasta que se dore, volteándolo varias veces. Saque las pechugas y dejelas reposar.'),
  (16, 3, 'Combine remaining ingredients in pan. Heat until boiling. Return chicken and cover pan.', 'Combine los ingredientes restantes en el sartén. Caliente hasta que hierva. Ponga de nuevo el pollo en el sartén y tápelo.'),
  (16, 4, 'Cook, turning often, over low heat 10-20 minutes, until chicken is no longer pink inside and broccoli is tender-crisp.', 'Cocine a fuego lento, volteando con frecuencia durante 10­-12 minutos, hasta que el pollo deje de estar rosado por dentro y el brócoli esté tierno pero firme.'),
  (17, 1, 'Put butter, margarine or oil and garlic and onion in a pot on medium heat. Stir until onion and garlic start to get soft.', 'Ponga la mantequilla, margarina o aceite y ajo (opcional) y cebolla (opcional) en una olla a fuego medio. Agite hasta que la cebolla y el ajo se ablanden.'),
  (17, 2, 'Crush or chop the tomatoes.', 'Machaque/pique los jitomates.'),
  (17, 3, 'Add broccoli, tomatoes (with juice), and broth to the pot.', 'Añada brócoli, jitomates (con jugo), y caldo a la olla.'),
  (17, 4, 'Cover and simmer for 10­-15 minutes, until broccoli pieces are tender. Stir a few times. Add a pinch of pepper.', 'Cubra y guise a fuego lento de 10­-15 minutos, hasta que los pedazos del brócoli estén tiernos. Agite unas cuantas veces. Añada una pizca de pimienta.'),
  (17, 5, 'Use a potato masher or a blender to crush vegetables (optional).', 'Use un triturador para papas o una licuadora para machacar los vegetales (opcional).'),
  (17, 6, 'Add more broth to reduce thickness, if you want.', 'Añada más caldo si lo desea, para diluir la sopa en caso de que este muy espesa.'),
  (18, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (18, 2, 'Combine all ingredients (except the butter, margarine, or oil) in a large bowl and mix well.', 'Combine todos los ingredientes (excepto la mantequilla, margarina o aceite) en un tazón grande y mezcle bien.'),
  (18, 3, 'Coat inside of large baking dish with butter, margarine, or vegetable oil. Spoon mixture into dish. Bake 1 hour.', 'Cubra el interior de recipiente grande para hornear con mantequilla, margarina o aceite vegetal. Usando una cuchara, ponga la mezcla dentro del recipiente. Hornee por 1 hora.'),
  (19, 1, 'Combine beans and corn in a large pot.  Heat gently, 3-4 minutes.', 'Combine los frijoles y maíz en una olla grande. Caliente de manera ligera de 3-4 minutos.'),
  (19, 2, 'In a different pot, cook the broccoli pieces (steam, boil, or microwave).', 'En otra olla, cocine los pedazos de brócoli (al vapor, hirviéndolos o en un horno de microondas).'),
  (19, 3, 'Mix broccoli, beans, corn, and cooked meat.', 'Mezcle el brócoli, frijoles, maíz y pollo o carne ya cocidas.'),
  (19, 4, 'Top with grated cheese, chopped avocado, or sour cream (optional).', 'Cubra todo con el queso rayado, aguacate picado o crema agria (opcional).'),
  (20, 1, 'Heat oil or butter in a large pot.', 'Caliente el aceite o mantequilla en una olla grande.'),
  (20, 2, 'Add onions and cook until soft.', 'Agregue las cebollas y cocínelas hasta que se ablanden.'),
  (20, 3, 'Add carrots and broth and bring to a boil.', 'Agregue las zanahorias y el caldo (o agua) y déjelos hervir.'),
  (20, 4, 'Turn heat to low, cover pot and let simmer until carrots are tender when pierced, about 30 minutes.', 'Reduzca la temperatura a fuego lento, cubra la olla y deje que se siga cocinando unos 30 minutos, hasta que las zanahorias estén tiernas al pincharlas.'),
  (20, 5, 'Blend the carrot soup using a blender, hand mixer or potato masher.', 'Mezcle o bata la sopa usando una licuadora, batidora de mano o un triturador de papas.'),
  (20, 6, 'Season with salt or pepper, to taste.', 'Sazone al gusto con sal o pimienta.'),
  (20, 7, 'Serve warm or let soup cool and stir in yogurt for a cold soup.', 'Sirva la sopa caliente o déjela enfriar y agréguele el yogur para convertirla en una sopa refrescante.'),
  (20, 8, 'Do not freeze if you add yogurt.', 'Si le agregó yogur, no se debe congelar.'),
  (21, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (21, 2, 'Rub chicken parts with bits of margarine or butter, sprinkle lightly with salt and pepper.', 'Frote/talle las pechugas de pollo con la margarina (o mantequilla) y espolvoree las mismas con sal y pimienta.'),
  (21, 3, 'Combine carrots, potatoes, and onion in baking dish and half of the oil, mix together.', 'Ponga las zanahorias, papas y cebolla en un recipiente ideal para hornear, agregue la mitad del aceite y mézclelo con las verduras.'),
  (21, 4, 'Sprinkle the vegetables lightly with salt and pepper. You can also add garlic or other seasonings (optional).', 'Espolvoree las verduras de manera conservadora con sal y pimienta. Si usted desea, también puede añadir ajo u otros sazonadores (opcional).'),
  (21, 5, 'Coat inside of baking dish with oil; place chicken on top of the vegetables.', 'Unte la parte interna del recipiente para hornear con el aceite restante y acomode los pedazos de pollo por encima de las verduras.'),
  (21, 6, 'Cover tightly with cover or foil and bake for 60 minutes; uncover and bake 10­-15 minutes more.', 'Cubra el recipiente de una manera firme con una tapadera o con papel de aluminio y hornee por 60 minutos; después quítele el papel de aluminio (o tapadera) y hornee al descubierto de 10 a 15 minutos adicionales.'),
  (22, 1, 'Shred the carrots and chop the tomato. Mix together.', 'Desmenuce las zanahorias, pique el jitomate y mézclelos.'),
  (22, 2, 'Add juice and salt.', 'Agregue el jugo del limón y sal.'),
  (22, 3, 'Add hot sauce, to taste.', 'Agregue la salsa picante, al gusto.'),
  (22, 4, 'Add cilantro (optional).', 'Agregue el cilantro (opcional).'),
  (22, 5, 'Eat as a side dish or put in a sandwich or tortilla wrap.', 'Cómalo como un platillo suplementario, o en un emparedado o envuelto en una tortilla.'),
  (23, 1, 'Boil carrots briefly, until cooked but not soft (about 7 minutes).', 'Hierva la zanahorias de manera breve (aprox. por 7 minutos) hasta que estén cocidas pero evitando que se ablanden.'),
  (23, 2, 'Drain carrots. Place them in a shallow plastic or glass dish with a tight-fitting lid.', 'Vacíe poco a poco el agua en el fregadero. Coloque las zanahorias en un recipiente de plástico o de cristal poco profundo y que tenga una tapa ajustada.'),
  (23, 3, 'Sprinkle your favorite seasonings over the carrots.', 'Espolvoree sus especias de preferencia sobre las zanahorias.'),
  (23, 4, 'Pour in jalapeño peppers, including liquid. Let peppers sit on top of the carrots.', 'Vierta los chiles jalapeños, incluyendo el jugo sobre las zanahorias.'),
  (23, 5, 'Cover and leave in refrigerator at least 12 hours before using.', 'Cubra el recipiente y métalo en el refrigerador por 12 horas por lo menos.'),
  (23, 6, 'Stir and eat both carrots and peppers.', '¡Revuelva las zanahorias, chiles y listo!'),
  (24, 1, 'Slice carrots and put into the Crock­Pot.', 'Rebane las zanahorias y métalas en la olla "Crock­Pot".'),
  (24, 2, 'Sprinkle the carrots with brown sugar and a pinch of salt or pepper.', 'Espolvoree las zanahorias con azúcar morena y póngales un pizco de sal o pimienta.'),
  (24, 3, 'Add other seasonings, if you like.', 'Si lo desea, puede agregar otras especias.'),
  (24, 4, 'Pour the melted butter or margarine over the carrots.', 'Vierta la mantequilla o margarina derretida sobre las zanahorias.'),
  (24, 5, 'Toss all of the ingredients together.', 'Revuelva todos los ingredientes juntos.'),
  (24, 6, 'Cover with lid and cook on high for 3 hours.', 'Cubra la olla con la tapa y cocine a temperatura alta por 3 horas.'),
  (25, 1, 'Place all ingredients in saucepan and bring to a boil.', 'Vierta todos los ingredientes en un sartén y caliéntelos hasta que hiervan.'),
  (25, 2, 'Reduce heat to medium. Cover and simmer until carrots are crisp and tender, about 5-8 minutes.', 'Reduzca el fuego a media intensidad. Cubra el sartén y siga calentando el guisado de 5-8 minutos aproximadamente, hasta que las zanahorias estén tiernas y crujientes.'),
  (25, 3, 'Uncover and cook until juices are reduced, about 5 minutes.', 'Quite la tapa del sartén y siga cocinando las zanahorias por aproximadamente 5 minutos hasta que se reduzcan los jugos.'),
  (25, 4, 'Season with salt and pepper, to taste.', 'Sazone a su gusto con sal y pimienta.'),
  (26, 1, 'Bring water to boil. Add carrots and bring to a boil again. Cook until tender, but not soft, about 5 minutes. Drain and cool the carrots.', 'Ponga a hervir agua. Añada las zanahorias y deje que hierva el agua otra vez. Cocine hasta que las zanahorias estén tiernas (en aproximadamente 5 minutos) pero no blandas. Vierta el agua en el fregadero y deje enfriar las zanahorias.'),
  (26, 2, 'Mix tomato soup, sugar, vinegar, oil, Worcestershire sauce, mustard, salt and pepper.', 'Mezcle la sopa de jitomate, azúcar, vinagre, aceite, salsa inglesa (Worcestershire), mostaza, sal y pimienta.'),
  (26, 3, 'Combine carrots and onions and green peppers.', 'Combine las zanahorias, cebollas y los pimientos morrones.'),
  (26, 4, 'Pour the tomato soup mixture over the vegetables.', 'Vierta la mezcla de la sopa de jitomate sobre las verduras.'),
  (26, 5, 'Chill 8 hours. Stir once or twice.', 'Ponga a enfriar en el refrigerador por 8 horas. Revuelva una o dos veces.'),
  (27, 1, 'Peel the carrots and cut into slices.', 'Pele las zanahorias y córtelas en rebanadas.'),
  (27, 2, 'Bring water to a boil in a pot.', 'Ponga el agua a hervir en una olla.'),
  (27, 3, 'Add the carrots, cover the pot, and turn the heat down to medium-low.', 'Agregue las zanahorias, tape la olla y cueza a fuego medio bajo.'),
  (27, 4, 'Cook the carrots about 10 minutes, or until tender. Cook a shorter time if you prefer crisper carrots.', 'Cueza las zanahorias por 10 minutos, o hasta que estén tiernas. Reduzca el tiempo de cocinar si las prefiere un poco crujientes.'),
  (27, 5, 'Season with salt or pepper to taste.', 'Sazone con sal o pimienta al gusto.'),
  (29, 1, 'Heat the vegetable oil in a pan to very hot.', 'Caliente el aceite en un sartén hasta que quede muy caliente.'),
  (29, 2, 'Add the chopped garlic, carrots, and other vegetables (optional). Stir for a minute.', 'Agregue el ajo picado, zanahorias y cualquier otra verdura (opcional) que haya seleccionado. Agite por un minuto.'),
  (29, 3, 'Add pepper or other herbs or spices, and soy sauce.', 'Agregue la pimienta o cualquier otra especia y la salsa de soya.'),
  (29, 4, 'Keep stirring and moving the vegetables until they are tender, 3-5 minutes.', 'Siga agitando y moviendo las verduras hasta que estas estén tiernas, de 3-5 minutos.'),
  (29, 5, 'Add meat and stir for a minute', 'Añada la carne e incorpore todo al cocinar por un minuto más.'),
  (30, 1, 'Mix the carrots and raisins together.', 'Mezcle las zanahorias y pasas juntas.'),
  (30, 2, 'Add yogurt to moisten, as desired. Mix well.', 'Agregue yogur al gusto para darle una consistencia "mojada" a la mezcla. Revuelva bien.'),
  (30, 3, 'Add sugar and drained pineapple, if you like.', 'Agregue el azúcar y piña, si así lo desea.'),
  (30, 4, 'Chill.', 'Colóquela en el refrigerador.'),
  (31, 1, 'Preheat oven to 350 degrees.', 'Precalentar el horno a 350 grados.'),
  (31, 2, 'Put 2 cups of water in a pot and bring to a boil.', 'Ponga 2 tazas de agua a calentar hasta que hierva.'),
  (31, 3, 'Add the sliced carrots. Cover the pot and turn the heat down.', 'Agregue las rebabadas de zanahorias. Tape la olla y reduzca la intensidad del fuego.'),
  (31, 4, 'Cook for 5-7 minutes, or until tender.', 'Cueza de 5-7 minutos, o hasta que las zanahorias estén tiernas.'),
  (31, 5, 'Drain the carrots.', 'Cuele las zanahorias vertiendo el agua en el fregadero.'),
  (31, 6, 'Combine the cooked carrots and apples in an 8"x8" baking dish.', 'Combine las zanahorias ya cocidas y las manzanas en un recipiente para hornear de 8" X 8" pulgadas.'),
  (31, 7, 'Pour orange juice over the carrots and apples.', 'Vierta el jugo de naranja por encima de las zanahorias y manzanas.'),
  (31, 8, 'Mix the flour and brown sugar. Sprinkle the mixture over the carrots and apples; this will form a light crust.', 'Mezcle la harina y azúcar morena. Espolvoreé esta mezcla por encima de las zanahorias y manzanas; esto hará que se forme una leve corteza.'),
  (31, 9, 'Bake for 40 minutes.', 'Cocine en el horno por 40 minutos.'),
  (32, 1, 'Heat the oil in a frying pan.', 'Ponga a calentar el aceite en un sartén.'),
  (32, 2, 'Add the carrots and onions.', 'Agregue las zanahorias y cebollas.'),
  (32, 3, 'Cover and turn the heat down.', 'Tape el sartén y reduzca el fuego.'),
  (32, 4, 'Check to make sure the carrots are not sticking. Stir if necessary.', 'Vigile que las zanahorias no se vayan a pegar. Si es necesario, agite la mezcla de manera leve.'),
  (32, 5, 'Cook for 8-10 minutes, or until carrots and onions are tender.', 'Cueza de 8-10 minutos, o hasta que las zanahorias y cebollas queden tiernas.'),
  (32, 6, 'Add the parsley (optional) and serve.', 'Agregue el perejil (opcional) y sirva.'),
  (33, 1, 'Heat the oil in a frying pan.', 'Ponga a calentar el aceite en un sartén.'),
  (33, 2, 'Add the carrots and garlic and cook for 3 minutes.', 'Agregue las zanahorias y ajo y cueza por 3 minutos.'),
  (33, 3, 'Add juice and raisins to carrots and mix well.', 'Agregue el jugo (de limón o naranja) y las pasas a las zanahorias. Mezcle todo muy bien.'),
  (33, 4, 'Cover with lid and simmer 3 minutes or until the carrots are tender.', 'Cubra el sartén con una tapadera y hierva a fuego lento por 3 minutos, o hasta que las zanahorias se pongan tiernas.'),
  (33, 5, 'Remove from heat. Serve warm or cold.', 'Quite el sartén del fuego. Sirva tibias o frías.'),
  (34, 1, 'Heat the oil in a pot.', 'Ponga a calentar el aceite en una olla.'),
  (34, 2, 'Add the onion and the garlic and stir over medium heat until soft.', 'Agregue la cebolla y ajo y agite de manera leve a fuego medio hasta que se ablanden.'),
  (34, 3, 'Add celery, carrots, tomatoes (including the liquid), and water or broth.  Add seasonings.', 'Agregue el apio, zanahorias, jitomates (incluyendo el jugo), y agua o consomé. Añadir los sazones/condimentos.'),
  (34, 4, 'Bring to boil. Then, reduce heat, cover pot and simmer 10-15 minutes, or until the vegetables are tender.', 'Dejar que hierva. A continuación, reducir la temperatura, tapar la olla y siga cocinando a fuego lento de 10-15 minutos, o hasta que las verduras estén tiernas.'),
  (34, 5, 'Add beans (including liquid) and bring to boil again.', 'Añada los frijoles (incluyendo el jugo) y dejar que hierva otra vez.'),
  (35, 1, 'Put carrots and 3-4 large spoons of water or broth into a microwavable dish.', 'Ponga las zanahorias y 3-4 cucharadas grandes de agua o caldo en un recipiente apropiado para un horno de microondas.'),
  (35, 2, 'Cook about 6 minutes on high.', 'Cueza aproximadamente por 6 minutos a temperatura alta.'),
  (35, 3, 'Season with salt or pepper to taste.', 'Sazone con sal o pimienta al gusto.'),
  (36, 1, 'Put carrots and 3-4 large spoons of water or broth into a microwavable dish.', 'Ponga las zanahorias y 3-4 cucharadas grandes de agua o caldo (de pollo o verduras) en un recipiente apropiado para un horno de microondas.'),
  (36, 2, 'Cook about 6 minutes on high.', 'Cocine por aproximadamente 6 minutos a temperatura alta.'),
  (36, 3, 'Add a handful of raisins to carrots (optional).', 'Agregue un puñado de pasas a las zanahorias (opcional).'),
  (36, 4, 'Combine marmalade and orange juice. Microwave this mixture on high for 30 seconds.', 'Mezcle la mermelada con el jugo de naranja; cueza en el horno de microondas a temperatura alta por 30 segundos.'),
  (36, 5, 'Pour over cooked carrots and mix well.', 'Vierta sobre las zanahorias ya cocidas y mezcle bien.'),
  (37, 1, 'Place carrots into a steamer basket.', 'Ponga las zanahorias en un vaporizador de verduras plegable.'),
  (37, 2, 'Pour just enough water in a pot so that water will not touch the bottom of the steamer basket.', 'Vierta suficiente agua en una olla sin que esta valla a tocar el fondo del vaporizador y déjela hervir.'),
  (37, 3, 'Bring water to a boil.', 'Dejar que el agua hierva.'),
  (37, 4, 'Place steamer basket in pot and cover loosely.', 'Ponga lel vaporizador plegable dentro de la olla y tápela casi por completo.'),
  (37, 5, 'Steam for 12 minutes, or until tender.', 'Cueza al vapor por 12 minutos, o hasta que las zanahorias estén tiernas.'),
  (37, 6, 'Season with salt or pepper to taste.', 'Sazone con sal o pimienta al gusto.'),
  (38, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (38, 2, 'Toss carrots, sliced garlic, and a pinch of your favorite herbs or spices with a little vegetable oil.', 'Agite las zanahorias, ajos rebanados y una pizca de su especie o sazonador favorito con un poco de aceite vegetal.'),
  (38, 3, 'Lightly coat the inside of a baking pan with oil.', 'Unte el interior de un recipiente para hornear con el aceite vegetal restante.'),
  (38, 4, 'Put carrots and garlic into the baking pan.', 'Ponga las zanahorias y ajo dentro de la charola para hornear.'),
  (38, 5, 'Bake for about 30-45 minutes, stirring a few times, or until tender.', 'Hornee de 30-45 minutos o hasta que estén tiernas, revolviendo todo ligeramente algunas veces.'),
  (39, 1, 'If needed, cut away fat and loose bits of meat from the chicken. Wash chicken and pat dry. Coat chicken pieces lightly with oil. Season with salt, pepper, or your favorite seasonings.', 'Si es necesario, quitar la grasa o pedacitos sueltos de las piezas de pollo. Lavar el pollo y secar suavemente. Cubrir de manera leve las piezas de pollo con aceite. Condimentar con sal, pimienta, o cualquiera de sus condimentos favoritos.'),
  (39, 2, 'In a large pot, heat 1 large spoon of oil over medium-high heat.', 'En una olla amplia, calentar 1 cucharada grande de aceite a fuego medio-alto.'),
  (39, 3, 'Place chicken pieces in pot. Cook until golden brown on both sides, about 10-12 minutes.', 'Colocar las piezas de pollo en la olla. Cocinar de 10-12 minutos o hasta que las piezas estén doraditas por ambos lados.'),
  (39, 4, 'Add onion and celery. Reduce heat to low, cover, and cook 20 minutes, stirring occasionally.', 'Agregar la cebolla y apio. Reducir el fuego, cubrir y cocinar por 20 minutos, revolviendo todo ocasionalmente.'),
  (39, 5, 'Add carrots and almost 2 cups of water or broth. Stir in rice.', 'Agregar las zanahorias, agua o consomé de pollo. Añada el arroz sin dejar de revolver.'),
  (39, 6, 'Bring to a boil, then reduce heat to low. Cover and cook until rice absorbs all of the liquid, about 30-40 minutes. Let stand covered for about 10 minutes before serving.', 'Dejar que hierva y reduzca a fuego lento. Cubrir la olla y siga cocinando hasta que el arroz absorba todo el liquido, aproximadamente 30-40 minutos. Apague el fuego y deje la olla cubierta por otros 10 minutos antes de servir.'),
  (40, 1, 'In a large pan, heat margarine or butter, and oil over medium heat.', 'En un sartén grande, caliente la margarina o mantequilla, y el aceite a fuego medio.'),
  (40, 2, 'Add garlic, onion, brown sugar, and salt and pepper.', 'Añada ajo, cebolla, azúcar marrón, y sal y pimienta.'),
  (40, 3, 'Add cabbage and cook until the cabbage starts to soften, about 3-5 minutes.', 'Añada repollo y cocine hasta que el repollo se empiece a suavisar, cerca de 3-5 minutos.'),
  (40, 4, 'Reduce heat to medium-low and stir in vinegar.', 'Reduzca el fuego a medio-bajo y agregue el vinagre.'),
  (40, 5, 'Cook, stirring often, for approximately 5 minutes, or more if cabbage is still too crunchy.', 'Cocine, revolviendo con frecuencia, por aproximadamente 5 minutos, o más si el repollo está todavía muy crujiente.'),
  (41, 1, 'Heat oil in pan, and cook beef and onion together. Drain off excess oil. Add salt and pepper.', 'Caliente aceite en un sartén, y cocine la carne y la cebolla juntas. Escurra el exceso de aceite. Añada sal y pimienta.'),
  (41, 2, 'Stir rice into beef mixture.', 'Vierta el arroz en la mezcla de carne.'),
  (41, 3, 'Place chopped cabbage in a large casserole dish.', 'Coloque el repollo picado en un recipiente para hornear grande.'),
  (41, 4, 'Spread beef, onion and rice mixture over the cabbage.', 'Esparsa la carne, cebolla y la mezcla de arroz sobre el repollo.'),
  (41, 5, 'Pour and spread tomato soup over top of beef mixture.', 'Vacíe y esparza la sopa de jitomate por encima de la mezcla de la carne.'),
  (41, 6, 'Fill soup can with water and pour evenly over casserole.', 'Llene la lata de sopa con agua y vacíe de manera uniforme sobre el resto de los ingredientes ya en el recipiente.'),
  (41, 7, 'Cover and bake one hour at 350 degrees.', 'Cubra y hornee por una hora a 350 grados.'),
  (41, 8, 'To make in a toaster oven, cut the recipe in half.', 'Para preparar en un horno tostador, divida la receta por la mitad.'),
  (42, 1, 'Combine all ingredients.', 'Combine todos los ingredientes.'),
  (42, 2, 'Chill for 2 hours.', 'Enfríe por 2 horas.'),
  (42, 3, 'Serve with tortilla chips, pita bread, tortillas, or cut fresh vegetables.', 'Sirva con totopos (chips) de maíz, pan pita, tortillas, o vegetales frescos y cortados.'),
  (43, 1, 'Heat oil and margarine or butter in large saucepan.', 'Caliente aceite y margarina o mantequilla en un sartén grande.'),
  (43, 2, 'Add cabbage, salt, and pepper and stir on low heat for 5 minutes.', 'Añada repollo, sal, y pimienta y revuelva a fuego lento por 5 minutos.'),
  (43, 3, 'Add broth and bring to a boil.', 'Añada caldo y ponga a hervir.'),
  (43, 4, 'Cover and simmer over medium-low heat, stirring often for about 15 minutes, until cabbage is tender.', 'Cubra y deje que hierva lentamente a temperatura media-baja, revolviendo con frecuencia por casi 15 minutos, hasta que el repollo esté tierno.'),
  (43, 5, 'Increase to medium heat. Uncover and let juices reduce to about half.', 'Suba el fuego a temperatura mediana, destape el sartén y deje que los jugos se reduzcan hasta casi la mitad.'),
  (44, 1, 'In large pan, heat vegetable oil.', 'En un sartén grande, caliente el aceite vegetal.'),
  (44, 2, 'Cook onions, celery and carrots until tender.', 'Cocine el apio, las cebollas y zanahorias hasta que estén tiernas.'),
  (44, 3, 'Add cabbage, sugar, salt, pepper, and tomatoes.', 'Añada repollo, azúcar, sal, pimienta, y jitomates.'),
  (44, 4, 'Bring to a boil, reduce heat to medium-low.', 'Deje que hierva, reduzca la intensidad del fuego a medio-bajo.'),
  (44, 5, 'Cover and cook 5-8 minutes.', 'Cubra y cocine 5-8 minutos.'),
  (45, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (45, 2, 'In large bowl, mix together the cabbage, mushrooms, peppers, carrots, and celery--or whatever combination of vegetables you choose--and salt and pepper.', 'En un recipiente grande y hondo, mezcle conjuntamente el repollo, hongos, pimientos, zanahorias, y apio, o cualquier otra combinación de vegetales que usted escoja, así como sal y pimienta.'),
  (45, 3, 'Coat inside of large casserole dish with oil or non-fat spray.', 'Cubra/bañe la parte interior de un recipiente grande para hornear con aceite o un rociador de aceite de bote sin grasa.'),
  (45, 4, 'Add vegetables to casserole dish.', 'Añada los vegetales al recipiente.'),
  (45, 5, 'Pour chicken broth or water over the vegetables.', 'Vierta el caldo de pollo o agua sobre los vegetales.'),
  (45, 6, 'Cover with foil and bake for 45 minutes.', 'Cubra con papel aluminio y hornee por 45 minutos.'),
  (45, 7, 'Remove from oven, uncover, and add the cheese.', 'Saque del horno, descubra, y añada al queso.'),
  (45, 8, 'Bake, uncovered, for another 5-10 minutes, until cheese melts.', 'Hornee al descubierto, por otros 5-10 minutos, hasta que el queso se derrita.'),
  (45, 9, 'To make in a toaster oven, cut the recipe in half.', 'Para preparar en un horno tostador, divida la receta por la mitad.'),
  (46, 1, 'In large pot, cook onion in margarine, butter, or oil until tender.', 'En una olla grande, cocine la cebolla en margarina, mantequilla o aceite hasta que esta se ponga tierna.'),
  (46, 2, 'Add all other ingredients.', 'Añada todos los otros ingredientes.'),
  (46, 3, 'Cover and bring to a boil.  Reduce heat and simmer for 15-20 minutes.', 'Tapar y dejar que hierva. Reducir la temperatura y cocinar a fuego lento de 15-20 minutos.'),
  (47, 1, 'Pre-heat oven to 350 degrees.', 'Pre caliente el horno a 350 grados.'),
  (47, 2, 'Rub chicken pieces with salt and pepper.', 'Frote las partes del pollo con sal y pimienta.'),
  (47, 3, 'Heat oil in hot pan; add chicken and half the garlic and cook until chicken is no longer pink, about 15 minutes; remove chicken from pan.', 'Ponga el aceite a calentar en un sartén ya caliente; añada el pollo y la mitad del ajo y cocine aproximadamente por 15 minutos, hasta que el pollo deje de estar rosado. Saque el pollo del sartén.'),
  (47, 4, 'Add onion slices to pan and cook until they are starting to get soft, a few minutes more.', 'Añada las tajadas de cebolla sartén y cocine por unos minutos más, hasta que empiecen a suavizarse.'),
  (47, 5, 'Combine cabbage, apples, onion, and remaining garlic in a mixture.', 'Combine repollo, manzanas, cebolla, y el resto del ajo en una mezcla.'),
  (47, 6, 'Spread a layer of half the mixture in casserole dish; add chicken on top.', 'Extienda una capa de la mitad de la mezcla en un recipiente hondo para hornear; añada el pollo por encima.'),
  (47, 7, 'Sprinkle some sugar, salt and pepper over chicken.', 'Espolvoree un poco de azúcar, sal y pimienta sobre el pollo.'),
  (47, 8, 'Spread another layer of the cabbage mixture over this.', 'Extienda otra capa con la mezcla de repollo sobre esto.'),
  (47, 9, 'Sprinkle rest of sugar, salt and pepper.', 'Espolvoree el resto de azúcar, sal y pimienta.'),
  (47, 10, 'Add chicken broth evenly.', 'Añada el caldo de pollo de manera uniforme.'),
  (47, 11, 'Dot with margarine or butter.', 'Salpique con margarina o mantequilla.'),
  (47, 12, 'Cover casserole dish with aluminum foil; bake for 30 minutes.', 'Cubra el recipiente con papel aluminio; hornee por 30 minutos.'),
  (47, 13, 'Uncover, and bake another 15 minutes.', 'Quítele el papel de aluminio, y hornee por otros 15 minutos.'),
  (48, 1, 'Mix all the vegetables in a bowl.', 'Mezcle todos los vegetales en un recipiente hondo.'),
  (48, 2, 'Combine lemon juice, sugar, and salt.', 'Combine jugo de limón, azúcar, y sal.'),
  (48, 3, 'Toss vegetables, while adding the lemon juice mixture.', 'Agite los vegetales, mientras añade la mezcla de jugo de limón.'),
  (48, 4, 'Cover bowl tightly with plastic and refrigerate for 2-4 hours before serving.', 'Cubra bien el recipiente hondo con plástico y refrigere por 2­4 horas antes de servir.'),
  (49, 1, 'Boil water in a large pot.', 'Hierva agua en una olla grande.'),
  (49, 2, 'Drop wedges of cabbage into the boiling water.', 'Vierta los trozos de repollo sobre el agua hirviendo.'),
  (49, 3, 'Cook uncovered for 10­-15 minutes.', 'Cocine sin tapar por 10­-15 minutos.'),
  (49, 4, 'Drain thoroughly. Press towel over cabbage to remove excess moisture.', 'Cuele el repollo y usando una toallita, haga presión sobre el repollo para remover el exceso de humedad.'),
  (49, 5, 'Combine with oil, salt, or pepper, and very small amount of vinegar or lemon juice to bring out flavors.', 'Combine con aceite, sal o pimienta, y una muy pequeña cantidad de vinagre o jugo de limón para acentuar los sabores.'),
  (50, 1, 'Cut the cabbage into 8 to 10 wedges, removing white core.', 'Corte el repollo en 8 a 10 trozos grandes, quitándole el centro blanco.'),
  (50, 2, 'Place in a microwave safe dish with 2 large spoonfuls of liquid (water or stock or apple juice).', 'Coloque bien en un recipiente para microondas con 2 cucharadas de agua, caldo o jugo de manzana).'),
  (50, 3, 'Cover and microwave at normal power for 5-7 minutes.', 'Cubra y caliente en el microondas a temperatura normal por 5-7 minutos.'),
  (51, 1, 'Heat vegetable oil in a large pan or wok over medium-high heat.', 'Caliente aceite vegetal en un sartén grande o wok a fuego medio-alto.'),
  (51, 2, 'Add vegetables (except cabbage and garlic). Cook 2 to 3 minutes, stirring quickly and constantly.', 'Añada vegetales (excepto repollo y ajo). Cocine de 2­-3 minutos; agitando rápido y constantemente.'),
  (51, 3, 'Add chicken pieces, stir for 2-3 minutes (optional).', 'Añada los pedacitos de pollo, y cocine de 2-3 minutos (opcional).'),
  (51, 4, 'Add cabbage and stir until the cabbage is tender.', 'Añada repollo y siga agitando hasta que el repollo esté tierno.'),
  (51, 5, 'Add garlic and soy sauce to taste.', 'Añada ajo y salsa de soya al gusto'),
  (51, 6, 'Cook for one more minute.', 'Cocine por un minuto más.'),
  (52, 1, 'Heat margarine, butter, or oil in a frying pan.', 'Caliente margarina, mantequilla o aceite en un sartén'),
  (52, 2, 'Add onions and cook about 2 minutes.', 'Añada cebollas y cocine por 2 minutos.'),
  (52, 3, 'Add cabbage, salt, and pepper to pan and cook until cabbage is tender, about 5 minutes; stir often during cooking.', 'Añada repollo, sal, y pimienta al sartén y cocine hasta que el repollo esté tierno, casi 5 minutos; agite constantemente mientras se cocina.'),
  (53, 1, 'Cut cabbage into wedges or slices, and place in steamer basket.', 'Corte el repollo en trozos o tajadas, y coloque en un vaporizador plegable o canastita para cocinar a vapor.'),
  (53, 2, 'Pour just enough water in a pot, so that water will not touch bottom of steamer basket. Bring water to a boil. Place basket in pot and cover.', 'Vierta un poco de agua en una olla, sin que esta vaya a tocar el fondo del vaporizador. Ponga el agua a hervir. Una vez que el agua este hirviendo, coloque el vaporizador en la olla y tápela.'),
  (53, 3, 'Cook large wedges for 15 minutes; smaller wedges or slices will take about 10 minutes.', 'Si los trozos o tajadas son grandes, cocine por 15 minutos. Si son chicos, entoncestomarán casi 10 minutos solamente.'),
  (54, 1, 'Heat pot of lightly salted water to boiling. Add noodles and cook according to package directions. Drain noodles.', 'Ponga a hervir una olla con agua ligeramente salada. Añada fideos y cocine de acuerdo a las indicaciones del paquete. Escurra los fideos.'),
  (54, 2, 'Heat butter, margarine, or vegetable oil in a frying pan. Add cabbage, salt, and pepper, and cook 10­-15 minutes.', 'Caliente mantequilla, margarina o aceite en un sartén. Añada repollo, sal y pimienta y cocine 10­-15 minutos.'),
  (54, 3, 'Combine cooked noodles and cabbage in a bowl. Toss with grated cheese and pinch of pepper flakes or other seasonings.', 'Combine los fideos ya cocidos y el repollo en un recipiente hondo. Añada el queso rallado y una pizca de hojuelas de chile rojo u otros condimentos y agite todo junto.'),
  (55, 1, 'Combine all ingredients.', 'Combine todos los ingredientes.'),
  (55, 2, 'Keep refrigerated until ready to serve.', 'Manténgala refrigerada hasta que esté lista para servir.'),
  (56, 1, 'Heat the margarine, butter, or oil in a pan.', 'Caliente margarina, mantequilla o aceite en una cacerola.'),
  (56, 2, 'Add onion and cook for one minute.', 'Añada cebolla y cocine por un minuto.'),
  (56, 3, 'Add cabbage and cook for 3 to 5 minutes.', 'Añada repollo y cocine de 3­-5 minutos.'),
  (56, 4, 'Add apples, salt, pepper, and brown sugar.', 'Añada manzanas, sal, pimienta, y azúcar marrón.'),
  (56, 5, 'Cook for 5 minutes, stirring.', 'Cocine por 5 minutos, removiendo.'),
  (56, 6, 'Add the water and vinegar and cook, covered, over low heat for about 30 minutes. Stir occasionally.', 'Añada el agua y vinagre y cocine, cubierto, a fuego bajo por casi 30 minutos. Remueva ocasionalmente.'),
  (57, 1, 'In a large pan, heat the oil.', 'En un sartén grande, caliente aceite.'),
  (57, 2, 'Add potatoes and cook over medium heat until lightly browned.', 'Agregue las papas y cocine a fuego medio hasta que estas estén levemente doraditas.'),
  (57, 3, 'Add the cabbage, onions, and water or broth.', 'Añada el repollo, cebollas, y agua o consomé.'),
  (57, 4, 'Season with red pepper flakes or salt or pepper or other seasonings.', 'Sazone con hojuelas de chile rojo o sal o pimienta u otros condimentos.'),
  (57, 5, 'Cover and cook over low heat until the potatoes are tender about 10 to 15 minutes; stir often.', 'Cubra y cocine a fuego bajo hasta que las papas estén tiernas por casi 10 a 15 minutos; agitando con frecuencia.'),
  (57, 6, 'To prevent the vegetables from browning, reduce the heat or add more water or broth.', 'Para prevenir que los vegetales se pongan cafés, reduzca el calor o añada más agua o caldo.'),
  (58, 1, 'Combine all ingredients in Crock­Pot and mix well.', 'Combine todos los ingredientes en la olla eléctrica "Crock-Pot" y mezcle bien.'),
  (58, 2, 'Cover and cook over low heat for 6-8 hours.', 'Cubra y cocine a fuego bajo por 6-8 horas.'),
  (58, 3, 'Mix well before serving.', 'Mezcle bien antes de servir.'),
  (59, 1, 'Cut the cabbage in half and remove the woody stem at the bottom (see photo). Cut the cabbage into thin strips.', 'Corte el repollo por la mitad y quítele el tallo/centro duro (ver foto). Después corte las mitades en tiritas delgadas.'),
  (59, 2, 'Place the peanut butter and greens in a blender or food processor. Turn on low speed.', 'Coloque la crema de cacahuate y las espinacas en una licuadora o un procesador de alimentos. Préndalo a velocidad baja.'),
  (59, 3, 'Slowly pour in oil, in a thin stream. Use enough oil to make a smooth sauce. In between blending, you may need to use the handle of a spoon to push the ingredients together so that they blend smoothly.', 'Lentamente vierta el aceite por medio de un chorrito delgado. Use suficiente aceite para hacer una salsa/mezcla suave. Durante el proceso de mezclar todo junto, es muy posible que tenga que usar el mango de una cuchara (con mucho cuidado) para "empujar y mantener" los ingredientes juntos para que formen una mezcla suavecita.'),
  (59, 4, 'Turn off the food processor and taste. Add salt if needed.', 'Apague la licuadora o procesador de alimentos y pruebe la salsa/mezcla. Agregue sal, si es necesario.'),
  (59, 5, 'Place cabbage and cooked noodles in a large mixing bowl. Add sauce and mix well.', 'Coloque el repollo y los fideos ya cocidos, en un recipiente hondo. Vierta la salsa/mezcla y revuelva bien.'),
  (59, 6, 'Stir in cooked meat, if you wish.', 'Añada sin dejar de revolver, la carne o pollo, si lo desea.'),
  (60, 1, 'In a bowl, mix beef, cabbage and onion.', 'En un recipiente hondo, mezcle la carne, repollo y cebolla.'),
  (60, 2, 'Put this mixture in a pan and cook over medium heat until meat is browned. Drain any excess liquid.', 'Vierta esta mezcla en un sartén y cocine a fuego medio hasta que la carne se vea doradita. Escurra/drene el liquido.'),
  (60, 3, 'Mix together the ketchup, brown sugar, garlic powder, and mustard.', 'En un recipiente separado, mezcle la salsa de ketchup, la azúcar morena, el ajo en polvo y la mostaza.'),
  (60, 4, 'Stir in ketchup mixture. Cook over medium heat for 30 minutes or until cabbage is as tender as you want. Stir occasionally. taste and season with salt and pepper, if desired.', 'Añada sin dejar de revolver la mezcla del ketchup al sartén. Cocine a fuego medio por 30 minutos o hasta que el repollo este tan tierno como usted lo deseé. Revuelva/agite ocasionalmente. Pruebe y condimente con sal o pimienta a su gusto, si así lo desea.'),
  (60, 5, 'Serve on hamburger buns.', 'Sírvalo en los panes para hamburguesas'),
  (61, 1, 'Place the cauliflower into a steamer basket.', 'Coloque la coliflor en un vaporizador plegable o canastita'),
  (61, 2, 'Pour just enough water in a pot so that water will not touch the bottom of the steamer basket.', 'Ponga suficiente agua en una olla pero evite que el agua vaya a tocar la parte de abajo de la vaporera.'),
  (61, 3, 'Bring water to a boil. Place steamer basket in pot and cover.', 'Una vez que el agua este hirviendo, coloque con mucho cuidado la vaporera dentro del la olla y cúbrala.'),
  (61, 4, 'Steam for 3-7 minutes or until just tender.', 'Cocine la coliflor al vapor de 3-­7 minutos o hasta que la coliflor se sienta tierna al tocarla con un tenedor.'),
  (62, 1, 'Fill a pot halfway with water and bring to a boil.', 'Llene un olla de agua hasta la mitad y pórgala a hervir'),
  (62, 2, 'Add the cauliflower to boiling water and cook until tender, about 5 to 8 minutes.', 'Agregue la coliflor a el agua hirviendo y cocine de 5 a 8 minutos o hasta que la coliflor este tierna.'),
  (62, 3, 'Drain the cauliflower.', 'Cuele el agua.'),
  (62, 4, 'Heat butter or margarine in a pan with a pinch of salt, pepper, or favorite seasonings.', 'Caliente la mantequilla o margarina en un sartén, agréguele una pizca de sal, pimienta o su sazón/condimento preferido.'),
  (62, 5, 'Pour this mixture over the cauliflower and stir gently to coat the pieces.', 'Vierta esta mezcla por encima de la coliflor y bata de una manera suave hasta revertirlo completamente.'),
  (63, 1, 'Place the cauliflower in a microwaveable dish.', 'Ponga la coliflor (cortada en pedazos) en un recipiente apropiado para el horno de microondas.'),
  (63, 2, 'Add ¼ cup water and cover with lid or plastic wrap.', 'Agregue ¼ de una taza de agua y cubra el recipiente con envoltura de plástico.'),
  (63, 3, 'Microwave on high for 3 minutes and then let stand for 2 more minutes.', 'Cocínelo en el horno de microondas en temperatura alta por 3 minutos y déjelo reposar por 2 minutos adicionales.'),
  (63, 4, 'Heat butter or margarine in a pan with a pinch of salt, pepper, or favorite seasonings.', 'Caliente la mantequilla o margarina en un sartén, agréguele una pizca de sal, pimienta o su sazón/condimento preferido.'),
  (63, 5, 'Pour this mixture over the cauliflower and stir gently to coat the pieces.', 'Vierta esta mezcla por encima de la coliflor y bata de una manera suave hasta revertirlo completamente.'),
  (64, 1, 'Heat oil in a pan.', 'Ponga el aceite a calentar en un sartén.'),
  (64, 2, 'Add garlic or onions and cook for a few seconds on medium heat.', 'Agregue el ajo o cebollas (o ambos) picaditos y cocínelos a fuego medio por solo unos segundos.'),
  (64, 3, 'Add the cauliflower and cook for 3-4 minutes.', 'Agregue la coliflor y cocínelo de 3­-4 minutos.'),
  (64, 4, 'Add salt and pepper to taste.', 'Agregue sal y pimienta al gusto.'),
  (65, 1, 'In a large bowl, mix cauliflower, carrots and celery.', 'Usando recipiente grande, mezcle/revuelva la coliflor, zanahorias y apio.'),
  (65, 2, 'To make salad dressing, mix all salad dressing ingredients.', 'Para hacer el aderezo, mezcle todos los ingredientes mencionados arriba en un recipiente separado.'),
  (65, 3, 'Pour dressing over vegetables and mix well.', 'Vierta el aderezo sobre las verduras y revuélvalo todo muy bien.'),
  (65, 4, 'Cover and refrigerate for 30 minutes.', 'Cubra el recipiente y métalo al refrigerador por 30 minutos.'),
  (66, 1, 'Steam or boil cauliflower and onions until tender, about 3 to 5 minutes. Drain.', 'Cocine la coliflor y las cebollas ya sea hirviéndolas o al vapor de 3­-5 minutos o hasta que estén tiernas al toque. Cuele el agua.'),
  (66, 2, 'Place the cauliflower and onions in a baking dish.', 'Coloque la coliflor y cebollas en un recipiente apropiado para hornear.'),
  (66, 3, 'Add peas and cooked chicken (optional).', 'Agregue los chíncharos y el pollo cocido (opcional).'),
  (66, 4, 'Mix soup with milk in a separate bowl.', 'Mezcle la sopa con la leche en un tazón separado.'),
  (66, 5, 'Pour soup mixture over cauliflower and stir. Sprinkle with cheese.', 'Vacíe esta mezcla por encima de la coliflor y cebollas y agite hasta que se integren todos los ingredientes. Espolvoree con queso.'),
  (66, 6, 'Bake at 350 degrees for 25 to 30 minutes.', 'Coloque el recipiente en el horno y cocine a 350 grados de 25 a 30 minutos.'),
  (67, 1, 'Boil or steam cauliflower and garlic until tender.', 'Ponga a hervir la coliflor y ajo, o cocínelos al vapor hasta que estén tiernos al toque.'),
  (67, 2, 'Drain off liquid and mash cauliflower and garlic with a potato masher or a blender.', 'Cuele el agua y machaque la coliflor y ajo usando un machacador de papas o licuadora.'),
  (67, 3, 'Add yogurt, margarine or butter, and salt and pepper.', 'Agregue el yogur, el aceite vegetal y la sal y pimienta.'),
  (67, 4, 'Mix thoroughly.', 'Mezcle todos los ingredientes hasta que queden bien integrados.'),
  (67, 5, 'Add any other favorite seasoning.', 'Agregue su sazonador-condimento preferido.'),
  (68, 1, 'Bring a large pot of water, with a pinch of salt, to a boil. Add cauliflower pieces and cook, covered, for 1-2 minutes. Then, add broccoli pieces and cook, covered, for another 1-2 minutes. Drain and immediately put pieces in a bowl of cold water and ice cubes to stop the cooking. Drain when vegetables are cool to the touch.', 'Ponga una olla con agua a hervir y agréguele una pizca de sal. Añada los pedazos de coliflor, cubra la olla y cocine de 1-2 minutos. A continuación, agregue los pedazos de brócoli, vuelva a cubrir la olla, y cocine por 1-2 minutos más. Vacíe el agua e inmediatamente ponga los pedazos de coliflor y brócoli en un recipiente hondo con agua fría y hielos para evitar que se sigan cocinando. Vacíe el agua una vez que las verduras estén frías al tocarlas.'),
  (68, 2, 'Combine cauliflower, broccoli (optional), apple, and celery.', 'Combine/mezcle la coliflor, el brócoli, el apio y las manzanas.'),
  (68, 3, 'Mix mayonnaise, or yogurt and sugar in a small bowl to make a dressing.', 'Mezcle la mayonesa o yogur y azúcar en un tazón pequeño, para preparar un "aderezo".'),
  (68, 4, 'Add dressing to the vegetable and fruit and mix well.', 'Agregue aderezo a las verduras y fruta y mezcle hasta que todo quede bien integrado.'),
  (68, 5, 'For a really crisp salad, use raw cauliflower and broccoli pieces. Or, you may place pieces in a pot of boiling, lightly salted water. Cook them for 5 minutes, drain, and put pieces in ice cubes and water to chill.', 'Para una ensalada realmente crujiente, use pedazos de coliflor y brócoli crudos. O, usted podría poner los pedazos en una olla con agua hirviendo con un poco de sal. Cocine por 5 minutos, cuele todo, y ponga a enfriar en agua con hielo.'),
  (68, 6, 'Chill finished salad, if desired, approximately 30 minutes.', 'Ponga la ensalada ya preparada en el refrigerador si lo desea, por aproximadamente 30 minutos.'),
  (69, 1, 'Boil or steam cauliflower and broccoli until tender, drain.', 'Ponga a hervir la coliflor y el brócoli o cocínelos al vapor hasta que estén tiernos al toque. Cuele el agua.'),
  (69, 2, 'In a small dish, combine water and chili powder.', 'En un recipiente pequeño, combine el polvo de chile y el agua.'),
  (69, 3, 'Heat the oil in a fry pan. Add chicken. Cook until golden brown. Add ginger and garlic (optional).', 'Caliente el aceite en un sartén. Agregue el pollo. Cocine hasta dorarse. Agregue jengibre y ajo (opcional).'),
  (69, 4, 'Cook for 30 seconds; do not let the garlic get brown.', 'Cocine por 30 segundos; no deje que el ajo se ponga café.'),
  (69, 5, 'Add the carrot (optional) and cook for 1 minute.', 'Añada las zanahorias (opcional) y cocine por un minuto.'),
  (69, 6, 'Add the cauliflower and broccoli, toss and stir for about 2 minutes.', 'Agregue la coliflor y el brócoli, revuelva y mezcle todo por 2 minutos aproximadamente.'),
  (69, 7, 'Add water and chili powder to pan, stir until mixed.', 'Agregue la mezcla de agua y chile en polvo al sartén y agite todos los ingredientes hasta que queden bien integrados.'),
  (69, 8, 'Add soy sauce and meat pieces (optional).', 'Agregue la salsa de soya y los trozos de carne (opcional).'),
  (69, 9, 'Add green onion (optional).', 'Agregue la cebollita verde rebanada (opcional).'),
  (69, 10, 'Add salt and pepper to taste.', 'Añada sal y pimienta al gusto.'),
  (70, 1, 'Steam or boil the cauliflower until tender, then drain.', 'Ponga a hervir la coliflor o cocínela al vapor hasta que esté tierna. Cuele el agua.'),
  (70, 2, 'Put the tomatoes, peppers, onion, and sugar in a fry pan.', 'Ponga los jitomates, chiles, cebolla y azúcar en un sartén.'),
  (70, 3, 'Peel thin strips of lime and add to the tomato mixture.', 'Pele tiritas delgadas del limón y agrégueselas a la mezcla de los jitomates.'),
  (70, 4, 'Cut the lime in half and squeeze the juice from both halves into the tomato mixture.', 'Corte el limón a la mitad y exprima el jugo de ambas mitades dentro de la mezcla de los jitomates.'),
  (70, 5, 'Heat gently, until onion softens.', 'Cocine a fuego lento hasta que la cebolla se ablande.'),
  (70, 6, 'Add cauliflower.', 'Agréguele la coliflor.'),
  (70, 7, 'Mix well together.', 'Revuelva los ingredientes hasta que estos estén bien integrados.'),
  (70, 8, 'Add cheese (optional).', 'Agregue el queso (opcional) si lo desea.'),
  (71, 1, 'Spray Crock­Pot with nonstick cooking spray, or coat with vegetable oil.', 'Rocíe la parte interior de la olla "Crock­Pot" con un rocío antiadherente para cocinar, o unte una capa de aceite vegetal.'),
  (71, 2, 'Combine all ingredients in Crock­Pot. Stir well.', 'Vacíe y Combine todos los ingredientes en la olla mezclándolos bien.'),
  (71, 3, 'Cook on low for 4 hours.', 'Cocine por 4 horas a una temperatura baja.'),
  (72, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (72, 2, 'Oil a baking sheet.', 'Unte aceite a una charola o bandeja para hornear.'),
  (72, 3, 'Put cauliflower slices on baking sheet.', 'Coloque las rebanadas de coliflor en la bandeja para hornear.'),
  (72, 4, 'Bake until cauliflower is slightly softened, about 10 minutes.', 'Hornee la coliflor hasta que la misma se ablande, aproximadamente 10 minutos.'),
  (72, 5, 'Melt margarine or butter in small pan over medium heat.', 'Derrita la margarina o mantequilla en un sartén a fuego medio.'),
  (72, 6, 'Add lemon juice, mustard and lemon peel (optional).', 'Añada el jugo de limón, mostaza y corteza de limón (opcional).'),
  (72, 7, 'Spoon mustard-lemon sauce over cauliflower slices.', 'Usando una cuchara, vacíe el aderezo de limón y mostaza por sobre las rebanadas de coliflor.'),
  (72, 8, 'Bake 10 minutes longer then serve.', 'Hornee por 10 minutos adicionales y después sírvalo.'),
  (73, 1, 'Heat a pan. Add oil and cook onions and garlic until tender.', 'Caliente un sartén. Agréguele aceite y cocine la cebolla y el ajo hasta que estos estén tiernos.'),
  (73, 2, 'Steam or boil the cauliflower and broccoli, for 5-7 minutes.', 'Cocine la coliflor y el brócoli ya sea hirviéndolos o al vapor de 5­-7 minutos.'),
  (73, 3, 'Put the cauliflower, broccoli, and onions in a dish.', 'Coloque la coliflor, el brócoli y las cebollas en un recipiente.'),
  (73, 4, 'Heat spaghetti sauce in a pan and pour over cauliflower mixture and mix well.', 'Caliente la salsa de jitomate tipo "spaghetti" en un sartén y vacíe sobre la mezcla de coliflor, brócoli y cebollas y revuélvalos bien.'),
  (73, 5, 'Add cooked noodles (optional), and mix.', 'Agregue los tallarines/fideos ya cocidos y mezcle todo de nuevo (opcional).'),
  (73, 6, 'Season with salt and pepper to taste.', 'Sazone al gusto con sal y pimienta.'),
  (74, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (74, 2, 'Put oil in a pan and heat.', 'Vacíe el aceite en un sartén y póngalo a calentar.'),
  (74, 3, 'Sprinkle salt or pepper on chicken pieces. Place chicken in pan and stir until brown on all sides, about 5 minutes.', 'Espolvoree los pedazos de pollo con sal o pimienta. Ponga los pedazos de pollo en un sartén y agítelos hasta que se doren por todos lados, en aproximadamente 5 minutos.'),
  (74, 4, 'Put cauliflower in pan, add 1 cup water; cover and cook on medium for 5 minutes.', 'Ponga la coliflor en el sartén y agregue 1 taza de agua; cubra el sartén y cocine a fuego medio por 5 minutos.'),
  (74, 5, 'Drain off the liquid.', 'Cuele el líquido del sartén.'),
  (74, 6, 'Add bell pepper and onion to pan and cook for 1 minute.', 'Añada el pimiento morrón y la cebolla, y cocine por 1 minuto.'),
  (74, 7, 'Add sour cream and half of cheese to the chicken-cauliflower mixture.', 'Agréguele la crema agria o yogur y la mitad del queso a la mezcla de pollo y coliflor.'),
  (74, 8, 'Put in greased baking dish.', 'Vierta todos los ingredientes del sartén en un recipiente para hornear el cual haya sido engrasado previamente.'),
  (74, 9, 'Bake, uncovered, at 400 degrees for 15 minutes.', 'Hornee al descubierto por 15 minutos a una temperatura de 400 grados.'),
  (74, 10, 'Take out of oven, top with remaining cheese and crushed cornflakes.', 'Saque del horno y cubra la mezcla con las hojuelas de maíz y el queso restante.'),
  (74, 11, 'Bake for another 5 minutes.', 'Ponga el recipiente de nuevo en el horno y hornee por 5 minutos adicionales.'),
  (75, 1, 'Add oil and butter to pan and heat on medium.', 'Ponga el aceite y mantequilla a calentar en un sartén a fuego medio.'),
  (75, 2, 'Add cauliflower, garlic and onion to pan, cover pan with a lid and cook until cauliflower begins to brown.', 'Coloque la coliflor, ajo y cebolla en el sartén. Cúbralo con una tapadera y cocínelo hasta que la coliflor se empiece a dorar.'),
  (75, 3, 'Place the fresh spinach on top of the cauliflower. It will quickly cook down. Stir all ingredients.', 'Coloque las espinacas encima de la coliflor. La espinaca se cocinara de una manera rápida. Después mezcle todos los ingredientes hasta que queden bien integrados.'),
  (75, 4, 'Season, to taste.', 'Sazone al gusto con sal y pimienta.'),
  (76, 1, 'Heat pan and melt half of margarine or butter.', 'Caliente el sartén y ponga derretir la mitad de margarina o mantequilla.'),
  (76, 2, 'Add the cauliflower and cook, turning often, until tender and brown, about 5-7 minutes.', 'Agregue la coliflor y cocínela de 5­-7 minutos, volteándola con frecuencia hasta que se ponga tierna y dorada.'),
  (76, 3, 'Combine brown sugar with other half of margarine or butter. Add this mixture to the cauliflower.', 'Combine la azúcar morena con la otra mitad de margarina o mantequilla. Agregue esta mezcla a la coliflor.'),
  (76, 4, 'Continue stirring and cook 3-4 minutes until cauliflower is coated with the melted brown sugar.', 'Continúe cocinando y revolviendo por un espacio de 3­-4 minutos, hasta que la coliflor quede completamente cubierta/revestida de la azúcar morena derretida.'),
  (77, 1, 'Steam or boil cauliflower until tender.', 'Cocine la coliflor ya sea hirviéndola o al vapor hasta que esta se ponga tierna.'),
  (77, 2, 'In a bowl, mix sour cream, onion, and mustard.', 'En un tazón, mezcle la crema agria, la cebolla y la mostaza.'),
  (77, 3, 'Add sour cream mixture to cauliflower.', 'Agregue la mezcla que contiene la crema agria a la coliflor.'),
  (77, 4, 'Add cheese, cover and let stand for 3 minutes.', 'Agregue el queso, cúbralo con una tapadera y déjelo reposar por 3 minutos.'),
  (78, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (78, 2, 'In a bowl, toss cauliflower with oil and seasonings.', 'En un tazón, agite la coliflor con el aceite y condimentos.'),
  (78, 3, 'Spread on an oiled baking sheet, or a baking sheet covered with aluminum foil.', 'Esparza todo sobre una charola para hornear que haya sido revestida con aceite o cubierta con papel de aluminio.'),
  (78, 4, 'Bake in oven for 15 minutes, until brown and tender.', 'Hornear por un espacio de 15 minutos o hasta que la coliflor se ablande y se dore.'),
  (79, 1, 'Heat oil in a pan over medium heat.', 'Ponga a calentar el aceite en un sartén a fuego medio.'),
  (79, 2, 'Cook cauliflower for 1 minute, stirring.', 'Cocine la coliflor durante un minuto agitándola.'),
  (79, 3, 'Add bell pepper, garlic, and crushed red pepper and cook for another 2-3 minutes, stirring frequently.', 'Añada el pimiento morrón, ajo y las hojuelas de chile rojo y cocine todo de 2-­3 minutos, moviendo los ingredientes con frecuencia para que se mezclen bien.'),
  (79, 4, 'Add broth or water, cover and cook 12 to 15 minutes until tender and brown.', 'Vierta el caldo o agua, tape el sartén y cocine todo de 12­-15 minutos o hasta que las verduras estén tiernas y un poco doradas.'),
  (80, 1, 'Steam or boil cauliflower in water until soft.', 'Ponga a hervir la coliflor o cocínela al vapor hasta que esté tierna.'),
  (80, 2, 'Drain and mash the cauliflower.', 'Cuele el agua y machaque la coliflor.'),
  (80, 3, 'Add egg, grated potato, onion, salt, pepper (optional), and breadcrumbs or flour and mix well.', 'Añada el huevo, la papa rallada, la cebolla, sal, pimienta (opcional) y las migajas de pan o harina y mezcle bien.'),
  (80, 4, 'Shape into patties.', 'Separe parte de la mezcla y con las manos déle forma a las tortitas.'),
  (80, 5, 'Heat 2 large spoons of oil in frying pan and put several patties in pan, cook 4 to 5 minutes on each side, or until brown.', 'Caliente 2 cucharadas grandes de aceite en un sartén y coloque las tortitas en el mismo. Cocine/fría las tortitas de 4 a 5 minutos por cada lado, o hasta que se doren.'),
  (80, 6, 'Add 2 more large spoons of oil and cook remaining patties.', 'Añada 2 cucharadas más de aceite y termine de cocinar/freír las tortitas restantes.'),
  (80, 7, 'Top the patties with a spoon of sour cream, applesauce, or salsa (optional).', 'Para terminar, usando una cuchara, póngale a las tortitas (por encima) una cucharadita de crema agria, puré de manzana o salsa (opcional).'),
  (81, 1, 'Heat oil in a pot.', 'Caliente el aceite en una olla.'),
  (81, 2, 'Add onions and cook until soft.', 'Agregue las cebollas y cuézalas hasta que se ablanden.'),
  (81, 3, 'Add cauliflower and seasonings, and cook until cauliflower turns golden brown.', 'Agregue la coliflor y el sazón y cuézalo hasta que se dore un poco.'),
  (81, 4, 'Add broth and bring to boil.', 'Vierta el caldo y déjelo hervir.'),
  (81, 5, 'Add carrots and cook until soft, about 6 to 8 minutes.', 'Agregue las zanahorias y cuézalas de 6­8 minutos hasta que se ablanden.'),
  (81, 6, 'Mix using a blender, hand mixer, or a potato masher.', 'Bata todo usando una licuadora, batidora de mano, o un triturador de papas.'),
  (81, 7, 'Add cheese and mix again.', 'Agregue el queso y vuelva a batir todo de nuevo.'),
  (82, 1, 'Bring pot of water to a boil and cook beans until crisp-tender, 4-5 minutes. Drain and pat dry with a towel.', 'Ponga una olla de agua a hervir. Añada los ejotes y cocínelos de 4-5 minutos hasta que estén ligeramente crujientes pero aun tiernos. Cuélelos y seque con una toallita.'),
  (82, 2, 'Cut the thin outer peel from a lemon, and slice these pieces into narrow strips.', 'Rebane la cáscara del limón en tiras cortas y delgadas.'),
  (82, 3, 'Squeeze the juice from half a lemon and combine with vegetable oil. Add the beans and toss to coat them.', 'Exprima el jugo de la mitad de un limón y combine con aceite vegetal. Añada los ejotes y revuelva varias veces para recubrirlos bien.'),
  (82, 4, 'Add lemon peel strips and sprinkle with salt or pepper, if desired. Mix together.', 'Añada las tiras de cáscara de limón y rocíe con sal y pimienta, si lo desea. Mezcle bien.'),
  (83, 1, 'Bring pot of water to a boil. Add green beans and simmer until tender. Drain.', 'Ponga agua a hervir en una olla, agréguele los ejotes y siga cocinando a fuego lento hasta que estos se suavicen. A continuación, cuele los ejotes vaciando toda el agua.'),
  (83, 2, 'In another pan, heat butter or margarine. Fry onions and garlic until brown.', 'En otra olla, caliente la mantequilla o margarina. Añada las cebollas y el ajo(opcional) y fríalos hasta que estén dorados.'),
  (83, 3, 'Add green beans, tomatoes, and salsa to onion mixture.', 'Añada los ejotes, los jitomates (opcional), y salsa a la mezcla de cebolla.'),
  (83, 4, 'Add salt or pepper to taste.', 'Añada sal o pimienta al gusto.'),
  (84, 1, 'In a pot, put the potatoes, pinch of salt, and enough water to cover the potatoes.', 'En una olla, ponga las papas, pizca de sal, y suficiente agua para cubrir las papas.'),
  (84, 2, 'Bring to a boil. Lower the heat and cook until the potatoes are tender, 7-10 minutes.', 'Ponga a hervir. Baje el fuego y cocine hasta que las papas estén tiernas, 7-10 minutos.'),
  (84, 3, 'Remove potatoes with slotted spoon, dry them on a towel.', 'Saque las papas usando una cuchara con ranuras y séquelas con una toalla.'),
  (84, 4, 'Add the green beans to the pot of hot water (where the potatoes were cooked) and cook until tender, 4-5 minutes. Drain and dry.', 'Añada los ejotes a la olla con agua caliente (donde las papas se cocinaron) y cocine hasta que estén tiernos, 4-5 minutos. Escurra y ponga a secar.'),
  (84, 5, 'In a bowl, combine the dressing and all the other ingredients.', 'En una recipiente hondo, combine el aderezo y todos los otros ingredientes.'),
  (84, 6, 'Mix gently to spread dressing.', 'Mezcle cuidadosamente para esparcir el aliño.'),
  (84, 7, 'Refrigerate until ready to serve.', 'Refrigere hasta que esté listo para servir.'),
  (85, 1, 'Spray the pot with cooking spray or lightly grease with butter or oil.', 'Apliquele a la olla aceite para cocinar de rociador, o engrase ligeramente con mantequilla o aceite.'),
  (85, 2, 'Heat a frying pan and add the bacon. Cook 4-5 minutes until starting to brown.', 'Caliente un sartén y añada el tocino. Cocine de 4-5 minutos hasta que empiecen a ponerse cafecitos y doraditos.'),
  (85, 3, 'Pour fat from the pan and add the onions. Cook for 3-4 minutes, until soft.', 'Vacie la grasa del sartén y añada las cebollas. Cocine de 3-4 minutos, hasta que estén suaves.'),
  (85, 4, 'Combine potatoes, green beans, onion, bacon (optional), soup, and pinch of pepper in the pot.', 'Combine las papas, ejotes, cebolla, tocino (opcional), sopa, y pizca de pimienta en la olla.'),
  (85, 5, 'Cover and cook on High for 3 hours.', 'Cubra y cocine a temperatura alta por 3 horas.'),
  (86, 1, 'Heat oil in pot. Add onions and cook until brown, stirring occasionally.', 'Caliente aceite en una olla. Añada cebollas y cocine hasta que estén doradas, meneando ocasionalmente.'),
  (86, 2, 'Add beans, salt, and garlic to pot and stir together with onions for 2 minutes.', 'Añada ejotes, sal, y ajo en la olla y revuelva todo junto con las cebollas por 2 minutos.'),
  (86, 3, 'Add water to 1 inch over the top of the mixture.', 'Añada agua hasta 1 pulgada por encima de la mezcla.'),
  (86, 4, 'Bring to a boil, and then reduce to a simmer. Cook for 12-14 minutes or until beans are soft.', 'Ponga a hervir, y luego reduzca a fuego lento. Cocine por 12-14 minutos o hasta que los ejotes estén suaves.'),
  (86, 5, 'Combine flour and sour cream in a bowl. Stir in several large spoons of hot liquid from the soup pot to warm the sour cream mixture.', 'Combine la harina con la crema agria en un recipiente hondo. Vierta varias cucharas grandes de líquido caliente procedente de la olla con sopa, para calentar la mezcla de crema agria.'),
  (86, 6, 'Add the sour cream mixture to the soup, stirring thoroughly.', 'Añada la mezcla de crema agria a la sopa, revolviendo bastante bien.'),
  (86, 7, 'Bring mixture to a simmer and stir over heat for another 2 minutes.', 'Deje que todo se siga cocinando a fuego lento, agitando lentamente, por otros 2 minutos.'),
  (86, 8, 'Add salt, pepper, and favorite seasonings to taste.', 'Añada sal, pimienta, y condimentos favoritos al gusto.'),
  (87, 1, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (87, 2, 'Boil lightly salted water in a pot.', 'Hierva agua con un poco de sal en una olla.'),
  (87, 3, 'Drop the green beans into the pot of boiling water.', 'Vierta los ejotes enteros en la olla de agua hirviendo.'),
  (87, 4, 'Cook uncovered for 4 to 5 minutes until just tender. Remove from the heat and drain.', 'Cocine sin tapar por 4 o 5 minutos hasta que los ejotes estén tiernos. Retire la olla de la estufa y cuele.'),
  (87, 5, 'Sprinkle with lemon juice or other seasonings.', 'Rocíe con jugo de limón y otros condimentos.'),
  (87, 6, 'To toast nuts, heat oven or counter top oven to 350 degrees. Put nuts on a metal tray, stir frequently with a fork. Watch to make sure that the nuts do not burn.', 'Para tostar las nueces, caliente el horno de la cocina o un horno tostador eléctrico pequeño a 350 grados. Ponga las nueces en una charola de metal y usando un tenedor agítelas con frecuencia. Vigílelas para asegurarse de que las nueces no se quemen.'),
  (87, 7, 'Sprinkle toasted nuts on the cooked green beans.', 'Esparza/rocíe las nueces tostadas sobre los ejotes ya cocidos.'),
  (87, 8, 'Another option is to cool the cooked beans by rinsing them with cold water. Then you can add the green beans to a salad.', 'Otra opción es la de enfriar los ejotes ya cocidos enjuagándolos con agua fría, para luego añadírselos a una ensalada.'),
  (88, 1, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (88, 2, 'Put the beans into a steamer basket over boiling water.', 'Ponga los ejotes en una canasta para cocinar al vapor sobre agua hirviendo.'),
  (88, 3, 'Cover the pan loosely and steam about 5 minutes, until just tender.', 'Cubra la cacerola sin taparla totalmente y hierva por casi 5 minutos, hasta que estén tiernos.'),
  (88, 4, 'Sprinkle with lemon juice or other seasonings.', 'Rocíe con jugo de limón u otros condimentos.'),
  (88, 5, 'To toast nuts, heat oven or countertop oven to 350 degrees. Put nuts on a metal tray, stir frequently with a fork. Watch to make sure that the nuts do not burn.', 'Para tostar las nueces, caliente el horno de la cocina o un horno pequeño a 350 grados. Ponga las nueces en una charola de metal y revuelva con frencuencia con un tenedor. Revisando para asegurarse de que las nueces no se quemen.'),
  (88, 6, 'Sprinkle toasted nuts on the cooked green beans.', 'Rocíe las nueces tostadas en los ejotes cocinados.'),
  (88, 7, 'Another option is to cool the cooked beans by rinsing them with cold water. Then you can add the green beans to a salad.', 'Otra opción es enfriar los ejotes cocinados enjuaguándolos con agua fría. Luego puede añadir los ejotes en la ensalada.'),
  (89, 1, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (89, 2, 'Place green beans in a microwavable dish with ¼ cup of water.', 'Coloque los ejotes en un plato para el microondas con ¼ de taza de agua.'),
  (89, 3, 'Cover with plastic or waxed paper.', 'Cubra con plástico o papel encerado.'),
  (89, 4, 'Cook on high for about 4-5 minutes, until just tender.', 'Cocine a fuego alto por cerca de 4-5 minutos, hasta que estén tiernos.'),
  (89, 5, 'Sprinkle with lemon juice or other seasonings.', 'Rocíe con jugo de limón u otros condimentos.'),
  (89, 6, 'To toast nuts, heat oven or countertop oven to 350 degrees. Put nuts on a metal tray, stir frequently with a fork. Watch to make sure that the nuts do not burn.', 'Para tostar las nueces, caliente el horno de la cocina o un horno pequeño a 350 grados. Ponga las nueces en una charola de metal, y usando un tenendor, agítelas frencuencia. Revise para asegurarse de que las nueces no se quemen.'),
  (89, 7, 'Sprinkle toasted nuts on the cooked green beans.', 'Vierta y esparza las nueces tostadas sobre los ejotes ya cocidos.'),
  (89, 8, 'Another option is to cool the cooked beans by rinsing them with cold water. Then you can add the green beans to a salad.', 'Otra opción es la de enfriar los ejotes ya cocidos, enjuaguándolos con agua fría para luego añadírselos a una ensalada.'),
  (90, 1, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (90, 2, 'Boil water in a pot.', 'Hierva agua en una olla.'),
  (90, 3, 'Drop the green beans into the pot of boiling water.', 'Eche los ejotes enteros en una olla con agua hirviendo.'),
  (90, 4, 'Cook for 3 to 4 minutes; beans should remain crisp.', 'Cocine por 3 o 4 minutos; los ejotes deberán permancer frescos.'),
  (90, 5, 'Remove quickly from the heat and drain the water. Put beans in a bowl of ice water to stop the cooking; drain again.', 'Retire rápido del fuego y cuele el agua. Ponga los ejotes en un plato hondo con agua helada para evitar que se sigan cocinando y cuele de nuevo.'),
  (90, 6, 'When ready to serve, put oil in a pan, heat to moderately high, and add the garlic and stir for a minute or two.', 'Cuando esté listo para servir, ponga aceite en el sartén, caliente a fuego moderadamente alto, añada el ajo y agite por un minuto o dos.'),
  (90, 7, 'Then, add the cooked beans; stir for 2-3 minutes.', 'Luego, añada los ejotes cocinados; agite de 2-3 minutos.'),
  (90, 8, 'Season with salt or pepper or other seasonings during cooking.', 'Sazone con sal o pimienta u otros condimentos mientras se cocinan.'),
  (92, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (92, 2, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (92, 3, 'Lightly coat a baking sheet with vegetable oil or non-stick cooking spray.', 'Ligeramente cubra una charola para hornear con aceite vegetal o rociador para cocinar antiadherente.'),
  (92, 4, 'Toss the beans, garlic slices, and seasonings (to taste) in vegetable oil.', 'Combine y revuelva los ejotes, los pedazos de ajo, y condimentos (al gusto) en aceite vegetal.'),
  (92, 5, 'Spread on sheet in one layer. Cook for 10­-15 minutes, turning several times.', 'Extienda sobre la charola en una sola capa; cocine por 10­-15 minutos, dándoles vuelta varias veces.'),
  (92, 6, 'Discard any overcooked slices of garlic.', 'Descarte cualquier pedazo de ajo sobrecocinado.'),
  (93, 1, 'Wash the beans and cut off the ends; cut the beans in half.', 'Lave los ejotes y corte los extremos; corte los ejotes por la mitad.'),
  (93, 2, 'Prepare other vegetables, if used.', 'Prepare otros vegetales, si los va a usar.'),
  (93, 3, 'Sprinkle meat with pepper.', 'Rocíe la carne con pimienta.'),
  (93, 4, 'Heat large frying pan to very hot temperature, and add 1 large spoon of oil.', 'Caliente una sartén grande a una temperatura bastante alta, y añada 1 cuchara grande de aceite.'),
  (93, 5, 'Place meat in pan. Stir constantly and remove quickly when browned; keep warm.', 'Coloque la carne en la sartén; remueva constantemente y retire rápido cuando se esté dorando; mantenga caliente.'),
  (93, 6, 'Add 2 large spoons of oil to pan.', 'Coloque 2 cucharas grandes de aceite en la sartén.'),
  (93, 7, 'Cook and stir onion and garlic (optional) until they begin to soften. Add green beans and your choice of other vegetables.', 'Cocine y remueva la cebolla y el ajo (opcional) hasta que empiecen a suavisarse. Eche los ejotes y los otros vegetales que haya elegido.'),
  (93, 8, 'Sprinkle a little soy sauce onto mixture; scatter pinch of salt, pepper, and other seasonings (optional); cook mixture, stirring constantly, until tender, 5-7 minutes.', 'Rocíe salsa de soya sobre le mezcla; esparza una pizca de sal, pimienta y otros condimentos (opcional); cocine la mezcla, removiendo constantemente, hasta que esté tierna, 5-7 minutos.'),
  (93, 9, 'Return meat pieces and juices to pan. Stir and cook one minute.', 'Ponga los pedazos de carne y su jugo de nuevo en el sartén. Agite y cocine por un minuto.'),
  (94, 1, 'Wash the beans and cut off the ends. Drop beans in boiling water and cook until just tender, 3-4 minutes. Drain and place in ice water to stop cooking; drain again.', 'Lave los ejotes y corte los extremos; eche los ejotes en agua hirviendo y cocine hasta que estén casi tiernos, 3-4 minutos. Cuele y coloque en agua helada para evitar que se sigan cocinando; cuele de nuevo.'),
  (94, 2, 'Put vegetables into a bowl. Add Italian dressing and pinch of pepper. Mix thoroughly.', 'Ponga vegetales en un plato hondo. Añada el aderezo italiano y una pizca de pimienta; mezcle bastante bien.'),
  (94, 3, 'Cover and refrigerate for at least 1 hour.', 'Cubra y refrigere por lo menos una hora.'),
  (95, 1, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (95, 2, 'Bring pot of water to boil (enough to cover vegetables);drop carrots into water and simmer (just below boiling) for 8-10 minutes, covered.', 'Ponga agua a hervir en una olla (suficiente como para cubrir las verduras); ponga las zanahorias en el agua, cubra la olla y hierva a fuego lento de 8-10 minutos.'),
  (95, 3, 'Then, add green beans and cook for 3-4 minutes.', 'A continuación, añada los ejotes, y siga cocinando de 3-4 minutos.'),
  (95, 4, 'Drain; mix thoroughly with margarine or butter and seasonings.', 'Cuele; mezcle minuciosamente con margarina o mantequilla y condimentos.'),
  (96, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados'),
  (96, 2, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (96, 3, 'Coat a baking dish with a little vegetable oil.', 'Cubra una charola para hornear con un poco de aceite vegetal.'),
  (96, 4, 'Toss vegetables with margarine or butter and a pinch of salt and pepper.', 'Combine los vegetales con la margarina o mantequilla y una pizca de sal y pimienta.'),
  (96, 5, 'Bake vegetables for 30-35 minutes.', 'Ponga los vegetales en la charola y hornee por 30-35 minutos.'),
  (96, 6, 'If you want, top with cheese for the last 5 minutes of baking. Do not freeze if you use cheese.', 'Si lo desea, cubra con queso durante los últimos 5 minutos que la charola esté en el horno. No congele si usa el queso.'),
  (97, 1, 'Wash the beans and cut off the ends; boil, steam, or microwave the beans.', 'Lave los ejotes y corte los extremos; hierva, cocine al vapor, o caliente en el microondas los ejotes.'),
  (97, 2, 'Heat the oil in a pan and add the onions. Cook until onions soften. Add garlic and cook for another 3-4 minutes, stirring occasionally.', 'Caliente el aceite en un sartén y añada las cebollas. Cocine hasta que las cebollas estén suaves. Añada el ajo y cocine por otros 3-4 minutos, removiendo ocasionalmente.'),
  (97, 3, 'Add green beans, tomatoes, and seasonings; mix thoroughly.', 'Añada los ejotes, los tomates, y condimentos; mezcle bastante bien.'),
  (97, 4, 'Cover and cook for 5 minutes.', 'Cubra y cocine por 5 minutos.'),
  (98, 1, 'Wash the beans and cut off the ends; steam, boil, or microwave the beans.', 'Lave los ejotes y corte los extremos; cocine los ejotes al vapor, hierva, o caliente en el microondas.'),
  (98, 2, 'In a dish, combine vinegar and sugar and stir with a fork to mix.', 'En un recipiente, combine el vinagre y el azúcar y agite con un tenedor para mezclar todo.'),
  (98, 3, 'In a frying pan, heat vegetable oil and add the onions; cook until onions soften.', 'En un sartén, caliente el aceite vegetal y añada las cebollas; cocine hasta que las cebollas estén suaves.'),
  (98, 4, 'Add the garlic and cook for another 3-4 minutes, stirring occasionally.', 'Añada el ajo y cocine por otros 3-4 minutos, removiendo ocasionalmente.'),
  (98, 5, 'Add the green beans to the pan, along with vinegar mixture and seasonings; cook, stirring, for 1-2 minutes.', 'Añada los ejotes a la sartén, junto con la mezcla de vinagre y los condimentos; cocine, removiendo, por 1-2 minutos.'),
  (99, 1, 'Wash the beans and cut off the ends; steam, boil, or microwave the beans.', 'Lave los ejotes y corte los extremos; cocine los ejotes, al vapor, hervidos o en un horno de microondas.'),
  (99, 2, 'Remove chicken from the bone; cut into pieces the size of your finger or thumb; sprinkle pieces all over with salt and pepper.', 'Quítele el hueso a pollo; corte en pedazos del tamaño de su dedo o pulgar y rocíe los pedazos por todos lados con sal y pimienta.'),
  (99, 3, 'In a large frying pan, heat the oil and add chicken pieces; cook and stir until they are no longer pink, 2-3 minutes.', 'En un sartén grande, caliente el aceite y agréguele las piezas de pollo; cocine y mueva las piezas hasta que pierdan el color "rosita", de 2-3 minutos aproximadamente.'),
  (99, 4, 'Then add onion, garlic squash, and mushroom, with a pinch of salt and pepper. Stir often until vegetables soften.', 'A continuación, añada la cebolla, ajo, calabaza, y hongos, así como una pizca de sal y pimienta. Siga cocinado y revuelva todo ocasionalmente hasta que las verduras se ablanden.'),
  (99, 5, 'Stir in tomatoes and enough juices for the moistness you want; bring to a boil, reduce heat, and simmer uncovered for 5 minutes; stir a couple times.', 'Agregue los jitomates y suficiente jugo para adquirir la consistencia que usted desee; deje que hierva, reduzca la intensidad, y siga cocinando a fuego lento sin cubrir por 5 minutos; agite un par de veces.'),
  (99, 6, 'Stir in cooked green beans; cook another minute.', 'Agregue los ejotes ya cocidos; cocine por un minuto mas.'),
  (100, 1, 'Preheat oven to 350 degrees.', 'Precalentar el horno a 350 grados.'),
  (100, 2, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (100, 3, 'Peel onion, cut off both ends, cut into wedges.', 'Pele la cebolla, corte los extremos, corte en trozos.'),
  (100, 4, 'In a large frying pan, heat vegetable oil and add the onion.', 'En un sartén grande, caliente aceite vegetal y añada la cebolla.'),
  (100, 5, 'Cook the onion until soft and lightly browned, 5-10 minutes.', 'Cocine la cebolla hasta que esté suave y ligeramente dorada, 5-10 minutos.'),
  (100, 6, 'Add green beans and barbecue sauce; stir 2-3 minutes.', 'Añada los ejotes y la salsa de barbacoa; remueva 2-3 minutos.'),
  (100, 7, 'Place mixture in a baking dish; bake for 15-20 minutes.', 'Coloque la mezcla en un recipiente para hornear; hornee de 15-20 minutos.'),
  (101, 1, 'Preheat oven to 375 degrees.', 'Precaliente el horno a 375 grados.'),
  (101, 2, 'Wash the beans and cut off the ends.', 'Lave los ejotes y corte los extremos.'),
  (101, 3, 'Mix mustard, honey, and 2 pinches of pepper.', 'Mezcle la mostaza, la miel, y 2 pizcas de pimienta.'),
  (101, 4, 'Wash chicken pieces. Trim extra fat and ribs, and discard. Pat pieces dry and lightly sprinkle chicken pieces with salt and coat with mustard mixture.', 'Lave los pedazos de pollo. Quíteles la grasa en exceso, así como las costillas, y deseche. Usando una toallita de papel, seque el pollo y ligeramente rocíe las piezas de pollo con sal y cubra con la mezcla de mostaza.'),
  (101, 5, 'Put each chicken breast on a sheet of aluminum foil.', 'Ponga cada pechuga de pollo sobre una hoja de papel de aluminio.'),
  (101, 6, 'Put a handful of green beans on top of each piece of chicken.', 'Ponga un puñado de ejotes sobre cada pieza de pollo.'),
  (101, 7, 'Place second sheet of foil on top; bring foil sides together and crinkle all sides creating a packet with room at the top for circulation.', 'Coloque una segunda hoja de papel de aluminio sobre el pollo; junte los extremos del papel y doble y arrugue los cuatro lados creando un paquete con espacio en la parte de arriba para que haya circulación.'),
  (101, 8, 'Place packets on top of baking sheets and bake for approximately 30 minutes.', 'Coloque los paquetes sobre una charola para hornear y hornee por aproximadamente 30 minutos.'),
  (101, 9, 'Also can be made with chicken thighs and drumsticks; cook for 35-40 minutes.', 'También puede hacerse con piernas de pollo o muslos; cocine por 35-40 minutos.'),
  (102, 1, 'Heat oil in large frying pan.', 'Caliente el aceite en un sartén.'),
  (102, 2, 'Add onions and stir until brown.', 'Añada cebollas y agite hasta que las cebollas estén doradas.'),
  (102, 3, 'Add greens and stir for just a minute or two, until greens are soft.', 'Añada verduras y revuelva por solo uno o dos minutos, hasta que las verduras estén suaves.'),
  (102, 4, 'Add lemon juice and stir.', 'Añada jugo de limón y agite.'),
  (102, 5, 'Remove from heat and add salt or pepper, to taste.', 'Aleje del fuego y añada sal y pimienta al gusto.'),
  (103, 1, 'Layer potatoes and onions in a microwave dish.', 'Coloque las papas y cebollas en "capas" en un recipiente semi hondo apropiado para el microondas.'),
  (103, 2, 'Add a pinch of salt or pepper.', 'Añada una pizca de sal o pimienta.'),
  (103, 3, 'Add butter or margarine on top.', 'Añada la mantequilla o margarina por encima.'),
  (103, 4, 'Cover and microwave at normal setting for 15 minutes; stop every 5 minutes and stir.', 'Cubra y caliente en el microondas a una temperatura normal por 15 minutos; apague el microondas cada 5 minutos y revuelva.'),
  (104, 1, 'Cut the white part of the bok choy into one-inch pieces.', 'Corte la parte blanca del repollo chino (Bok Choy) en pedazos de una pulgada.'),
  (104, 2, 'Coarsely chop the green part of the bok choy. Keep the white and the greens separate.', 'Pique en pedazos gruesos la parte verde del repollo chino (Bok Choy). Mantenga la parte blanca y verde separadas.'),
  (104, 3, 'Heat a pan and add a small amount of oil or spray with vegetable oil.', 'Caliente una cacerola y añada una cantidad pequeña de aceite vegetal o use un rociador para cocinar.'),
  (104, 4, 'Cook the bok choy white stems, onions, and green beans over medium high heat for 6-7 minutes.', 'Cocine las raíces blancas del repollo china (Bok Choy), las cebollas, y los ejotes a fuego medio-alto por 6-7 minutos.'),
  (104, 5, 'Add bok choy greens and cook one minute longer.', 'Añada la parte verde del repollo chino (Bok Choy) y cocine por un minuto más.'),
  (104, 6, 'Add soy sauce and stir several times. Season to taste.', 'Añada salsa de soya y revuelva varias veces. Sazone al gusto.'),
  (106, 1, 'Boil a pot of water, enough so that the onions will be covered.', 'Hierva una olla con agua, lo suficiente para cubrir las cebollas.'),
  (106, 2, 'Cut the ends off and peel the onions.', 'Corte los extremos y pele las cebollas.'),
  (106, 3, 'Cut onions into halves.', 'Corte las cebollas en mitades.'),
  (106, 4, 'Boil onions for 10-20 minutes, until tender.', 'Hierva las cebollas por 10-20 minutos, hasta que estén tiernas.'),
  (106, 5, 'Drain the water.', 'Escurra el agua.'),
  (106, 6, 'Season with salt and pepper to taste.', 'Sazone con sal y pimienta al gusto.'),
  (107, 1, 'Grease medium-sized baking dish with small amount of margarine or butter.', 'Engrase una charola mediana para el horno con una pequeña cantidad de margarina o mantequilla.'),
  (107, 2, 'Slice onions and arrange in the baking dish.', 'Corte las cebollas en tajadas y acomódelas en la charola.'),
  (107, 3, 'Mix the melted margarine or butter with vinegar, boiling water, and sugar. Pour this mixture over the onions.', 'Mezcle la margarina o mantequilla derretida con vinagre, agua hirviendo, y azúcar. Vierta esta mezcla sobre las cebollas.'),
  (107, 4, 'Bake at 300 degrees for 1 hour, stirring several times during baking.', 'Hornee a 300 grados por 60 minutos, revolviendo varias veces mientras se cocinan.'),
  (108, 1, 'Heat oil and add onions to frying pan.', 'Caliente el aceite en un sartén y añada las cebollas.'),
  (108, 2, 'Cover pan and cook on low heat for 20 minutes or until onions are soft.', 'Cubra la sartén y cocine a fuego bajo por 20 minutos o hasta que las cebollas estén suaves.'),
  (108, 3, 'Cook noodles according to package.', 'Cocine los fideos de acuerdo a las instrucciones del paquete.'),
  (108, 4, 'Remove pan cover and turn heat up to medium.', 'Retire la tapa de la sartén y eleve a fuego a punto medio.'),
  (108, 5, 'Add broth to pan and stir.', 'Añada caldo al sartén y revuelva.'),
  (108, 6, 'Cook until most of the liquid is gone and onions are brown, 5­-10 minutes.', 'Cocine hasta que casi todo el líquido haya desaparecido y las cebollas estén de color doradas, 5-10 minutos.'),
  (108, 7, 'Add parsley and pepper (optional) and stir.', 'Añada perejil y pimienta (opcional) y revuelva.'),
  (108, 8, 'Pour over noodles and add parmesan cheese to taste.', 'Vierta sobre los fideos y añada queso parmesano al gusto.'),
  (109, 1, 'Slice cucumbers and onions.', 'Corte las cebollas y pepinillos en tajadas.'),
  (109, 2, 'Mix vinegar, water, sugar, salt and pepper. Add mixture to cucumbers and onions.', 'Mezcle vinagre, agua, azúcar, sal y pimienta. Añada la mezcla a los pepinillos y cebollas.'),
  (109, 3, 'Cover tightly with plastic wrap or store in airtight containers. Refrigerate 8 hours.', 'Cubra completamente y bien con una envoltura plástica o ponga en recipientes herméticos. Refrigere 8 horas.'),
  (110, 1, 'Melt butter on stove top or in microwave and mix with honey.', 'Derrita la mantequilla en un sartén o en un recipiente para apto para el horno de microondas y mezcle con la miel.'),
  (110, 2, 'Peel onions, cut and half, and place cut side up on a microwave safe dish.', 'Pele las cebollas, pártalas por la mitad, y coloque, con la parte cortada hacia arriba, en un recipiente apropiado para el horno de microondas.'),
  (110, 3, 'Pour honey mixture over the onions.', 'Vierta la mezcla de miel y mantequilla sobre las cebollas.'),
  (110, 4, 'Cover with wax paper, lid, or plastic wrap.', 'Cubra con papel encerado, o con una tapa o envoltura de plástico.'),
  (110, 5, 'Microwave on high for 6-8 minutes, stopping every few minutes to spoon juices over the onions and to rotate dish.', 'Cocine en el microondas a temperatura alta de 6-8 minutos, y usando una cuchara vierta los jugos sobre las cebollas cada un par de minutos y no se olvide de rotar el recipiente.'),
  (111, 1, 'Preheat oven to 375 degrees.', 'Precalentar el horno a 375 grados.'),
  (111, 2, 'Melt butter or margarine in a small pan.  Add honey to the butter or margarine and mix together.', 'Derrita la mantequilla o margarina en un sartén chico. Añada la miel a la mantequilla o margarina y mezcle bien.'),
  (111, 3, 'Peel the onions and cut in half.', 'Pele las cebollas y córtelas por la mitad.'),
  (111, 4, 'Place, cut side up, in a baking dish that has been lightly coated with oil or non-stick spray. Or, you can line the dish with foil.', 'Coloque las cebollas con el lado cortado hacia arriba en una charola para hornear que haya sido recubierta con aceite o un rociador para hornear antiadherente. O, también pudiera cubrir la charola con papel de aluminio.'),
  (111, 5, 'Pour the honey mixture over the onions.', 'Vierta la mezcla de la miel por encima de las cebollas.'),
  (111, 6, 'Bake for 60 minutes, turning onions over twice.', 'Coloque la charola en el horno por 60 minutos, volteando las cebollas en dos ocasiones.'),
  (112, 1, 'Heat the oil in a large frying pan. Add the carrots and onions. Keeping the heat at medium to high, cook and stir the vegetables for about 5 minutes.', 'Caliente el aceite en un sartén grande. Añada las zanahorias y cebollas. Manteniendo el fuego entre medio y alto, cocine y menee los vegetales por casi 5 minutos.'),
  (112, 2, 'Add the garlic and the rest of the vegetables, any combination you want. If the pan is not big enough to hold all of the vegetables, you can cook them one at a time then mix together.', 'Añada el ajo y el resto de los vegetales, cualquier combinación que apetezca. Si el sartén no es tan grande para contener todos los vegetales, usted puede cocinarlos uno por uno y luego mezclarlos juntos.'),
  (112, 3, 'Cook until the vegetables are soft and slightly crunchy. You may add a spoonful of water to help them cook faster.', 'Cocine hasta que los vegetales estén suaves y ligeramente crujientes. Usted puede añadir una cucharada de agua para ayudar a que se cocinen más rápido.'),
  (112, 4, 'Add cooked meat and stir for 1 minute (optional).', 'Agregue la carne ya cocida, y siga cocinando sin dejar de revolver por 1 minuto (opcional).'),
  (112, 5, 'Add salt and pepper to taste.', 'Añada sal y pimienta al gusto.'),
  (112, 6, 'Serve on rice, cooked according to package.', 'Sirva sobre arroz, cocinado de acuerdo a las instrucciones del paquete.'),
  (113, 1, 'Pre-heat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (113, 2, 'Season chicken pieces with salt and pepper.', 'Sazone las piezas de pollo con sal y pimienta'),
  (113, 3, 'Coat inside of baking dish with oil.', 'Cubra con aceite el interior de un recipiente para hornear con borde.'),
  (113, 4, 'Arrange chicken pieces skin side up (or you may remove skins), and bake for 15 minutes.', 'Acomode las piezas de pollo con el pellejo hacia arriba (o puede quitarles el pellejo), y hornee por 15 minutos.'),
  (113, 5, 'Combine onions, garlic, carrots and zucchini with oil in a bowl. Sprinkle with a pinch of salt and pepper and toss to coat.', 'Combine las cebollas, ajo, zanahorias, y calabacitas con el aceite en un recipiente hondo. Espolvoree una pizca de sal y pimienta y revuelva todo bien.'),
  (113, 6, 'Add vegetables and half the chicken broth to the baking dish with chicken pieces.', 'Añada las verduras y la mitad del consomé de pollo al recipiente para hornear junto con las piezas de pollo.'),
  (113, 7, 'Cover tightly with foil and bake for 30 minutes.', 'Cubra de manera firme con papel de aluminio y cocine por 30 minutos.'),
  (113, 8, 'Uncover, add remaining chicken broth, and bake uncovered 5-10 minutes longer, or until chicken juices run clear when you poke pieces with a knife.', 'Destape el recipiente, agregue el resto del consomé, y cocine destapado de 5-10 minutos adicionales, o hasta que los jugos del pollo se vean claros cuando trinche las piezas con un cuchillo.'),
  (114, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (114, 2, 'Peel and slice onions into small pieces the size of the end of your thumb.', 'Pele y corte las cebollas en pedazos pequeños del tamaño de su dedo pulgar.'),
  (114, 3, 'Wash potatoes and leave the skins. Cut potatoes into pieces the size of your thumb.', 'Lave las papas y déjeles la cáscara. Córtelas en pedazos del tamaño de su dedo pulgar.'),
  (114, 4, 'Toss onions and potatoes in a bowl with oil or melted margarine and a pinch of salt and pepper.', 'Ponga las cebollas en un tazón y mezcle con aceite o margarina derretida y una pizca de sal y pimienta.'),
  (114, 5, 'Spread onions and potatoes on an oiled baking pan or pan lined with foil. The vegetables should be in a single layer.', 'Esparza las cebollas y papas en un recipiente para hornear que haya sido revestido con aceite o cubierto con papel de aluminio. Las verduras deberán ser esparcidas en una sola capa.'),
  (114, 6, 'Cover with foil and bake for 50 minutes.', 'Cubra con papel de aluminio y cocine por 50 minutos.'),
  (114, 7, 'Remove foil and bake another 10 minutes until brown.', 'Remueva el papel de aluminio y siga cocinándo por otros 10 minutos hasta dorarse.'),
  (116, 1, 'Peel and chop or slice onions.', 'Pele y pique o corte las cebollas en tajadas.'),
  (116, 2, 'Add salt and pepper to taste (optional).', 'Añada sal y pimienta al gusto (opcional).'),
  (116, 3, 'Heat frying pan on low. Add oil, butter or margarine to pan (Note: Butter or margarine provide more flavor than oil. If using butter or margarine, add 1 large spoon of oil to prevent butter from burning).', 'Caliente un sartén a fuego lento. Añada aceite, mantequilla o margarina al sartén (Nota: La mantequilla o margarina da más sabor que el aceite. Si usa mantequilla o margarina, agréguele 1 cucharada grande de aceite para prevenir que la mantequilla se queme).'),
  (116, 4, 'Add onions to pan.', 'Añada cebollas al sartén.'),
  (116, 5, 'Cook on low heat and stir constantly.', 'Cocine a fuego bajo y menee constantemente.'),
  (116, 6, 'Cook until lightly browned for about 10 to 15 minutes. Add garlic. The longer the onions cook, the sweeter they get.', 'Cocine por casi 10 a 15 minutos hasta que estén ligeramente doradas. Agréguele el ajo. Mientras más se cocinen las cebollas, más dulces se pondrán.'),
  (117, 1, 'Bring 1 inch of water in a pot to boil.', 'Ponga a hervir 1 pulgada de agua en una olla.'),
  (117, 2, 'Place steamer basket in the pot and put sliced onions in basket.', 'Coloque un vaporizador plegable o "canastita" en una olla y ponga las tajadas de cebollas dentro del vaporizador.'),
  (117, 3, 'Cover, cook for 5 to 12 minutes (the thicker the slices, the longer they need to be steamed).', 'Cubra y cocine de 5­-12 minutos (mientras más gruesas las tajadas, más tiempo necesitarán cocinarse al vapor).'),
  (117, 4, 'Remove onions from steamer, drain.', 'Saque las cebollas del vaporizador y cuelelas.'),
  (117, 5, 'Season with salt, pepper, or other favorite seasonings.', 'Sazone con sal, pimienta, u otros condimentos favoritos.'),
  (118, 1, 'Put onion pieces in a microwavable dish.', 'Ponga los trozos de cebollas en un recipiente apropiado para el microondas.'),
  (118, 2, 'Add water or broth.', 'Añada agua o caldo.'),
  (118, 3, 'Cover dish with a lid or wax paper.', 'Cubra el recipiente con una tapa o papel encerado.'),
  (118, 4, 'Cook for 5 to 7 minutes turning dish once during cooking.', 'Cocine de 5­-7 minutos volteando el recipiente una vez mientras se cocinan.'),
  (118, 5, 'Add salt, pepper, or other favorite seasonings.', 'Añada sal, pimienta, u otros condimentos favoritos.'),
  (119, 1, 'Combine onions, butter or margarine, and salt in a Crock­Pot.', 'Combine cebollas, mantequilla o margarina, y sal en una olla eléctrica.'),
  (119, 2, 'Cover and cook on low for 8 hours.', 'Cubra y cocine a temperatura baja por 8 horas.'),
  (119, 3, 'Serve as a side dish with any other vegetables, meat, or fish.', 'Sirva como un plato de acompañamiento con otros vegetales, carne o pescado.'),
  (120, 1, 'Mix lime juice and orange juice in a bowl.', 'Mezcle los jugos de limón y naranja en un recipiente hondo.'),
  (120, 2, 'Place the onions in a glass or ceramic bowl. Cover the onions with boiling water and wait 30 seconds.', 'Coloque las cebollas en un recipiente hondo de vidrio o cerámica. Cubra las cebollas con agua hirviendo y espere 30 segundos.'),
  (120, 3, 'Drain the onions thoroughly.', 'Cuele las cebollas hasta deshacerse del agua completamente.'),
  (120, 4, 'Return the onions to the bowl and pour on the juices and stir in the salt.', 'Vuelva a colocar las cebollas en el recipiente hondo y vierta los jugos y agregue la sal mientras agita todo.'),
  (120, 5, 'Cover. Let the onion mixture sit in the refrigerator for 8 hours.', 'Cubra. Deje la mezcla de cebollas reposar en el refrigerador por 8 horas.'),
  (120, 6, 'Before serving, drain the onions.', 'Antes de servir, cuele de nuevo las cebollas.'),
  (121, 1, 'Preheat oven to 450 degrees.', 'Precaliente el horno a 450 grados.'),
  (121, 2, 'Coat a cookie sheet with vegetable oil.', 'Cubra con aceite vegetal una charola para hacer galletas en el horno.'),
  (121, 3, 'Slice the onions as wide as your finger, and separate into rings.', 'Corte las cebollas en tajadas del ancho de su dedo, y sepárelas en anillos.'),
  (121, 4, 'In one bowl, place the flour. Put eggs in a second bowl. Place bread crumbs in a third bowl.', 'En un recipiente hondo, coloque harina. Ponga huevos en un segundo recipiente hondo. Coloque las migajas de pan en un tercer recipiente hondo.'),
  (121, 5, 'Coat all the onion rings lightly with flour, to dry them.', 'Cubra todos los anillos de cebolla ligeramente con harina, para secarlos.'),
  (121, 6, 'Dip each ring individually in egg mixture, to coat. Then coat with bread crumbs. Pat so the crumbs will stick to all surfaces. Spread rings out on a plate.', 'Meta uno por uno, los anillos de cebolla en la mezcla de huevo, asegurándose que queden completamente cubiertos. Luego cubralos con las migajas de pan. Con sus manos haga que las migajas cubran completamente las cebollas. Ponga los anillos en un plato.'),
  (121, 7, 'Heat the oiled cookie sheet in the oven for 4-6 minutes.', 'Caliente la charola para hacer galletas, previamente aceitada, en el horno por 4-6 minutos.'),
  (121, 8, 'Carefully, pull sheet out, place onion rings onto heated sheet, making sure none are touching. Bake for 8 minutes.', 'Cuidadosamente, saque la charola, coloque los anillos de cebollas sobre la misma, asegurándose de que los anillos no se toquen entre si. Hornee por 8 minutos.'),
  (121, 9, 'Remove sheet, turn rings over, and bake for another 8 minutes.', 'Saque la charola, voltee los anillos, y hornee por otros 8 minutos.'),
  (122, 1, 'Brown beef in oil in a frying pan.', 'Dore la carne de res en un sartén con aceite.'),
  (122, 2, 'Add onions and celery or carrots (optional) and cook until tender.', 'Añada cebollas y apio o zanahorias (opcional) y cocine hasta que estén blandas.'),
  (122, 3, 'Mix meat, onion mixture, and potatoes in a large bowl.', 'Combine la carne y la mezcla de los vegetales y papas en un tazón hondo y grande.'),
  (122, 4, 'Add the tomato soup and a soup can of water to the mixture and mix well.', 'Añada la sopa de jitomate y el contenido de una lata con agua a la mezcla y revuelva bien todo.'),
  (122, 5, 'Add seasonings and stir.', 'Añada condimentos y agite.'),
  (122, 6, 'Put mixture into the Crock­Pot.', 'Ponga todo en la olla eléctrica.'),
  (122, 7, 'Cook on high for 4 hours.', 'Cocine por 4 horas a temperatura alta.'),
  (123, 1, 'Mix grated potatoes, green onions, egg, and breadcrumbs (or flour) in a bowl.', 'Mezcle las papas ralladas, cebollitas, huevo y el pan molido en un tazón.'),
  (123, 2, 'Form into patties.', 'Forme las tortitas.'),
  (123, 3, 'Heat a large spoon of oil in a frying pan; when hot, cook patties on each side, about 5-10 minutes turning once. They should be lightly browned.', 'Caliente una cucharada grande de aceite en un sartén; una vez caliente, cocine las tortitas aproximadamente 5-10 minutos por cada lado, hasta que estén ligeramente doraditas, volteándolas una vez solamente.'),
  (123, 4, 'Drain the patties on paper towel.', 'Coloque las tortitas sobre una toallita de papel para que esta absorba el exceso de aceite.'),
  (123, 5, 'For dipping sauce, combine garlic, green onion, soy sauce, vinegar, and sugar in a dish, and mix well.', 'Para la salsa, combine el ajo, la cebollita, salsa de soya, vinagre, y azúcar en un tazón chico y mezcle bien.'),
  (124, 1, 'Wash potatoes under cold water.', 'Lave las papas con agua fría.'),
  (124, 2, 'Cut the potatoes into medium-sized chunks, the width of your thumb.', 'Corte las papas en trozos medianos, del ancho de su dedo pulgar.'),
  (124, 3, 'Fill a pot with cold water and add potatoes. Bring to a boil.', 'Llene una olla con agua fría y ponga las papas en la misma. Dejar que hierva.'),
  (124, 4, 'Cover loosely and cook for 15 minutes.', 'Cubra la olla de manera holgada sin taparla totalmente y cocine por 15 minutos.'),
  (124, 5, 'Test the potatoes with a fork to make sure they are soft, but not falling apart.', 'Pruebe las papas con un tenedor para asegurarse de que estén suaves y tiernas, pero no deshaciéndose.'),
  (124, 6, 'Drain the potatoes.', 'Cuele el agua.'),
  (124, 7, 'Add salt, pepper, or other seasonings.', 'Añada sal, pimienta, u otros condimentos.'),
  (124, 8, 'You can also mash the cooked potatoes and season to taste.', 'Usted también puede machacar las papas ya cocidas, para hacer un puré, sazonándolo a su gusto.'),
  (125, 1, 'Set the oven temperature to 400 degrees.', 'Seleccione la temperatura del horno a 400 grados.'),
  (125, 2, 'Wash potatoes under cold water. Stick the potatoes all over with a fork or sharp knife.', 'Lave las papas con agua fría. Hágale huecos a las papas por todos lados usando un tenedor o un cuchillo delgado y filoso.'),
  (125, 3, 'Bake for 45 minutes to 1 hour, or until soft.', 'Hornee por 45 minutos a 1 hora, o hasta que estén suaves y tiernas.'),
  (125, 4, 'Lightly coating the potato with vegetable oil before cooking will make the potato skin crispy.', 'Cubra las papas ligeramente con aceite vegetal antes de meterlas al horno. Esto hará que las cáscaras queden crujientes al ser horneadas.'),
  (125, 5, 'Add seasonings or other toppings, if desired.', 'Añada condimentos u otros ingredientes, si desea.'),
  (125, 6, 'You can also mash the cooked potatoes and season to taste.', 'Usted también puede machacar las papas ya cocidas y sazonar al gusto.'),
  (126, 1, 'Wash potatoes under cold water. Stick the potatoes all over with a fork or sharp knife.', 'Lave las papas con agua fría. Hágale huecos a las papas por todos lados usando un tenedor o un cuchillo delgado y filoso.'),
  (126, 2, 'If cooking only one potato, place it in the center of the microwave on a paper towel.', 'Si solo está cocinando una papa, póngala en el centro del horno de microondas sobre una toalla de papel.'),
  (126, 3, 'Microwave one potato on high power for 5 minutes or more, turning the potato once during cooking. Remove and let stand for about 2 minutes.', 'Cocine una papa en el horno de microondas a temperatura alta por 5 minutos o más, volteándola una vez mientras se esta cocinando. Saque la papa y déjela reposar por 2 minutos.'),
  (126, 4, 'If cooking more than one, place the potatoes at least one inch apart.', 'Si va a cocinar más de una papa a la vez, coloque las papas con por lo menos una pulgada de separación.'),
  (126, 5, 'Cook two potatoes for about 12 minutes; three potatoes for about 15 minutes; four potatoes for about 18 minutes. Cook until soft. Remove potatoes from the microwave and let stand for about 2 minutes before serving.', 'Si va a cocinar dos papas, cocínelas por cerca de 12 minutos; si son tres papas por cerca de 15 minutos; si son cuatro papas por cerca de 18 minutos. Siempre cocínelas hasta que estén suaves. Saque las papas del horno de microondas y déjelas reposar por 2 minutos antes de servirlas.'),
  (126, 6, 'Add seasonings or other toppings, if desired.', 'Añada condimentos u otros ingredientes, si lo desea.'),
  (126, 7, 'You can also mash the cooked potatoes and season to taste.', 'Usted también puede machacar las papas ya cocidas y sazonarlas a su gusto.'),
  (128, 1, 'Wash potatoes under cold water.', 'Lave las papas con agua fría.'),
  (128, 2, 'Cut potatoes into medium-size chunks.', 'Corte las papas en trozos medianos.'),
  (128, 3, 'Fill a pot with cold water and add potatoes. Add a couple of pinches of salt and garlic. Bring to a boil and cook until soft, 15-20 minutes.', 'Llene una olla con agua fría y ponga las papas en la misma. Agréguele el ajo y un par de pizcas de sal. Deje que hierva y cocine hasta que las papas se pongan blandas, de 15-20 minutos.'),
  (128, 4, 'Drain the potatoes and garlic.', 'Cuele las papas y el ajo.'),
  (128, 5, 'Use a potato masher or large fork to mash the potatoes and garlic together.', 'Use un triturador de papas o un tenedor grande para machacar juntos las papas y el ajo.'),
  (128, 6, 'Add yogurt or buttermilk or milk, if you like.', 'Añada yogur, o leche cremosa/agria tipo "buttermilk", o leche regular, si lo desea.'),
  (128, 7, 'Season with a pinch of salt and pepper, chopped chives, green onion, or other seasonings.', 'Sazone con una pizca de sal y pimienta, cebollitas picadas, u otros condimentos.'),
  (128, 8, 'Do not freeze leftovers if you add yogurt, buttermilk, or milk.', 'Si le añade yogur, leche cremosa, o simple leche, no vaya a congelar lo que le sobre.'),
  (129, 1, 'Wash potatoes under cold water.', 'Lave las papas con agua fría.'),
  (129, 2, 'Slice unpeeled potatoes into ¼ inch thick slices.', 'Corte las papas sin pelar en tajadas de ¼ de pulgada de ancho.'),
  (129, 3, 'Lightly coat a baking dish with vegetable oil.', 'Cubra ligeramente con aceite vegetal una charola para hornear.'),
  (129, 4, 'Lightly toss potato slices with oil and seasonings.', 'Mezcle Ligeramente las tajadas de papa con aceite y condimentos.'),
  (129, 5, 'Place potatoes in baking dish, using two layers if needed.', 'Coloque las papas en la charola para hornear, haciendo 2 capas si es necesario.'),
  (129, 6, 'Sprinkle with cheese, between layers and on top.', 'Vierta/esparza el queso, por encima y entre las capas de papas.'),
  (129, 7, 'Add milk so that it barely covers the potatoes.', 'Añada leche de modo que apenas cubra las papas.'),
  (129, 8, 'Bake in 350 degree oven until soft, about one hour.', 'Hornee a 350 grados hasta que estén suaves, en aproximadamente una hora.'),
  (130, 1, 'Boil or microwave whole potatoes until soft; let potatoes cool and cut them into chunks; sprinkle with salt or pepper, to taste.', 'Hierva o cocine las papas en un horno de microondas hasta que estén blandas; deje enfriar las papas y córtelas en pedazos; rocíe con sal o pimienta, al gusto.'),
  (130, 2, 'Chop onions and celery.', 'Pique las cebollas y el apio.'),
  (130, 3, 'Cook eggs in almost boiling water for 15 minutes; cool under cold running water, peel, and chop.', 'Ponga los huevos a cocer en agua que esté casi hirviendo por 15 minutos; enfríe bajo agua fría, pélelos y píquelos.'),
  (130, 4, 'In a bowl, mix potatoes with onion, celery, and eggs.', 'En un recipiente hondo o tazón, mezcle las papas con las cebollas, el apio y los huevos.'),
  (130, 5, 'Combine mayonnaise or yogurt with mustard, to make dressing.', 'Combine la mayonesa o yogurt con la mostaza, para hacer el aderezo/aliñó.'),
  (130, 6, 'Add dressing to the potato mixture and stir until all ingredients are coated.', 'Añada el aderezo/aliñó a la mezcla de papa y revuelva hasta que todos los ingredientes queden cubiertos con el aderezo.'),
  (130, 7, 'Refrigerate before serving.', 'Refrigere antes de servir.'),
  (131, 1, 'Wash potatoes under cold water.', 'Lave las papas con agua fría.'),
  (131, 2, 'Peel and slice the potatoes as thick as a pencil.', 'Pele y corte las papas en tajadas de ¼ de pulgada, como del grosor de un lápiz.'),
  (131, 3, 'Put oil in pot on low heat. Add potatoes, onions, celery, and garlic. Sprinkle with flour and cook for 5 minutes, until vegetables are soft.', 'Ponga el aceite a calentar en una olla a fuego lento. Añada las papas, cebollas, apio y ajo. Espolvoree la harina y cocine por 5 minutos, hasta que las verduras estén blandas.'),
  (131, 4, 'Add water to cover the vegetables and bring to a boil.', 'Añada agua hasta cubrir los vegetales y deje hervir.'),
  (131, 5, 'Boil until potatoes begin to fall apart, about 20 minutes.', 'Hierva hasta que las papas empiecen a deshacerse, en aproximadamente 20 minutos.'),
  (131, 6, 'Add a can of corn (drained), or a small package of frozen corn (thawed).', 'Añada la lata de elote (sin jugo), o un paquete pequeño de elote congelado (pero ya descongelado).'),
  (131, 7, 'Milk or broth may be added.', 'Se puede añadir leche o caldo.'),
  (131, 8, 'Season with salt and pepper.', 'Sazone con sal y pimienta.'),
  (133, 1, 'Wash potatoes under cold water.', 'Lave las papas con agua fría.'),
  (133, 2, 'Peel the potatoes and cut into slices, thick as a pencil.', 'Pele y corte las papas en tajadas de ¼ de pulgada, como del grosor de un lápiz.'),
  (133, 3, 'Bring about 1 inch of water to a boil in a pot.', 'Hierva 1 pulgada de agua en una olla.'),
  (133, 4, 'Place a steamer in the pot and place the potatoes in the steamer loosely.', 'Coloque un vaporizador de vegetales plegable (tipo canastita) en la olla y ponga las papas dentro del vaporizador de manera suelta.'),
  (133, 5, 'Cover the pot loosely and steam for 12-15 minutes.', 'Cubra la olla sin taparla totalmente y cocine de 12-15 minutos.'),
  (133, 6, 'Heat the oil in a pan; transfer potatoes to pan, sprinkle with seasonings, and cook, turning often until crispy and golden brown.', 'Caliente el aceite en un sartén; transfiera las papas al sartén, rocíe con condimentos, y cocine, volteándolas con frecuencia hasta que estén crujientes y doradas.'),
  (134, 1, 'Wash potatoes under cold water.', 'Lave las papas con agua fría.'),
  (134, 2, 'Cut the potatoes into slices, as thick as a pencil.', 'Corte las papas en tajadas de ¼ de pulgada, como del grosor de un lápiz.'),
  (134, 3, 'Bring about 1 inch of water to a boil in a pot.', 'Hierva 1 pulgada de agua en una olla.'),
  (134, 4, 'Place a steamer in the pot and place the potatoes in the steamer, loosely.', 'Coloque un vaporizador de vegetales plegable (tipo canastita) en la olla y ponga las papas dentro del vaporizador de manera suelta.'),
  (134, 5, 'Cover the pot loosely and steam for 15-20 minutes, or until tender.', 'Cubra la olla sin taparla totalmente y cocine de 15-20 minutos, o hasta que estén tiernas.'),
  (134, 6, 'Season with salt or pepper to taste, or use other seasonings.', 'Sazone con sal o pimienta al gusto, o use otros condimentos.'),
  (134, 7, 'You can also mash the cooked potatoes and season to taste.', 'Usted también puede machacar las papas ya cocidas y hacer un puré, sazonando al gusto.'),
  (135, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (135, 2, 'Wash potatoes under cold water. Cut into medium-sized chunks.', 'Lave las papas con agua fría. Corte en pedazos de tamaño mediano.'),
  (135, 3, 'Peel onions and cut into wedges. Cut other vegetables into chunks.', 'Pele las cebollas y corte en trozos tipo cuña. Corte los otros vegetales en pedazos cortos y anchos.'),
  (135, 4, 'Toss vegetables with 2 large spoons of oil, a pinch of salt and pepper, and other seasonings.', 'Mezcle los vegetales con 2 cucharadas grandes de aceite, una pizca de sal y pimienta, y otros condimentos.'),
  (135, 5, 'Coat the inside of a baking dish with 1 large spoon of oil.', 'Usando una cucharada de aceite cubra la parte interior de una charola para hornear.'),
  (135, 6, 'Bake for 55 minutes to 1 hour or until tender, turning several times; to reduce time, cut potatoes into smaller pieces.', 'Hornee de 55 minutos a 1 hora o hasta que los vegetales estén tiernos, volteando varias veces; si desea reducir el tiempo en el horno, corte las papas en pedazos pequeños.'),
  (135, 7, 'Add unpeeled garlic cloves (tossed in oil and seasonings) halfway through cooking, if you wish.', 'Si lo desea, puede añadir los dientes de ajo sin pelar (mezclados con aceite y condimentos) aproximadamente 30 minutos después de que haya puesto la charola en el horno.'),
  (136, 1, 'Wash potatoes thoroughly.', 'Lave las papas plenamente'),
  (136, 2, 'Fill a pot with cold water and a couple pinches of salt. Bring to a boil. Add whole potatoes and cook for about 25 minutes, until tender.', 'Llene una olla con agua fría y un par de pizcas de sal. Déjela que hierva. Agregue las papas enteras y cocine por 25 minutos, o hasta que estas estén blandas/tiernas.'),
  (136, 3, 'Drain potatoes and cut them into chunks.', 'Cuele las papas y córtelas en pedazos.'),
  (136, 4, 'To cook the spinach or greens, drop leaves into a large pot of boiling water and cook 1-2 minutes. Drain.', 'Para cocinar las espinacas u otras verduras de hoja verde, ponga las hojas en una olla grande con agua hirviendo y cocine de 1-2 minutos. Cuele.'),
  (136, 5, 'Add oil to a large frying pan and cook garlic for just 1 minute. Add potatoes and cook until slightly brown. Add tomatoes and cooked greens to the pan.', 'Vierta el aceite en un sartén y cocine el ajo por solo 1 minuto. Añada las papas y cocine hasta que se pongan ligeramente doraditas. A continuación, añada el jitomate y espinacas o berzas (ya cocidas).'),
  (136, 6, 'Add ground meat and cook until browned, stirring occasionally (optional).', 'Agregue la carne molida y cocine hasta que se dore, agitando/revolviendo todo ocasionalmente (opcional).'),
  (136, 7, 'Cook over medium heat for 5-10 minutes, until mixed and heated.', 'Cocine a fuego medio de 5-10 minutos, hasta que todo este bien mezclado y caliente.'),
  (136, 8, 'Add seasonings to taste.', 'Añada condimentos/sazonadores al gusto.'),
  (137, 1, 'Bake the potatoes in the oven, microwave, or toaster oven until soft.', 'Cocine las papas en el horno, en un horno de microondas, o un horno tostador eléctrico hasta que estén blandas.'),
  (137, 2, 'Cool potatoes and cut into cubes.', 'Enfríe las papas y corte en cubos.'),
  (137, 3, 'Mix the potatoes and the chili together; add salsa or hot sauce, if desired.', 'Mezcle juntos las papas y el chili; añada la salsa regular o picante, si lo desea.'),
  (137, 4, 'Heat in 350 degree oven for 15-20 minutes, or in the microwave on high for 5 minutes until hot.', 'Caliente en el horno a 350 grados por 15-20 minutos, o en un horno de microondas a temperatura alta por 5 minutos, hasta que esté caliente.'),
  (137, 5, 'Top with cheese, onion, or other extras (optional).', 'Cubra por encima con queso, cebolla u otros extras, si lo desea.'),
  (138, 1, 'Bake the potatoes in the oven, microwave, or toaster oven.', 'Cocine las papas en el horno, en un horno de microondas, o un horno tostador eléctrico.'),
  (138, 2, 'Drain can of beans and combine with an equal amount of salsa. Put in a saucepan and heat until warm.', 'Cuele la lata de frijoles y combine con una cantidad igual de salsa. Ponga en una olla o cacerola, y caliente hasta que esté tibio.'),
  (138, 3, 'Serve the bean-salsa mixture over the potato.', 'Sirva la mezcla de salsa con frijoles sobre la(s) papa(s).'),
  (138, 4, 'Top with sour cream, yogurt, or shredded cheese.', 'Remate con crema agria, yogur o queso rayado.'),
  (139, 1, 'Preheat oven to 425 degrees.', 'Precalentar el horno a 425 grados.'),
  (139, 2, 'Line a baking dish with aluminum foil.', 'Cubra un recipiente para hornear con papel de aluminio.'),
  (139, 3, 'Cut potatoes into slices as thick as a pencil; pat dry and toss potatoes lightly with 1-2 large spoons of oil and a pinch of salt, pepper, or other favorite seasonings.', 'Corte las papas en pedazos del grosor de un lápiz; séquelas y revuelva las papas ligeramente usando 1-2 cucharadas grandes de aceite y una pizca de sal, pimienta, u otros sazones/condimentos favoritos.'),
  (139, 4, 'Spread the potatoes in the baking dish and bake for 12 minutes.', 'Distribuya las papas en el recipiente para hornear y cocine por 12 minutos.'),
  (139, 5, 'Remove pan from the oven and move the potatoes to the sides of the dish.', 'Saque el recipiente del horno y mueva las papas hacia los lados/orillas del mismo.'),
  (139, 6, 'Rub chicken breasts with a 1-2 large spoons of oil and a pinch of salt or pepper or other seasonings; place chicken in the baking dish.', 'Frote las pechugas de pollo con 1-2 cucharadas grandes de aceite y una pizca de sal, pimienta, u otros sazones/condimentos; coloque el pollo en el recipiente para hornear.'),
  (139, 7, 'Bake for 20 minutes or until the chicken is no longer pink inside.', 'Cocine por 20 minutos o hasta que el pollo ya no este rosita por dentro.'),
  (139, 8, 'In a small bowl, combine the cheese with salsa or chopped tomatoes; sprinkle this mixture over the cooked chicken.', 'En un tazón chico, combine el queso con la salsa o jitomates picados; distribuya esta mezcla por encima del pollo ya cocido.'),
  (139, 9, 'Bake for another 5 minutes or so, until the cheese is melted.', 'Cocina en el horno por otros 5 minutos más o menos, hasta que el queso se haya derretido.'),
  (140, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (140, 2, 'Peel potatoes and steam or boil them.', 'Pele las papas y cocínelas al vapor o hirviéndolas.'),
  (140, 3, 'Mash potatoes, adding salt, pepper, or seasonings and a bit of milk, so that the potatoes will spread easily.', 'Machaque las papas, añada sal, pimienta, u otros condimentos y un poco de leche, de modo que las papas se extiendan fácilmente (como puré).'),
  (140, 4, 'Heat oil in a pan, cook onion and garlic for 2-3 minutes.', 'Caliente el aceite en un sartén, y cocine la cebolla y el ajo de 2-3 minutos.'),
  (140, 5, 'Add meat and brown for 3-5 minutes. Drain the fat, and place mixture in bottom of a greased baking dish.', 'Añada la carne y dore de 3-5 minutos. Filtre la grasa, y coloque la mezcla en una charola para hornear previamente engrasada.'),
  (140, 6, 'Cover the meat mixture with the corn.', 'Cubra la mezcla de la carne con el elote.'),
  (140, 7, 'Spread the mashed potatoes on top of the corn.', 'Esparza el puré de papas por encima del elote.'),
  (140, 8, 'Bake 30 minutes at 350 degrees, or until the potatoes are light brown.', 'Hornee por 30 minutos a 350 grados, o hasta que "el puré" esté un poco dorado.'),
  (141, 1, 'Place the pieces in a steamer basket and steam for about 10­-15 minutes or drop the pieces into boiling water and cover, simmering for approximately 5-8 minutes, until tender when pierced with a fork.', 'Coloque los pedazos de los vegetales ya sea en una canastita para cocer al vapor de 10 a 15 minutos, o viértalos en una olla con agua ya hirviendo y cubra con una tapadera. Déjelos cociendo aproximadamente de 5 a 8 minutos, hasta que usted sienta que están tiernos al pincharlos con un tenedor.'),
  (141, 2, 'When pieces are soft enough to mash, place them in a bowl and blend with a potato masher. Add butter or margarine, cheese, yogurt, and seasonings. Add small amounts of water or low-fat milk if mixture is too thick.', 'Una vez que los pedazos estén lo suficientemente tiernos para ser machacados, póngalos en un recipiente hondo, mézclelos y tritúrelos con un machacador para papas. Agregue la mantequilla o margarina, el queso, yogur, y los sazonadores. Añada agua o leche baja en grasas en pequeñas cantidades si la mezcla esta muy espesa.'),
  (141, 3, 'Do not freeze if you add milk, cheese, or yogurt.', 'Si le agrego queso, leche o yogur, no congele lo que le sobre.'),
  (142, 1, 'Peel and cut off the ends of the turnips (or rutabagas or parsnips). Cut into chunks.', 'Pele y corte los extremos de los nabos (o colinabos o pastinacas). Corte los vegetables en pedazos cortos y gruesos.'),
  (142, 2, 'Drop the turnips (or rutabagas or parsnips) into boiling water, cover, and cook approximately 5-8 minutes, until soft.', 'Vierta los nabos (o colinabos o pastinacas) en agua hirviendo, cubra con una tapa y cueza aproximadamente de 5­-8 minutos, hasta que queden tiernos.'),
  (142, 3, 'Drain and season to taste.', 'Cuélelos y añada sus sazonadores al gusto.'),
  (143, 1, 'Wash, peel and cut off the ends of the rutabagas or turnips or parsnips.', 'Lave y pele los nabos, o colinabos, o pastinacas y córtele los extremos.'),
  (143, 2, 'Cut vegetables into pieces and place in a microwavable dish with the water or broth.', 'Corte los vegetales en pedazos y colóquelos en un recipiente apropiado para el horno de microondas. Agréguele el agua, o caldo.'),
  (143, 3, 'Cover with plastic wrap and cook on high.', 'Cubra usando un rollo transparente de plástico y cocine a temperatura alta.'),
  (143, 4, 'Rutabagas (in photo) cook 5 minutes; turnips cook 3 minutes; parsnips cook 3 minutes.', 'Colinabos (en la foto) cocine por 5 minutos; nabos cocine por 3 minutos; pastinacas cocine por 3 minutos.'),
  (143, 5, 'Season to taste.', 'Sazone al gusto.'),
  (144, 1, 'Peel and cut off the ends of the rutabagas (or turnips or parsnips).', 'Pele los nabos, o colinabos, o pastinacas y córtele los extremos.'),
  (144, 2, 'Put water in a pot so that it does not touch the steamer basket. Bring water to a boil.', 'Ponga agua en una olla pero evite que esta vaya a tocar la parte de abajo del vaporizador plegable o canastita. Deje que el agua hierva.'),
  (144, 3, 'Cut rutabagas into pieces and place in a steamer basket.', 'Corte los colinabos en pedazos y póngalos en la canastita (vaporizador).'),
  (144, 4, 'Place the steamer into pot and cover loosely.', 'Coloque la canastita dentro de la olla con el agua hirviendo y cúbrala con una tapadera no ajustada.'),
  (144, 5, 'Cook on high for approximately 10­-15 minutes, until tender.', 'Cueza a fuego alto de 10­-15 minutos aproximadamente, hasta que los pedazos estén tiernos.'),
  (144, 6, 'Season with salt, pepper, other favorite seasonings (optional).', 'Sazone con sal, pimienta u otros condimentos favoritos.'),
  (145, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (145, 2, 'Coat baking sheet with vegetable oil.', 'Unte el aceite a una charola para hornear.'),
  (145, 3, 'Combine melted butter or margarine, sugar, and ginger in a bowl.', 'Combine la mantequilla o margarina derretida, con el azúcar y jengibre en un recipiente hondo.'),
  (145, 4, 'Add turnips (or parsnips or rutabagas or a combination) to the butter or margarine mixture and toss.', 'Añada los nabos (o pastinacas o colinabos, o una combinación de ellos) a la mezcla de la mantequilla o margarina y revuelva bien.'),
  (145, 5, 'Place on baking sheet and cook for 35 minutes or until tender, stirring every 15 minutes.', 'Coloque todo en la charola para hornear y cocine a 400 grados por 35 minutos, o hasta que estén tiernos, agitado todo cada 15 minutos.'),
  (146, 1, 'Wash and peel the turnips (or rutabagas or parsnips) and cut into bite-sized pieces.', 'Lave y pele los nabos (o colinabos o pastinacas) y corte en pedazos del tamaño de un bocado.'),
  (146, 2, 'Heat 1 large spoon of the butter or margarine in a frying pan over medium heat.', 'Caliente una cucharada grande de mantequilla o margarina en un sartén a fuego medio.'),
  (146, 3, 'Add the maple syrup, cinnamon, salt and pepper and stir.', 'Agréguele la miel de Maple, canela, sal y pimienta y agite todo.'),
  (146, 4, 'Add the vegetables and then add 2 large spoons of water.', 'Añada los vegetales y vierta 2 cucharadas grandes de agua.'),
  (146, 5, 'Bring to a boil, cover, reduce heat to medium and steam until turnips are tender, about 7­-8 minutes.', 'Deje que hierva, cubra con una tapadera, reduzca la intensidad del fuego y deje que se guisen los nabos hasta que estén tiernos, de 7­-8 minutos.'),
  (146, 6, 'Uncover and continue to cook until the liquid has reduced and the turnip pieces are glazed with the syrup and spices, about 3 more minutes.', 'Quite la tapadera y continué cocinando por aproximadamente 3 minutos mas, hasta que el "liquido" se haya condensado y los pedazos de los nabos estén cubiertos/glaseados con la miel y los sazonadores.'),
  (146, 7, 'Add the remaining margarine along with the lemon juice. Shake the pan to coat the turnips evenly.', 'Añada la mantequilla o margarina restante junto con el jugo de limón. Agite el sartén para revestir los nabos uniformemente.'),
  (147, 1, 'Preheat oven to 375 degrees. Cook chicken and vegetables in two different pans.', 'Precaliente el horno a 375 grados. Guise el pollo y los vegetales en dos recipientes/cacerolas diferentes.'),
  (147, 2, 'Mix mustard, oil, and herbs or spices in bowl.', 'Mezcle la mostaza, aceite y hierbas aromáticas o especies en un recipiente hondo.'),
  (147, 3, 'Rub chicken with pepper. Brush inside and out with half of mustard mixture. Place breast down in an oiled roasting pan and cook.', 'Frote el pollo con la pimienta. Usando una brochita, úntele al pollo por dentro y por fuera la mitad de la mezcla de mostaza y aceite. Coloque el pollo con la pechuga hacia abajo en un recipiente propio para asar, al cual se la haya untado aceite con anterioridad y póngalo en el horno.'),
  (147, 4, 'After 15 minutes, turn chicken on its back and continue roasting until done, about 1 hour total.', 'Después de 15 minutos, ponga al pollo de espalda y continué asando, como por 1 hora en total.'),
  (147, 5, 'Meanwhile, brush another baking sheet with oil.', 'Mientras se cocina el pollo, aplíquele aceite a una charola para hornear.'),
  (147, 6, 'Toss onions, parsnips (or turnips or rutabagas), and carrots with remaining mustard mixture in bowl.', 'Ponga las cebollas, pastinacas (o nabos o colinabos), y zanahorias en un recipiente hondo con la otra mitad de la mezcla de mostaza y aceite y revuelva bien todo.'),
  (147, 7, 'Spread vegetables on oiled baking sheet.', 'Esparza los vegetales en la charola para hornear a la cual se le unto aceite con anterioridad.'),
  (147, 8, 'After chicken has been in the oven for 20-30 minutes, put vegetables in the oven and cook until tender and beginning to brown, turning once. Cook about 30-40 minutes total.', 'Después de que el pollo haya estado en el horno de 20-30 minutos, ponga la charola con los vegetales en el horno hasta que estén tiernos y se empiecen a dorar, volteándolos una vez. Cocine de 30-40 minutos en total.'),
  (147, 9, 'Transfer chicken to platter and serve with vegetables.', 'Transfiera el pollo a la charola y sírvalo con los vegetales.'),
  (148, 1, 'Preheat oven to 400 degrees. Lightly coat a baking dish with cooking spray or oil.', 'Precaliente el horno a 400 grados. Cubra de manera leve, una charola para hornear con un poco de aceite o un rociador para hornear antiadherente.'),
  (148, 2, 'Keep the parsnips in a separate bowl and mix with a little oil and melted butter or margarine and seasonings.', 'Ponga las pastinacas por separado en un recipiente hondo y mezcle con un poco de aceite y mantequilla o margarina derretida, y sus sazonadores.'),
  (148, 3, 'In another bowl, mix all of the other vegetables together with oil and melted butter or margarine and seasonings.', 'En otro recipiente hondo, mezcle el resto de los vegetales y mezcle con un poco de aceite y mantequilla o margarina derretida, y sus sazonadores.'),
  (148, 4, 'Place the rutabagas, turnips, and other vegetables into the baking dish and cook for about 10 minutes.', 'Coloque los colinabos, nabos, y los otros vegetales (excepto las pastinacas) sobre la charola para hornear y cocine por 10 minutos.'),
  (148, 5, 'Add the parsnips to the baking dish and continue cooking for another 15 minutes, or until the vegetables are tender and brown. Stir once or twice, while cooking.', 'Agréguele las pastinacas a la charola y continúe horneando por otros 15 minutos, o hasta que los vegetales estén tiernos y doraditos. Agite/revuelva los vegetales un par de veces mientras se cocinan.'),
  (149, 1, 'Mix oil, vinegar, and salt in medium bowl to make a sauce. Set aside.', 'En un recipiente hondo y mediano, mezcle aceite, vinagre y sal para preparar una salsa. Reserva.'),
  (149, 2, 'Bring a large pot of water to a boil. Add turnips (or rutabagas or parsnips) and cook about 10-12 minutes. Then, add green beans and cook an additional 3-4 minutes. Vegetables should be crisp. Drain.', 'Ponga una olla grande con agua a hervir. Añada nabos (o colinabos o pastinacas) y cocine por 10-12 minutos. A continuación, agréguele los ejotes y siga cocinando todo por 3-4 minutos adicionales. Las verduras deberán estar crujientes. Cuele todo.'),
  (149, 3, 'Heat sauce in a large frying pan over low heat until warm.', 'Caliente la salsa en un sartén grande a fuego lento hasta que esta este calientita.'),
  (149, 4, 'Add turnips, beans, and peas. Toss until heated through and coated with sauce, about 5 minutes.', 'Vierta en el sartén los nabos, ejotes y chícharos. Distribuya y agite todo alrededor de 5 minutos hasta que las verduras estén calientes y bien cubiertas con la salsa.'),
  (149, 5, 'Season to taste with additional salt and pepper.', 'Sazone al gusto con más sal y pimienta.'),
  (150, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (150, 2, 'Cut off tip of garlic head and discard. Place head in small baking dish, pour a little oil on the garlic, sprinkle with pepper, and bake for 40 minutes. Cool the garlic head. Squeeze the garlic into a small dish.', 'Corte la parte de arriba de la cabecita de ajo y tírela. Ponga la cabecita de ajo en un recipiente pequeño para hornear. Vierta un poco de aceite sobre el ajo y espolvoree un poco de pimienta y colóquelo en el horno por 40 minutos. Deje enfriar la cabecita de ajo. Estruja el ajo en un recipiente chico.'),
  (150, 3, 'Drop rutabagas (or turnips or parsnips) into a pot of boiling water. Cook until very tender, about 10 minutes. Drain.', 'Vierta los colinabos (o nabos o pastinacas) en una olla de agua hirviendo. Cueza por aproximadamente 10 minutos, hasta que los vegetales queden blanditos. Cuele el agua.'),
  (150, 4, 'Combine vegetables in bowl with garlic, yogurt, butter or margarine, and salt or pepper.', 'Combine los vegetales en un recipiente hondo con el ajo, yogur, mantequilla o margarina, y sal o pimienta.'),
  (150, 5, 'Blend with a potato masher, or use an electric blender. Add small amounts of water or milk if mixture is too thick.', 'Machaque/muela todo con un machacador de papas, o usando una licuadora. Añada pequeñas cantidades de agua o leche si el puré esta muy espeso.'),
  (150, 6, 'Do not freeze if you add yogurt.', 'No congele lo que le sobre si uso yogur.'),
  (151, 1, 'Cook ginger in oil over low heat for 1-2 minutes.', 'En un sartén grande guise el jengibre en aceite a fuego lento de 1­-2 minutos.'),
  (151, 2, 'Add meat and cook over high heat 3-4 minutes and stir occasionally.', 'Añada la carne y guise a alta temperatura de 3­-4 minutos revolviendo ocasionalmente.'),
  (151, 3, 'Add rutabagas (or turnips or parsnips), cook for 5-8 minutes, stirring occasionally.', 'Agregue los colinabos (o nabos o pastinacas), y guise de 5­-8 minutos, meneando ocasionalmente.'),
  (151, 4, 'Stir in water, soy sauce, sugar, and salt and bring to a boil for 1 minute.', 'Añada el agua, la salsa de soya, azúcar y sal, y deje que hierva por 1 minuto.'),
  (151, 5, 'Turn heat down to low and cook for 5 minutes.', 'Disminuya la llama a fuego lento y guise por 5 minutos más.'),
  (151, 6, 'Serve over rice or noodles (optional).', 'Sirva sobre tallarines o arroz, preparados de acuerdo a las instrucciones de sus respectivos paquetes (opcional).'),
  (152, 1, 'Mix grated potato and turnips (or rutabagas or parsnips) together.', 'Mezcle la papa y nabos rallados (o colinabos o pastinacas) juntos.'),
  (152, 2, 'Squeeze in a paper towel to remove as much moisture as possible.', 'Estruja en una toallita de papel para eliminar el exceso de agua/humedad.'),
  (152, 3, 'Add egg, breadcrumbs or flour, onion (optional), salt, and pepper and mix well.', 'Añada el huevo, pan molido o harina, la cebolla (opcional), sal y pimienta y mezcle todo bien.'),
  (152, 4, 'Heat oil in a frying pan.', 'Ponga a calentar el aceite en un sartén.'),
  (152, 5, 'Form potato mixture into four tightly packed patties.', 'Usando la mezcla de papas y otros ingredientes, forme cuatro tortitas bien compactas usando sus manos.'),
  (152, 6, 'Cook patties on each side, about 5 minutes, turning once. They should be lightly browned.', 'Guise las tortitas por 5 minutos por lado, volteándolas solo una vez. Las tortitas deberán estar un poco doraditas.'),
  (152, 7, 'Transfer to paper towels to soak up the excess oil.', 'Colóquelas sobre unas toallas de papel para que estas absorban el exceso de aceite.'),
  (152, 8, 'Serve pancakes with applesauce, salsa, non-fat sour cream, or plain yogurt, if desired.', 'Sírvalas con puré o compota de manzana, salsa, crema agria sin grasa, o yogur sin sabor, si así lo prefiere.'),
  (153, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (153, 2, 'Coat baking sheet with vegetable oil.', 'Frote y cubra una charola para hornear con el aceite.'),
  (153, 3, 'Combine melted butter or margarine, sugar, salt and pepper flakes in a bowl.', 'Combine la mantequilla o margarina derretida con el azúcar, sal y hojuelas de chile en un recipiente hondo.'),
  (153, 4, 'Add rutabagas (or parsnips or turnips or a combination) to the margarine mixture and toss.', 'Añada los colinabos (o pastinacas o nabos o una combinación de ellos) a la mezcla de margarina y revuelva bien.'),
  (153, 5, 'Place on baking sheet and cook for 35 minutes or until tender, stirring every 15 minutes.', 'Vierta todo sobre la charola y coloque en el horno por 35 minutos o hasta que los vegetales estén tiernos, revolviendo todo cada 15 minutos.'),
  (154, 1, 'Heat pot of water to boiling, add turnips (or rutabagas or parsnips or a combination) and cook until tender, about 15 minutes.', 'Ponga agua a hervir en una olla, agréguele los nabos (o colinabos, o pastinacas, o una combinación de ellos) y cueza por aproximadamente 15 minutos, hasta que se ponga tiernos.'),
  (154, 2, 'Drain turnips, mash, and drain off any excess liquid.', 'Cuele los nabos, macháquelos y elimine cualquier exceso de líquido.'),
  (154, 3, 'Stir in beaten egg, saltines, milk, salt and pepper, and cheese. Blend well.', 'Vierta el huevo batido, las galletas saladas (machacadas), leche, sal, pimienta y queso. Mezcle bien todo.'),
  (154, 4, 'Pour into a buttered or oiled Crock­Pot. Cook on high for 2 hours.', 'Transfiera todo a la olla estilo "Crock­Pot" después de haberle untado aceite o mantequilla en el interior de esta misma. Guise a temperatura alta por 2 horas.'),
  (155, 1, 'Heat butter, margarine or oil in a pan and fry the turnips (or parsnips or rutabagas or a combination) until they start to get soft.', 'Caliente la mantequilla, margarina o aceite vegetal en un sartén y fría los nabos (o pastinacas o colinabos o una combinación de ellos) hasta que se empiecen a ablandar.'),
  (155, 2, 'Season with salt, pepper and brown sugar and continue cooking until tender.', 'Sazone con sal, pimienta y azúcar morena y continúe guisando hasta que estén tiernitos.'),
  (156, 1, 'Heat butter or margarine in the bottom of a large pot. Cook onions until soft.', 'Caliente la mantequilla o margarina en una olla grande. Guise las cebollas hasta que se ablanden.'),
  (156, 2, 'Add turnips (or rutabagas or parsnips) and potatoes to pot. Add broth to 1 inch over the top of the mixture and cook for 15­-20 minutes until tender.', 'Ponga los nabos (o colinabos o pastinacas) y las papas en la olla. Agregue suficiente caldo para cubrir todo a un nivel de aproximadamente una pulgada por encima de los vegetales. Guise de 15­-20 minutos hasta que los vegetales estén tiernos.'),
  (156, 3, 'If desired, mix in a blender or food processor and add a little more broth.', 'Si usted lo desea, mezcle todo en una licuadora o una procesadora de alimentos y agréguele un poco mas de caldo.'),
  (156, 4, 'Season with salt and pepper to taste.', 'Sazone con sal y pimienta al gusto.'),
  (157, 1, 'Heat butter or margarine in the bottom of a large pot.', 'Caliente la mantequilla o margarina en una olla grande.'),
  (157, 2, 'Add parsnips (or turnips or rutabagas or a combination), onions, and garlic and cook until onions are soft but not brown.', 'Añada las pastinacas (o nabos o colinabos o una combinación de ellos), cebollas, y ajo y guise hasta que las cebollas estén blanditas pero evitando que se doren.'),
  (157, 3, 'Add broth to cover vegetables. Simmer until vegetables are soft, about 30-40 minutes.', 'Agréguele el caldo cubriéndolo todo. Cocine a fuego lento aproximadamente de 30-40 minutos, hasta que los vegetales se ablanden.'),
  (157, 4, 'Remove from heat. Blend in a blender or food processor.', 'Quite la olla de la estufa. Mezcle todo en una licuadora o procesadora de alimentos.'),
  (157, 5, 'Stir in maple syrup.', 'Añada la miel de Maple sin dejar de revolver/mezclar.'),
  (158, 1, 'Preheat oven to 350 degrees. Lightly grease a baking dish.', 'Precaliente el horno a 350 grados. Úntele aceite a una charola para hornear de manera leve.'),
  (158, 2, 'Grate parsnips (or rutabagas or turnips or a combination) and squeeze water out in a towel.', 'Ralle las pastinacas (o colinabos o nabos o una combinación de ellos) y estruja en una toallita de papel para eliminar el exceso de agua.'),
  (158, 3, 'Heat frying pan and add vegetable oil and butter or margarine. Add vegetables and cook for 15 minutes, on medium heat, until brown.', 'Caliente un sartén y añada el aceite vegetal y mantequilla o margarina. Agréguele los vegetales y guise a fuego medio por 15 minutos, hasta que se doren.'),
  (158, 4, 'Combine soup, mustard, and pepper in a large bowl and mix well.', 'Combine la sopa (de hongos), mostaza, y pimienta en un recipiente hondo y revuelva bien todo.'),
  (158, 5, 'Add vegetables, meat (optional), green onions (optional), ½ cup of cheese.', 'Agregue los vegetales, carne o pollo (opcional), cebollitas (opcional) y ½ taza de queso.'),
  (158, 6, 'Spoon some of the mixture into the center of a tortilla. Fold in sides of each tortilla.', 'Usando una cuchara, coloque algo de la "mezcla" en el centro de una tortilla. Doble hacia adentro los lados de cada tortilla, como si fueran empanadas.'),
  (158, 7, 'Place in a greased baking dish.', 'Ponga los tacos en la charola para hornear.'),
  (158, 8, 'Bake for 15 minutes.', 'Coloque la charola en el horno y cocine por 15 minutos.'),
  (158, 9, 'Sprinkle with remaining cheese. Bake 5­-10 minutes more.', 'Espolvoree el queso restante. Hornee de 5­-10 minutos adicionales.'),
  (158, 10, 'Serve with salsa (optional).', 'Sirva con salsa (opcional).'),
  (159, 1, 'Mix the orange juice and the honey in a pot. Bring the mixture to a boil over high heat.', 'Mezcle el jugo de naranja y la miel en una olla. Ponga en la estufa y deje que hierva a alta temperatura.'),
  (159, 2, 'Stir in the vegetables.', 'Vierta los vegetales revolviendo todo.'),
  (159, 3, 'Bring to a boil again and simmer, covered, for 10­-15 minutes.', 'Deje que la "mezcla" hierva otra vez, reduzca a fuego lento, cubra con una tapa y siga guisando de 10­-15 minutos.'),
  (159, 4, 'Remove cover and continue cooking until the liquid thickens.', 'Quítele la tapadera y deje que se siga cocinando hasta que el líquido se ponga espeso.'),
  (160, 1, 'Preheat oven to 350 degrees. Lightly grease a baking dish.', 'Precaliente el horno a 350 grados. Úntele aceite de manera leve a una charola para hornear.'),
  (160, 2, 'Boil, steam, or microwave the turnips or parsnips or rutabagas. Drain and mash the vegetables.', 'Cocine los nabos, o pastinacas o colinabos ya sea hirviéndolos, al vapor o en el horno de microondas. Después, cuélelos y macháquelos.'),
  (160, 3, 'Spread half of the mashed vegetables in the bottom of the baking dish.', 'Esparza la mitad de los vegetales ya machacados sobre la charola para hornear.'),
  (160, 4, 'Mix the cinnamon and sugar in a bowl.', 'Combine y mezcle la canela y azúcar en un recipiente hondo.'),
  (160, 5, 'Dip the apple slices in the cinnamon and sugar mixture and then place on the layer of mashed vegetables.', 'Inmersa/meta las rebanadas de manzana en la mezcla de canela y azúcar, para después colocarlas sobre la capa de vegetales esparcida en la charola.'),
  (160, 6, 'Spread the remaining mashed vegetables on top of the apples.', 'Esparza el resto de los vegetales ya machacados por encima de las manzanas.'),
  (160, 7, 'Mix flour, brown sugar and butter (or margarine) together until crumbly.', 'Mezcle la harina, azúcar morena y mantequilla (o margarina) juntas, hasta que la misma se ponga desmenuzada.'),
  (160, 8, 'Sprinkle this flour mixture on top of the casserole.', 'Espolvoree esta mezcla por encima de los vegetales.'),
  (160, 9, 'Bake for 1 hour or until the top is crispy brown.', 'Ponga la charola en el horno por 1 hora, o hasta que la parte de arriba de la "mezcla" este doradita y crujiente.'),
  (161, 1, 'Fill a pot with water. Add sweet potatoes to water and bring to a boil.', 'Llene una olla con agua.  Añada los camotes y deje que el agua hierva.'),
  (161, 2, 'Cover loosely and simmer for 15 minutes.', 'Cubra la olla ligeramente y siga cocinando a fuego lento por 15 minutos.'),
  (161, 3, 'Test the sweet potatoes with a fork to make sure they are soft, but not falling apart.', 'Pinche los camotes con un tenedor para asegurarse de que estén suaves, pero que no se deshagan.'),
  (161, 4, 'Drain the sweet potatoes.', 'Cuele los camotes.'),
  (161, 5, 'Add salt, pepper, or other seasonings.', 'Añada sal, pimienta y otros condimentos.'),
  (161, 6, 'You can also mash the cooked sweet potatoes and season to taste.', 'También puede hacer puré con los camotes cocidos y sazonar al gusto.'),
  (162, 1, 'Heat the oven or counter top oven to 350 degrees.', 'Caliente el horno o un horno eléctrico pequeño a 350 grados.'),
  (162, 2, 'Wash sweet potatoes under cold water. Stick the potatoes all over with a fork or sharp knife.', 'Lave los camotes en agua fría. Con un tenedor o cuchillo filudo, haga huecos a los camotes por todos lados.'),
  (162, 3, 'Bake for 45 minutes to 1 hour, or until soft.', 'Hornee de 45 minutos a 1 hora, o hasta que estén suaves.'),
  (162, 4, 'Lightly coating the sweet potato with vegetable oil during cooking will make the potato skin crispy.', 'El cubrir ligeramente los camotes con aceite vegetal mientras se cocinan hará que la piel de los camotes se ponga crujiente.'),
  (162, 5, 'To serve, slit top of the cooked sweet potato and push ends toward each other.', 'Para servir, corte la porción superior del camote cocido y presione los extremos uno contra el otro.'),
  (162, 6, 'Add seasonings or other toppings, if desired. (Yogurt cannot be frozen.)', 'Añada condimentos y otros ingredientes, si desea. (El yogur no puede estar congelado).'),
  (162, 7, 'You can also scoop out the insides of the cooked sweet potatoes, mash, and season to taste.', 'También puede sacar el interior del camote con una cuchara, hacerlo puré, y sazonar al gusto.'),
  (163, 1, 'Wash sweet potato under cold water. Stick the sweet potato all over with a fork or sharp knife.', 'Lave el camote en agua fría. Con un tenedor o cuchillo filudo, hágale huecos al camote por todos lados.'),
  (163, 2, 'Place the sweet potato in the center of the microwave on a paper towel or microwavable dish.', 'Coloque el camote en el centro del microondas sobre una toallita de papel o un plato apropiado para microondas.'),
  (163, 3, 'Cook on high power for 3-5 minutes, turning the sweet potato once during cooking.', 'Cocine a fuego alto por 3-5 minutos, dándole vuelta al camote una vez mientras lo cocina.'),
  (163, 4, 'Remove the sweet potato and let stand for about 2 minutes.', 'Retire el camote y deje enfriar por casi 2 minutos.'),
  (163, 5, 'To serve, slit top of cooked potato and push ends toward each other.', 'Para servir, corte la porción superior del camote cocido y presione los extremos uno contra el otro.'),
  (163, 6, 'Add seasonings or other toppings, if desired. (Yogurt cannot be frozen.)', 'Añada condimentos y otros ingredientes, si desea. (El yogur no puede estar congelado).'),
  (163, 7, 'You can also scoop out the insides of cooked sweet potatoes, mash, and season to taste.', 'También puede sacar el interior del camote con una cuchara, hacerlo puré, y sazonar al gusto'),
  (163, 8, 'If cooking more than one sweet potato:', 'Si cocina más de un camote:'),
  (163, 9, 'Place the sweet potatoes at least one inch apart.', 'Coloque los camotes separándolos por al menos una pulgada.'),
  (163, 10, 'Cook two sweet potatoes for about 7 minutes; three sweet potatoes for about 10 minutes; four sweet potatoes for about 13 minutes. Cook until soft.', 'Cocine dos camotes por casi 7 minutos; tres camotes por casi 10 minutos; cuatro camotes por casi 13 minutos. Cocine hasta que estén suaves.'),
  (163, 11, 'Remove sweet potatoes from the microwave and let stand for about 2 minutes before serving.', 'Revuelva los camotes del microondas y deje enfriar por cerca de 2 minutos antes de servir.'),
  (164, 1, 'Bring about 1 inch of water to a boil in a pot.', 'Ponga casi 1 pulgada de agua a hervir en una olla.'),
  (164, 2, 'Place a steamer in the pot and place the sweet potatoes in the steamer, loosely arranged.', 'Coloque la canasta para cocinar a vapor en una olla y coloque los camotes en la canasta, ordenados ligeramente.'),
  (164, 3, 'Cover the pot loosely and steam for 15-20 minutes, or until tender.', 'Cubra la olla ligeramente y cocine a vapor por 15-20 minutos, o hasta que estén tiernos.'),
  (164, 4, 'Season with butter or margarine and salt or pepper to taste, or use other seasonings.', 'Sazone con mantequilla o margarina, y sal o pimienta al gusto, o use otros condimentos.'),
  (164, 5, 'You can also mash the cooked sweet potatoes and season to taste.', 'También puede hacer puré con los camotes cocidos y sazonar al gusto.'),
  (165, 1, 'Combine broth or water, soy sauce, vinegar, sugar, 1 large spoon of oil, and pepper for sauce. Set aside.', 'Combine caldo o agua, salsa de soya, vinagre, azúcar, 1 cuchara grande de aceite, y pimienta para la salsa. Ponga al costado.'),
  (165, 2, 'Cut peel from orange, taking only the colored part. Chop into small strips. Set aside.', 'Corte la cascára de una naranja, tomando solo la parte anaranjada. Corte en pequeñas tiras. Ponga al costado.'),
  (165, 3, 'Heat 1 large spoon of oil in a frying pan that has a cover.', 'Caliente una cuchara grande de aceite en una sartén que tenga una tapa.'),
  (165, 4, 'Add orange peel, garlic, ginger and sweet potatoes and cook for 2­3 minutes.', 'Añada la cascára de la naranja, ajo, jengibre y camotes, y cocine de 2-3 minutos.'),
  (165, 5, 'Add sauce.', 'Añada la salsa.'),
  (165, 6, 'Bring to a boil, then cook, covered over medium heat until potatoes are tender, 15-20 minutes. Stir often.', 'Ponga a hervir, luego cubra y cocine a fuego medio hasta que los camotes estén tiernos, 15-20 minutos. Revuelva con frecuencia.'),
  (165, 7, 'Add chicken and chopped green onions if desired.', 'Añada pollo y cebollitas picadas si desea.'),
  (166, 1, 'Preheat oven to 375 degrees.', 'Precaliente el horno a 375 grados.'),
  (166, 2, 'Rub chicken with salt and pepper.', 'Frote el pollo con sal y pimienta.'),
  (166, 3, 'Spray or oil baking dish and arrange chicken in one layer.', 'Unte o rocíe aceite en una charola para el horno y acomode el pollo en una capa.'),
  (166, 4, 'Scatter sweet potatoes, garlic and onions on chicken.', 'Esparza los camotes, ajo y cebollas sobre el pollo.'),
  (166, 5, 'Sprinkle with salt and pepper.', 'Rocíe con sal y pimienta.'),
  (166, 6, 'Mix sugar and orange juice, drizzle over chicken and potatoes.', 'Mezcle azúcar y jugo de naranja, y vierta ligeramente sobre el pollo y camotes.'),
  (166, 7, 'Bake uncovered 30 minutes, basting occasionally.', 'Hornee sin cubrir por 30 minutos, cubriéndolos con su propio jugo ocasionalmente'),
  (166, 8, 'Add peaches on top and dots of margarine (optional).', 'Añada los duraznos y trocitos de margarina por encima (opcional).'),
  (166, 9, 'Bake uncovered 30 additional minutes or more, basting occasionally, until potatoes are tender and chicken is cooked through.', 'Hornee sin cubrir por 30 minutos más, cubriéndolos con su propio jugo ocasionalmente, hasta que los camotes estén tiernos y el pollo se termine de cocinar.'),
  (167, 1, 'Place all vegetables in a pot.', 'Coloque los vegetales en una olla.'),
  (167, 2, 'Cover with water or broth.', 'Cubra con agua o caldo.'),
  (167, 3, 'Bring to a boil and continue cooking until vegetables are tender.', 'Ponga a hervir y continúe cocinando hasta que los vegetales estén tiernos.'),
  (167, 4, 'Mash vegetables until smooth using a large spoon or a potato masher.', 'Haga puré con los vegetales hasta que estén suaves usando una cuchara grande o un machacador de papas.'),
  (167, 5, 'Add salt and pepper to taste.', 'Añada sal y pimienta al gusto.'),
  (168, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (168, 2, 'Cut potatoes into narrow wedges.', 'Corte los camotes en trozos delgados.'),
  (168, 3, 'Coat a baking sheet with vegetable spray or vegetable oil.', 'Cubra una charola para hornear con aceite de rociador o aceite vegetal.'),
  (168, 4, 'Put the potatoes in a large bowl with garlic.', 'Ponga los camotes en un recipiente hondo y grande con ajo.'),
  (168, 5, 'Add the oil and melted margarine or butter. Stir.', 'Añada el aceite y la margarina o mantequilla derretida. Revuelva.'),
  (168, 6, 'Add pepper and salt.', 'Añada pimienta o sal.'),
  (168, 7, 'Place potatoes on baking sheet.', 'Coloque los camotes en una charola para el horno.'),
  (168, 8, 'Bake for 20 minutes.', 'Hornee por 20 minutos.'),
  (168, 9, 'Turn over the potatoes and bake another 20 minutes or until brown and tender.', 'Voltee los camotes y hornee por otros 20 minutos o hasta que estén cafecitos y tiernos.'),
  (169, 1, 'Preheat oven to 400 degrees.', 'Precaliente el horno a 400 grados.'),
  (169, 2, 'Mix potatoes, optional vegetables and garlic with the oil and melted butter or margarine, sprinkle with salt and pepper. Toss well.', 'Mezcle los camotes, los vegetales opcionales y ajo con el aceite y la mantequilla o margarina derretida, rocíe con sal y pimienta. Mezcle bien.'),
  (169, 3, 'Place the vegetables in a baking dish that has been coated with cooking spray or oil.', 'Coloque los vegetales en una charola para el horno que haya sido cubierta con un rociador para cocinar o aceite.'),
  (169, 4, 'Place in oven and bake for 30 minutes.', 'Coloque dentro del horno y hornee por 30 minutos.'),
  (170, 1, 'Steam or boil sweet potatoes, until tender; drain and let cool.', 'Cocine al vapor o hierva los camotes, hasta que estén tiernos, escurra y deje enfriar.'),
  (170, 2, 'Combine lime or lemon juice, oil, mustard, salt, pepper, and garlic in a bowl and stir.', 'Combine jugo de limón verde o amarillo, aceite, mostaza, sal, pimienta, y ajo en un recipiente hondo y revuelva.'),
  (170, 3, 'Add sweet potato, onions, and beans. Stir well to coat.', 'Añada el camote, cebollas, y frijoles. Revuelva bien para recubrir todo.'),
  (171, 1, 'Place oil in pan.', 'Coloque aceite en un sartén.'),
  (171, 2, 'Put onions in pan and cook until tender.', 'Ponga las cebollas en el sartén y cocine hasta que estén tiernas.'),
  (171, 3, 'Add sweet potatoes, other potatoes and cook for a few minutes.', 'Añada la papa y camote y cocine por unos minutos.'),
  (171, 4, 'Add salt or pepper or favorite seasoning.', 'Añada sal o pimienta o condimento favorito.'),
  (172, 1, 'Boil or steam potatoes until tender.', 'Hierva o cocine al vapor los camotes y papas hasta que estén tiernas.'),
  (172, 2, 'Drain potatoes and mash.', 'Cuele los camotes y papas, y haga puré.'),
  (172, 3, 'Add yogurt, parsley, salt and pepper and mix thoroughly.', 'Añada yogur, perejil, sal y pimienta y mezcle muy bien.'),
  (173, 1, 'Preheat oven to 350 degrees. Lightly grease a baking dish with vegetable oil or spray.', 'Precaliente el horno a 350 grados. Engrase ligeramente una charola para hornear con aceite vegetal o de roceador.'),
  (173, 2, 'Peel the sweet potatoes and cut into cubes.', 'Pele los camotes y corte en cubos'),
  (173, 3, 'Fill a pot with water. Add sweet potatoes to water and bring to a boil.', 'Llene una olla con agua. Agréguele los camotes y deje que el agua hierva.'),
  (173, 4, 'Cover loosely and simmer for 10 minutes, or until tender, but not falling apart.', 'Cubra la olla levemente y siga cocinando a fuego lento por 10 minutos, o hasta que los camotes estén tiernos pero no deshaciéndose.'),
  (173, 5, 'Drain the sweet potatoes and mix with the crushed pineapple, most of the brown sugar, and margarine or butter and put into the baking dish.', 'Cuele los camotes y mezcle con la piña picada, casi toda la azúcar morena, y margarina o mantequilla, y ponga dentro de una charola para hornear.'),
  (173, 6, 'Bake for 20 minutes.', 'Hornee por 20 minutos.'),
  (173, 7, 'Sprinkle remaining brown sugar on top and broil for 5 minutes (optional).', 'Rocíe el resto de azúcar morena por encima y hornee en la parte de abajo de su horno por otros 5 minutos (opcional).'),
  (174, 1, 'Boil or steam potatoes until tender, drain.', 'Hierva o cocine al vapor los camotes hasta que estén tiernos,y luego cuélelos.'),
  (174, 2, 'Mash potatoes.', 'Machaque los camotes.'),
  (174, 3, 'Stir in lemon juice, butter or margarine, and salt.', 'Remueva en jugo de limón, mantequilla o margarina, y sal.'),
  (174, 4, 'If topping with lemons, put mashed potatoes into a baking dish and top with lemon slices.', 'Si la cobertura es con limones, ponga los camotes hechos puré en una charola para hornear y cubra con las tajadas de limón.'),
  (174, 5, 'Cook at 350 degrees for 20 minutes or until heated through.', 'Cocine a 350 grados por 20 minutos o hasta que se haya calentado totalmente.'),
  (174, 6, 'Cook under broiler for about 3-5 minutes, until top starts to brown (optional).', 'Cocine bajo la parrilla del horno entre 3-5 minutos, hasta que la parte de arriba se ponga café.'),
  (175, 1, 'Place sweet potatoes in a Crock­Pot.', 'Coloque los camotes en una olla eléctrica.'),
  (175, 2, 'Mix remaining ingredients together in a bowl. Pour this mixture over the potatoes and stir gently.', 'Mezcla los ingredientes restantes juntos en un recipiente hondo. Eche la mezcla sobre los camotes y remueva suavemente.'),
  (175, 3, 'Cover and cook on low heat 4-5 hours or until the sweetpotatoes are very tender.', 'Cubra y cocine a baja temperatura durante 4-5 horas o hasta que los camotes estén bien tiernos.'),
  (175, 4, 'Mix the sweet potatoes well before serving.', 'Mezcle los camotes bien antes de servir.'),
  (176, 1, 'Mix oil, chili powder or cayenne pepper and hot sauce together.', 'Mezcle todo: aceite, chili en polvo o pimienta cayena y salsa picante'),
  (176, 2, 'Add sweet potatoes and toss until well coated.', 'Añada los camotes y revuelva hasta que estén bien cubiertos.'),
  (176, 3, 'Spread potatoes onto a baking pan coated lightly with cooking spray or vegetable oil.', 'Esparza los camotes sobre una charola para hornear cubierta ligeramente aceite vegetal un rociador de bote para cocinar.'),
  (176, 4, 'Bake at 400 degrees for 20 minutes, turn potatoes and bake another 20 minutes or until potatoes are tender and browned.', 'Hornee a 400 grados por 20 minutos, voltee los camotes y hornee por otros 20 minutos o hasta que los camotes estén tiernos y dorados.'),
  (177, 1, 'Boil potatoes in lightly salted water for 10 minutes, or until tender.', 'Hierva los camotes en agua ligeramente salada por 10 minutos, o hasta que estén tiernos.'),
  (177, 2, 'Drain and cool.', 'Escurra y deje enfriar.'),
  (177, 3, 'Combine the beans, sweet potatoes and salsa.', 'Combine los frijoles, camotes y salsa.'),
  (177, 4, 'Serve warm or cold.', 'Sirva caliente o frío.'),
  (178, 1, 'Boil or steam potatoes until potatoes can be pierced easily with a sharp knife.', 'Hierva o cocine al vapor los camotes hasta que se les puedan hacer huecos fácilmente con un cuchillo filoso.'),
  (178, 2, 'Drain the potatoes and cool.', 'Cuele los camotes y deje enfriar.'),
  (178, 3, 'Peel the potatoes and cut into medium-sized chunks.', 'Pele los camotes y corte en trozos de tamaño mediano.'),
  (178, 4, 'In a large bowl, combine the mayonnaise, mustard, salt, and pepper.', 'En un recipiente hondo y grande, combine la mayonesa, mostaza, sal y pimienta.'),
  (178, 5, 'Add the eggs, celery, and green onions.', 'Añada los huevos, apio, y cebollitas.'),
  (178, 6, 'Add the potatoes and mix gently.', 'Añada los camotes y mezcle con cuidado.'),
  (178, 7, 'Cover and refrigerate for 2-4 hours.', 'Cubra y refrigere por 2-4 horas.'),
  (179, 1, 'Thaw frozen corn or drain canned corn.', 'Descongele el maíz, o vacíe el agua si usa maíz de lata.'),
  (179, 2, 'Put butter, margarine, or oil in a frying pan.', 'Coloque la mantequilla, margarina o aceite vegetal en un sartén para freír.'),
  (179, 3, 'Add onions and corn and cook until onions are clear, but not brown.', 'Agregue las cebollas y maíz y guise hasta que las cebollas estén translucientes pero sin dejar que se doren.'),
  (179, 4, 'Add zucchini, salt, and pepper to taste.', 'Agregue las calabacitas y sal y pimienta al gusto.'),
  (179, 5, 'Add about ½ cup of cold water and cover pan.', 'Añada aproximadamente ½ taza de agua frí y tape el sartén.'),
  (179, 6, 'Cook on medium heat until vegetables are tender, just a few minutes.', 'Cocine a medio fuego por unos minutos hasta que las verduras se pongan tiernas.'),
  (179, 7, 'Drain any excess water, then add cheese, mix, and cover until the cheese melts.', 'Vacíe el agua que quede y después añada el queso, mezcle todo bien y cubra el sartén hasta que el queso se derrita.'),
  (180, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (180, 2, 'In a frying pan, brown hamburger, onion, green peppers, parsley, onion, and garlic salt.', 'En el sartén, ponga a dorar ligeramente la carne molida, cebollas, pimiento morrón, perejil y sal de ajo.'),
  (180, 3, 'In a baking dish, place layers of meat mixture and zucchini, then meat mixture and zucchini.', 'En un recipiente para hornear, coloque capas de la carne ya doradita y sazonada, con capas de calabacitas alternándolas una sobre la otra. O sea, una capa de carne y luego una capa de calabacitas hasta formar 4 capas.'),
  (180, 4, 'Top with tomato slices.', 'Luego, ponga una capa de jitomates.'),
  (180, 5, 'Mix breadcrumbs and Parmesan cheese together and put on top.', 'Mezcle el pan molido/rallado con el queso parmesano y vierta por sobre la capa de jitomates.'),
  (180, 6, 'Bake at 350 degrees for 40 minutes.', 'Hornee a 350 grados por 40 minutos.'),
  (180, 7, 'Bake an additional 5 minutes at 450 degrees or broil for 1-2 minutes if you want a crispier top.', 'Súbale la temperatura al horno a 450 grados y hornee por 5 minutos adicionales. O también si usted lo desea, puede colocar el recipiente en la parte de debajo de su horno y "asar" de 1 a 2 minutos adicionales para que la capa con el pan molido y queso quede mas doradita y crujiente.'),
  (181, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (181, 2, 'Lightly grease a casserole dish with butter, margarine, or oil.', 'Unte de manera ligera la parte interior del recipiente para hornear con mantequilla, margarina, o aceite.'),
  (181, 3, 'Cover the bottom of the casserole dish with half the sliced tomatoes.', 'Cubra el fondo del recipiente con la mitad de los jitomates rebanados.'),
  (181, 4, 'Add half the zucchini and onions.', 'Añada la mitad de las calabacitas y cebollas.'),
  (181, 5, 'Season with salt and pepper.', 'Sazone con sal y pimienta.'),
  (181, 6, 'Sprinkle with half the Parmesan cheese.', 'Espolvoree usando la mitad de queso parmesano.'),
  (181, 7, 'Repeat layer using remaining vegetables.', 'Repita agregando los jitomates, calabacitas y cebollas restantes de la misma manera.'),
  (181, 8, 'Top off the casserole with remaining Parmesan cheese.', 'Cubra todo con el resto del queso parmesano.'),
  (181, 9, 'Bake uncovered for 45 minutes.', 'Coloque el recipiente en el horno y hornee por 45 minutos.'),
  (182, 1, 'Preheat oven to 425 degrees. Lightly coat a baking sheet with oil.', 'Precaliente el horno a 425 grados. Unte un poco de aceite de manera ligera a una charola para hornear .'),
  (182, 2, 'Cut the zucchini in half lengthwise. With the tip of a spoon remove zucchini seeds and discard, leaving plenty of the zucchini in the shell. Cut a thin slice from the bottom of each zucchini piece to allow it to sit flat.', 'Corte las calabacitas por la mitad a lo largo de las mismas. Usando una cucharita, quíteles las semillas y parte de la "carnosidad" dejando una especie de canal a lo largo de las calabacitas. Corte un pedazo delgado en la parte de abajo de cada rebanada de la calabacita para permitir que las mismas puedan permanecer "planas" sobre el plato sin voltearse.'),
  (182, 3, 'Rub the zucchini shells lightly with oil.', 'Frote las calabacitas con el aceite vegetal.'),
  (182, 4, 'Mix together the breadcrumbs, bell pepper, cheese, and seasonings. And, meat, if you wish.', 'Mezcle juntos el pan molido, el pimiento morrón, el queso, y sus sazonadores/condimentos favoritos. Y si lo desea, añada carne.'),
  (182, 5, 'Pat the mixture into the zucchini shells. Top with more cheese, if desired.', 'Ponga la "mezcla" en los huecos de las calabacitas. Cúbralas con queso si lo desea.'),
  (182, 6, 'Bake, uncovered, for 15 minutes or until brown.', 'Colóquelas en la charola y hornee al descubierto por 15 minutos, o hasta que la parte de arriba este doradita.'),
  (183, 1, 'Cut the chicken breast pieces into strips, about the size of a finger.', 'Corte las pechugas de pollo en tiritas aproximadamente del tamaño de un dedo.'),
  (183, 2, 'Heat oil in a frying pan and cook chicken, stirring often, until brown on all sides, 3-5 minutes.', 'Caliente el aceite en el sartén y guise el pollo, agitando con frecuencia hasta que las tiritas estén doraditas por todos lados, de 3­-5 minutos.'),
  (183, 3, 'Add zucchini and cook until lightly browned, stirring occasionally, 5-7 minutes.', 'Agregue las calabacitas y cocine de 5-­7 minutos hasta que las mismas estén ligeramente doraditas, agitando ocasionalmente.'),
  (183, 4, 'Add the mushrooms and tomatoes and mix well. Cook another 3-5 minutes.', 'Añada los hongos y jitomate y mezcle bien todo. Cocine de 3­-5 minutos adicionales.'),
  (183, 5, 'Serve over noodles or rice, prepared according to the package.', 'Sirva sobre los tallarines o arroz, previamente preparados de acuerdo a las instrucciones del paquete.'),
  (184, 1, 'Preheat oven to 375 degrees.', 'Precaliente el horno a 350 grados.'),
  (184, 2, 'Toss zucchini with a large spoon of vegetable oil and a pinch of salt, pepper, or favorite seasonings.', 'Revuelva las calabacitas con una cucharada grande de aceite vegetal, sal, pimienta o su sazonador favorito.'),
  (184, 3, 'Spread the zucchini on a baking sheet.', 'Esparza las calabacitas en una charola para hornear.'),
  (184, 4, 'Bake for 10 minutes and turn the zucchini. Bake another 10 minutes until brown.', 'Ponga a hornear por 10 minutos. Déle vuelta a las calabacitas y hornee por otros 10 minutos hasta que estén doraditas.'),
  (185, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (185, 2, 'Heat oil in a frying pan. Add garlic, zucchini, bell peppers and chili powder and any optional ingredients.', 'Caliente el aceite en un sartén. Añada el ajo, calabacitas, pimiento morrón, y chile en polvo y cualquiera de los ingredientes opcionales.'),
  (185, 3, 'Fry the vegetables until tender, about 5-7 minutes.', 'Fría las verduras hasta que estas estén tiernas, de 5-­7 minutos.'),
  (185, 4, 'Lightly oil a baking dish.', 'Unte aceite a la charola para hornear de manera ligera.'),
  (185, 5, 'Put zucchini mixture on the tortillas and roll them up.', 'Ponga la "mezcla" de las verduras y otros ingredientes en cada una de las tortillas y envuélvalas en forma de burritos.'),
  (185, 6, 'Place the tortillas in a baking dish and bake for 10 minutes.', 'Coloque las tortillas (ya en forma de burritos) en la charola y ponga a hornear por 10 minutos.'),
  (185, 7, 'Pour enchilada sauce, any extra zucchini mixture, and cheese over the tortillas and bake for 10 more minutes.', 'Vierta la salsa para enchiladas, así como sobras de la mezcla de ingredientes y el queso por encima de las tortillas y deje hornear por otros 10 minutos.'),
  (186, 1, 'Lightly coat a casserole dish with vegetable oil or spray.', 'Cubra de manera ligera la parte interior de una cacerola u otro recipiente apropiado para usar en el horno, con aceite vegetal. Ya sea esparciéndolo o usando un rociador de aceite para cocinar.'),
  (186, 2, 'Combine zucchini, onion, bread cubes or stuffing mix, cheese, garlic, and seasonings to taste and mix well.', 'Combine las calabacitas, cebolla, cubitos de pan o mezcla de relleno, queso, ajo y condimentos al gusto y mezcle bien todo.'),
  (186, 3, 'Add a bit of vegetable oil, just enough to moisten the mixture. Mix well.', 'Añada un poco de aceite vegetal, solo para humedecer la mezcla. Revuelva bien.'),
  (186, 4, 'Cover and bake at 350 degrees for 55 minutes.', 'Tape el recipiente y póngalo en el horno por 55 minutos a 350 grados.'),
  (186, 5, 'Let sit 5 minutes before serving.', 'Saque del horno y déjelo "reposar" por 5 minutos antes de servirlo.'),
  (187, 1, 'Cut zucchini lengthwise. Then cut crosswise into pieces that are pencil-wide.', 'Corte las calabacitas de extremo a extremo. Después córtelas de manera diagonal en pedazos de un ¼ de pulgada de ancho aproximadamente.'),
  (187, 2, 'Cook noodles according to directions on the package.', 'Cueza los tallarines de acuerdo a las instrucciones del paquete.'),
  (187, 3, 'While noodles are cooking, heat a frying pan. Add vegetable oil, garlic, and zucchini and cook until tender, about 10 minutes. Stir occasionally.', 'Mientras cocina los tallarines, ponga un sartén a calentar usando el aceite vegetal. Agregue el ajo y las calabacitas y guise por aproximadamente 10 minutos, agitando ocasionalmente hasta que se pongan blandas.'),
  (187, 4, 'Add tomatoes, salt, and pepper to zucchini and stir.', 'Añada los jitomates, sal y pimienta y agite la mezcla de nuevo.'),
  (187, 5, 'Bring to a boil, reduce heat, and simmer for 5 minutes, stirring often.', 'Una vez que este hirviendo, reduzca el fuego y cocine a fuego lento por 5 minutos, agitando los ingredientes con frecuencia.'),
  (187, 6, 'Once the noodles are cooked, drain, and stir into the zucchini­tomato mixture.', 'Una vez que los tallarines estén cocidos, cuélelos y viértalos al sartén y revuélvalos con las calabacitas y jitomate.'),
  (187, 7, 'Top with cheese.', 'Cubra todo con queso.'),
  (188, 1, 'Melt the margarine or butter in a large fry pan. Cook the onion and garlic on medium for 3-7 minutes, until softened but not browned.', 'Derrita la margarina o mantequilla en un sartén. Guise la cebolla y ajo a medio fuego de 3-­7 minutos hasta que estén blandas, pero sin dejar que se doren.'),
  (188, 2, 'Add the tomatoes with their juice, bring to a boil, lower heat, and simmer for 10­-15 minutes.', 'Añada el jitomate con todo y su jugo, déjelo hervir, reduzca el fuego y cocine a fuego lento de 10­-15 minutos.'),
  (188, 3, 'Add the zucchini to the sauce, cover tightly and simmer for 10­-15 minutes, or until tender.', 'Vierta las calabacitas al sartén, cúbralo con una tapadera firme y cocine a fuego lento de 10­-15 minutos, o hasta que las calabacitas se pongan blandas.'),
  (188, 4, 'Stir in the seasoning to taste.', 'Mientras agita todo, agréguele sal y pimienta al gusto.'),
  (189, 1, 'In a dish, arrange cucumber, zucchini and onions in alternate layers.', 'En un recipiente adecuado, coloque los pepinos, las calabacitas y la cebolla en capas alternas.'),
  (189, 2, 'Mix vinegar, sugar, and ½ cup hot water, until the sugar is dissolved.', 'Mezcle el vinagre, azúcar y ½ taza de agua caliente, hasta que el azúcar se disuelva.'),
  (189, 3, 'Add salt, pepper, and crushed red pepper to vinegar mixture.', 'Añada sal, pimienta y las hojuelas de chile rojo a la mezcla de vinagre.'),
  (189, 4, 'Add two ice cubes to the mix to chill it.', 'Ponga 2 cubos de hielo en la mezcla para enfriarla.'),
  (189, 5, 'Pour dressing over vegetables and let sit at room temperature for 1 hour before serving.', 'Vierta la mezcla sobre las verduras y déjelas marinar a la temperatura ambiental por 1 hora antes de servirlas.'),
  (189, 6, 'Mix vegetables and dressing a couple of times while sitting at room temperature.', 'Revuelva todo un par de veces mientras se esta marinando la mezcla.'),
  (190, 1, 'Put water to fill a pot halfway and bring to a boil.', 'Ponga agua en una olla hasta la mitad y deje que hierva.'),
  (190, 2, 'Add the zucchini and boil until they are soft, about 3-4 minutes.', 'Añada las calabacitas y permita que al agua vuelva a hervir y cuézalas hasta que las calabacitas estén tiernas, en aproximadamente 3­-4 minutos.'),
  (190, 3, 'Drain the zucchini and toss with some vegetable oil and seasonings.', 'Cuélelas y agrégueles el aceite vegetal y los condimentos, mezclando todo para que queden bien sazonadas.'),
  (191, 1, 'In large frying pan, cook zucchini in oil over medium heat for 4 minutes.', 'En un sartén grande, guise las calabacitas en aceite a fuego medio por 4 minutos.'),
  (191, 2, 'Sprinkle with lemon zest (optional), salt, and pepper.', 'Espolvoree la corteza de limón (opcional), la sal y pimienta.'),
  (191, 3, 'Fry 4-5 minutes longer or until zucchini is crisp.', 'Fría de 4­-5 minutos adicionales o hasta que las calabacitas estén crujientes.'),
  (191, 4, 'Remove from heat, and sprinkle with cheese.', 'Quítelas de la estufa y empolvoréelas con el queso parmesano.'),
  (192, 1, 'Heat oil in a frying pan and cook onions for 3-4 minutes.', 'Ponga el aceite a calentar en un sartén y guise las cebollas de 3-­4 minutos.'),
  (192, 2, 'Combine onions and all the other ingredients in the Crock­Pot and mix well.', 'Vierta y combine todos los ingredientes en la olla "Crock­Pot" y revuélvalos bien.'),
  (192, 3, 'Cover and cook on low for 4 hours.', 'Póngale la tapadera a la olla y guise a baja temperatura por 4 horas.'),
  (192, 4, 'Can serve over noodles or rice, prepared according to package.', 'Se puede servir sobre tallarines o arroz, preparados de acuerdo a las instrucciones de sus respectivos paquetes.'),
  (193, 1, 'Place zucchini in a steamer basket.', 'Coloque las calabacitas en un vaporizador plegable o "canastita" para cocinar al vapor.'),
  (193, 2, 'Pour just enough water in a pot so that the water will not touch the bottom of the steamer basket. Bring water to boil. Place steamer basket in pot and cover.', 'Ponga suficiente agua en una olla pero evite que el agua vaya a tocar la parte de abajo de la canastita o vaporizador plegable. Deje que el agua hierva primero para después situar la canastita o vaporizador plegable dentro de la olla. Cubra la olla.'),
  (193, 3, 'Cook for 5-7 minutes or until zucchini are bright green and tender.', 'Cueza de 5-­7 minutos, o hasta que las calabacitas se pongan de un color verde brillante y blanditas.'),
  (193, 4, 'Drain and season with salt, pepper, or other favorite seasonings.', 'Cuélelas y sazone con sal, pimienta, o algún otro sazonador de su agrado.'),
  (194, 1, 'Cut zucchini into chunks.', 'Corte las calabacitas en pedazos cortos y gruesos.'),
  (194, 2, 'Bring a pot of water, with a pinch of salt, to a boil. Add zucchini pieces and cook for 3 minutes. Drain and immediately put pieces in a bowl of cold water and ice cubes to stop the cooking. Let cool and drain.', 'Ponga una olla con agua a hervir y agréguele una pizca de sal. Añada las calabacitas y cocine por 3 minutos.  Vacíe el agua e inmediatamente ponga las calabacitas en un recipiente hondo con agua fría y hielos para evitar que se sigan cocinando. Déjelas que se enfríen para después colarlas.'),
  (194, 3, 'Cut tomatoes in half. Remove seeds. Cut into chunks.', 'Corte los jitomates a la mitad. Quítele las semillas. Córtelos en pedazos chicos y gruesos.'),
  (194, 4, 'Combine zucchini and tomatoes in a bowl. Add Italian salad dressing and mix vegetables to coat them.', 'Combine las calabacitas y el jitomate en un recipiente hondo. Agregue el aderezo estilo italiano, y revuelva todo bien para que las verduras se cubran del aderezo.'),
  (194, 5, 'Add garlic powder, salt, pepper, or favorite seasonings, to taste (optional), mixing well.', 'Añada el polvo de ajo (opcional), sal, pimienta, o su sazonador/condimento favorito al gusto. Mezcle todo.'),
  (195, 1, 'Put zucchini and onion into a microwave-safe bowl, with 2 large spoons of water.', 'Ponga las calabacitas y cebolla en un recipiente apropiado para el horno de microondas con 2 cucharadas grandes de agua.'),
  (195, 2, 'Microwave on high for 6-8 minutes, stirring every 2 minutes.', 'Coloque el recipiente en el horno de microondas a temperatura alta de 6-8 minutos, mezclando y revolviendo cada 2 minutos.'),
  (195, 3, 'Season with garlic powder, salt, pepper, or other optional seasonings, to taste. Blend in melted margarine or butter, if you wish.', 'Sazone con el ajo en polvo, sal, pimienta, u otros sazonadores opcionales al gusto. Vierta y mezcle la margarina o mantequilla derretida, si así lo desea.'),
  (196, 1, 'Preheat oven to 350 degrees. Lightly grease a casserole dish with vegetable oil or spray.', 'Precaliente el horno a 350 grados. Cubra de manera ligera la parte interior de una cacerola u otro recipiente apropiado para usar en el horno, con aceite vegetal, ya sea esparciéndolo o usando un rociador de aceite para cocinar.'),
  (196, 2, 'Mix the eggs and the Bisquick together in a large bowl.', 'Bata los huevos y la harina "Bisquick" juntos en un recipiente hondo.'),
  (196, 3, 'Add the zucchini, onions, and cheese. Mix.', 'Agregue las calabacitas, cebollas y el queso. Mezcle bien todo.'),
  (196, 4, 'Add salt and pepper to taste.', 'Añada sal y pimienta, al gusto.'),
  (196, 5, 'Put into a casserole dish and bake 45 minutes.', 'Vacié todo en la cacerola u otro recipiente que haya escogido y coloque en el horno ya caliente por 45 minutos.'),
  (197, 1, 'In a pot, heat vegetable oil.', 'Ponga el aceite a calentar en una olla.'),
  (197, 2, 'Add chopped onions and garlic and cook until the onions are soft.', 'Agregue los trozos de cebolla y ajo y guise hasta que las cebollas se pongan tiernas.'),
  (197, 3, 'Add the zucchini and mix together.', 'Agrégueles las calabacitas y mézclelas.'),
  (197, 4, 'Add the chicken broth and bring to a boil. Simmer until zucchini is soft, 15-20 minutes.', 'Añada el consomé y déjelo que hierva. Reduzca la intensidad del fuego y cocine hasta que las calabacitas estén tiernas, de 15-­20 minutos.'),
  (197, 5, 'Mix with a potato masher or blender.', 'Mezcle todo usando un triturador de papas o licuadora.'),
  (197, 6, 'Season with salt or pepper to taste.', 'Sazone con sal o pimienta, al gusto.'),
  (197, 7, 'This soup can be served hot or cold.', 'Esta sopa se puede servir caliente o fría.'),
  (198, 1, 'Preheat oven to 425 degrees.', 'Precaliente el horno a 425 grados.'),
  (198, 2, 'Coat a wire rack lightly with vegetable oil or cooking spray.', 'Unte y cubra una parrilla/anaquel de metal con aceite vegetal o de rociador para cocinar.'),
  (198, 3, 'Combine breadcrumbs, Parmesan cheese, seasonings and mix well.', 'Combine el pan molido, queso parmesano, condimentos y mézclelos bien.'),
  (198, 4, 'Place egg in a shallow bowl.', 'Ponga el huevo batido en un recipiente poco profundo.'),
  (198, 5, 'Dip zucchini slices in the egg, and then in the breadcrumb mixture. Cover the zucchini on both sides with the breadcrumb mixture.', 'Introduzca las calabacitas rebanadas en el huevo, y luego póngalas en el recipiente con la mezcla de pan molido. Asegurese de revestir las calabacitas completamente con la mezcla de pan molido.'),
  (198, 6, 'Place zucchini slices on the wire rack and put the wire rack on a baking sheet.', 'Coloque las calabacitas en la parrilla-anaquel y ponga la parrilla sobre una charola para hornear.'),
  (198, 7, 'Bake for 25-30 minutes, or until brown and crispy.', 'Hornee de 25­-30 minutos, o hasta que las calabacitas estén doraditas y crujientes.'),
  (199, 1, 'Heat oil in a frying pan and brown meat or chicken over medium heat, about 3-5 minutes.', 'Ponga el aceite a calentar en un sartén y dore la carne molida o el pollo a fuego medio de 3­-5 minutos.'),
  (199, 2, 'Add onions and garlic and cook about 2 minutes.', 'Agregue las cebollas y ajo y guise por 2 minutos aproximadamente.'),
  (199, 3, 'Add chicken broth and soy sauce and mix well.', 'Vierta el consomé, la salsa de soya y revuelva bien.'),
  (199, 4, 'Add zucchini and bean sprouts and cook 2 minutes.', 'Añada las calabacitas y brotes de soya y cocine por 2 minutos.'),
  (199, 5, 'Add tomato and cook 1 minute.', 'Agréguele el jitomate y guise por 1 minuto más.'),
  (199, 6, 'Serve with rice, prepared according to package.', 'Sirva con arroz, preparado anteriormente de acuerdo a las instrucciones del paquete.'),
  (200, 1, 'Preheat oven to 350 degrees.', 'Precaliente el horno a 350 grados.'),
  (200, 2, 'In a pan, heat oil over medium heat. Add zucchini and onion and cook until tender, about 8-10 minutes. Add meat, corn and beans and mix well.', 'En un sartén, calentar el aceite a fuego medio. Agregar las calabacitas y cebolla y cocinar hasta que estén tiernitas, de 8-10 minutos. Añadir la carne, pollo o pavo, maíz, y frijoles y mezcle bien todo.'),
  (200, 3, 'In a 9" x 13" baking dish, spread ½ cup of enchilada sauce.', 'En un recipiente para hornear de 9" X 13", vierta y esparza ½ taza de la salsa para enchiladas.'),
  (200, 4, 'Then, place a layer of tortillas, overlapping, if needed. Add the vegetables/meat mix. Add half of the cheese.', 'A continuación, coloque una capa de tortillas, sobrepuestas una sobre la otra levemente (si es necesario). Añadir la mezcla de verduras y carne. Añadir también la mitad del queso.'),
  (200, 5, 'Spread about 1 ½ cup of enchilada sauce on top of the cheese.', 'Vierta y esparza 1 ½ taza de la salsa para enchiladas sobre el queso.'),
  (200, 6, 'Add another layer of tortillas. Spread the remaining enchilada sauce evenly on top of the tortillas.', 'Coloque otra capa de tortillas. Vierta y esparza el resto de la salsa para enchiladas de manera uniforme por encima de las tortillas.'),
  (200, 7, 'Bake for 20-25 minutes. Remove from oven and top with remaining cheese. Bake for another 5-10 minutes or until cheese is melted and golden brown.', 'Hornear de 20-25 minutos. Sacar el recipiente del horno y verter y esparcir el resto del queso. Ponga el recipiente de nuevo en el horno y cocine por otros 5-10 minutos, o hasta que el queso se derrita y este doradito.'),
  (200, 8, 'Top with sour cream (optional).', 'Agregar crema agria (opcional).'),
  (205, 1, 'Cook rice according to instructions on the package.', 'Cocine el arroz de acuerdo a las instrucciones del paquete.'),
  (205, 2, 'Cook the broccoli pieces (steam, boil, or microwave).', 'Cocine los pedazos de brócoli (al vapor, hirviéndolos o en un horno de microondas).'),
  (205, 3, 'Mix together broccoli, corn, rice, and meat.', 'Mezcle el brócoli, elote, arroz y carne.'),
  (205, 4, 'If desired, warm mixture on stove top or in 350 degree oven for 5 minutes.', 'Si lo desea, caliente "la mezcla" por 5 minutos, ya sea en la estufa o en el horno a una temperatura de 350° grados.'),
  (205, 5, 'Top with grated cheese and, if desired, place under broiler until cheese melts. (optional)', 'Cubra todo con el queso rayado, y si lo desea, póngalo en el "broiler" (la parrilla en cajón movible en la parte inferior de la estufa) hasta que el queso se derrita.'),
  (206, 1, 'Boil noodles according to the directions on the package and drain.  Save a cup of the boiling water.', 'Hierva los fideos de acuerdo a las instrucciones del paquete y cuélelos. Guarde y ponga a un lado una taza del agua hervida.'),
  (206, 2, 'Cook the broccoli pieces (steam, boil or microwave).  The broccoli should be a bright green and still firm.  Test with a fork.', 'Cocine los pedazos de brócoli (al vapor, hervidos o en un horno de microondas). El brócoli deberá permanecer firme y de color verde brillante. Pruebe con un tenedor.'),
  (206, 3, 'Heat the oil in a pan over medium heat, add garlic (optional) and stir until garlic starts to soften.', 'Caliente el aceite en un sartén a fuego medio, agregue el ajo (opcional) y agite levemente hasta que el ajo se empiece a ablandar.'),
  (206, 4, 'Add the broccoli to the pan and stir together. Add a pinch of salt, pepper or red pepper flakes (optional).', 'Vierta el brócoli en el sartén y revuelva todo. Añada una pizca de sal, pimienta o las hojuelas de chile rojo (opcional).'),
  (206, 5, 'Add any other cooked vegetables and cooked meat/chicken. Add noodles, and some of the boiling water for desired consistency.', 'Agregue cualquier otra verdura y carne cocida o pollo cocido. Añada los fideos, y un poco del agua hervida hasta alcanzar la consistencia deseada.'),
  (206, 6, 'Serve this way, or with shredded cheese as a topping.', 'Sirva de de esta manera, o con queso rayado esparcido por encima'),
  (207, 1, 'In a bowl, combine meat or chicken with 1 large spoon of oil, salt, pepper, soy sauce (optional) and mix well.', 'En un recipiente hondo, combine la carne o pollo junto con 1 cucharada grande de aceite, sal, pimienta, salsa de soya (opcional) y revuelva bien todo.'),
  (207, 2, 'Heat 1 large spoon oil in a pan until hot.', 'Ponga a calentar una cucharada grande de aceite en un sartén, hasta que este caliente.'),
  (207, 3, 'Add meat or chicken and stir constantly until browned, about 2-3 minutes. Put meat/chicken on a plate.', 'Agréguele la carne o pollo y agite/revuelva constantemente hasta que esta se dore, de 2-3 minutos. Ponga la carne o pollo en un plato.'),
  (207, 4, 'Add broccoli and any other vegetables to the pan.', 'Añada el brócoli y cualquier otra verdura al sartén.'),
  (207, 5, 'Add water or broth.  Cover and cook until vegetables are tender, 3-6 minutes, depending on vegetables.', 'Añada agua o consomé. Cubra y cocine hasta que las verduras estén tiernas, de 3-6 minutos, dependiendo de las verduras.'),
  (207, 6, 'Add meat to the pan and stir for another 1-2 minutes.', 'Agregue la carne o pollo al sartén, mezclando y revolviendo todo por 1-2 minutos.'),
  (207, 7, 'Serve over rice or noodles (optional).', 'Sirva sobre arroz o fideos (opcional).'),
  (208, 1, 'Preheat oven to 375 degrees. Lightly grease a 9-inch baking dish.', 'Precalentar el horno a 375 grados. Levemente engrase un recipiente para hornear de 9 pulgadas.'),
  (208, 2, 'Heat oil in a large frying pan over medium-high heat. Add onions and zucchini and cook until tender, stirring occasionally.  Drain.', 'Caliente el aceite en un sartén grande a fuego medio-alto. Agregue las cebollas y calabacitas y cocine hasta que estén tiernas, revolviendo ocasionalmente. Cuele.'),
  (208, 3, 'In a large bowl, combine eggs, cheese, salt, pepper, or other seasonings.  Add zucchini/onion mix and blend well.  Add meat.', 'En un recipiente grande y hondo, combine los huevos, queso, sal, pimienta, o cualquier otro condimento/sazón.  Agregue la mezcla de calabacitas y cebolla y revuelva todo. Añada la carne.'),
  (208, 4, 'Scoop into prepared pie pan.', 'Usando una cuchara, vierta todo dentro del molde para pay/tarta ya preparado.'),
  (208, 5, 'Bake until eggs have set, about 30 minutes. Let cool for 10 minutes before serving.', 'Cocine en el horno hasta que los huevos se asienten, alrededor de 30 minutos. Saque del horno y deje a un lado por 10 minutos antes de servirlo.'),
  (209, 1, 'Cut broccoli florets and stems into small pieces (see cutting tip).', 'Corte los tallos y floretes de brócoli en pedazos pequeños (ver consejos de como cortar).'),
  (209, 2, 'Heat butter, a cup of the broth, and flour in a large pot over medium-high heat.  Stir briefly to mix.  Add broccoli, potatoes, onion, salt, and pepper.  Stir frequently for about 12 minutes.', 'Caliente la mantequilla, una taza del consomé, y harina en una olla grande a fuego medio-alto. Mezcle todo de manera breve. Agregue el brócoli, papas, cebolla, sal, y pimienta. Revuelva con frecuencia por 12 minutos aproximadamente.'),
  (209, 3, 'Add 2 cups broth.  Bring to a boil and reduce to simmer.  Cover and cook until all vegetables are soft, at least 20 minutes, stirring once or twice.', 'Añada 2 tazas de consomé. Dejar que hierva y reduzca la intensidad a fuego lento. Cubra y cocine por 20 minutos, hasta que las verduras estén suaves y tiernas, revolviendo todo una o dos veces.'),
  (209, 4, 'Stir in spinach and cook until wilted, 1-2 minutes.', 'Añada la espinaca sin dejar de revolver, y cocine hasta que esta se ablande por completo, de 1-2 minutos.'),
  (209, 5, 'Transfer mixture to blender or food processor, add cheese, and blend until smooth.  You can add more broth or water while blending to get the soup to the consistency that you want.', 'Transfiera "la mezcla" a una licuadora o procesador de alimentos, agregue el queso, y licue bien todo hasta quedar suave. Si usted desea, puede añadir más consomé, o agua mientras licua todo para obtener la consistencia y textura deseada.'),
  (210, 1, 'In a microwaveable dish, mix soy sauce, lemon juice, and cornstarch.  Add steak strips and stir to coat all pieces.  Cover and refrigerate for 30 minutes.', 'En un recipiente apto para el horno de microondas, mezcle la salsa de soya, el jugo de limón, y la maicena. Añada las tiritas de carne y revuelva bien hasta que las tiritas estén bien revestidas por la mezcla. Cubra y refrigere por 30 minutos.'),
  (210, 2, 'Drain beef and save the liquid.', 'Cuele la carne y guarde el líquido.'),
  (210, 3, 'Mix beef with broccoli, onion, and garlic in the microwaveable dish.  Cover and microwave on high 6-8 minutes, stirring after 4 minutes, until beef is no longer pink.', 'Mezcle la carne con el brócoli, cebolla, y ajo en el recipiente para el microondas. Cubra y cocine en el horno de microondas a temperatura alta de 6-8 minutos, revolviendo todo después de 4 minutos del tiempo total, hasta que la carne no tenga el color rosita.'),
  (210, 4, 'Stir in bell pepper and the saved liquid.  Cover and microwave 2-3 minutes on high, or until liquid is slightly thickened.', 'Vierta el pimiento morrón y el líquido que se había guardado. Cubra y cocine en el microondas a temperatura alta de 2-3 minutos, o hasta que el liquido este levemente espeso.'),
  (210, 5, 'Serve with rice or noodles, cooked according to package directions.', 'Sirva con arroz o fideos, cocinados de acuerdo a las indicaciones del paquete.'),
  (211, 1, 'Preheat oven to 350 degrees.  Lightly oil a baking dish.', 'Precaliente el horno a 350 grados. Ligeramente engrase con aceite una charola para hornear.'),
  (211, 2, 'Heat oil in a frying pan, and add broccoli, bell pepper, garlic, and chili powder.', 'Caliente el aceite en un sartén, y agréguele el brócoli, pimiento morrón, ajo, y chile en polvo.'),
  (211, 3, 'Fry the vegetables until tender, about 5-8 minutes.', 'Fría las verduras hasta que estén tiernas, alrededor de 5-8 minutos.'),
  (211, 4, 'Add cooked meat or beans (optional).', 'Añada la carne cocida o frijoles (opcional).'),
  (211, 5, 'Put broccoli mixture on the tortillas and roll them up.', 'Coloque la mezcla de brócoli sobre cada tortilla y enróllelas.'),
  (211, 6, 'Place the tortillas in the baking dish and bake for 15 minutes.', 'Coloque las tortillas en la charola y ponga en el horno por 15 minutos.'),
  (211, 7, 'Pour enchilada sauce, any extra broccoli mixture, and cheese over tortillas and bake for 10 more minutes.', 'Vierta la salsa para enchiladas, así como lo que le haya sobrado de la mezcla de brócoli, y queso sobre las tortillas y cocine por 10 minutos más.'),
  (212, 1, 'You can use any size tortilla to make this pizza.  You can vary the amount of sauce, toppings, and cheese.', 'Usted puede usar cualquier tamaño de tortillas para preparar esta pizza. Así mismo, usted puede variar las cantidades de salsa, ingredientes ("toppings"), y queso.'),
  (212, 2, 'Heat oven to 425 degrees.  Put tortilla on a baking sheet.', 'Caliente el horno a 425 grados. Ponga la tortilla sobre una charola para hornear.'),
  (212, 3, 'Spread sauce evenly across the tortilla, leaving ½ inch around edges.', 'Esparza la salsa de manera uniforme por encima de la tortilla, dejando un espacio libre de salsa de ½ pulgada alrededor de toda la orilla.'),
  (212, 4, 'Spread toppings on sauce.  Sprinkle with cheese.', 'Esparza los ingredientes ("toppings") por encima de la salsa. Espolvoree el queso por encima de todo.'),
  (212, 5, 'Bake in oven for 10-15 minutes, until cheese is bubbling and edges of the tortilla are lightly browned.', 'Ponga la charola en el horno y cocine de 10-15 minutos, hasta que el queso este derretido y "burbujeando", y la orilla de la tortilla este ligeramente dorada.'),
  (213, 1, 'In large pot, heat oil over medium heat and add beef and onions. Cook until meat is browned. Drain excess liquid.', 'En una olla grande, caliente el aceite a fuego medio y añada la carne y cebolla. Cocine hasta que la carne este doradita. Vacíe el líquido extra.'),
  (213, 2, 'Add remaining ingredients to pot and stir.  Make sure that the bouillon pieces are dissolved.', '•Añada el resto de los ingredientes a la olla y revuelva. Asegurase que los pedacitos de consomé se disuelvan por completo.'),
  (213, 3, 'Cover and cook over low-med heat for 30-40 minutes, stirring occasionally. If the soup is too watery, remove lid and simmer to reduce liquid to desired thickness.', 'Cubra y cocine a fuego bajo-medio de 30-40 minutos, revolviendo ocasionalmente. Si la sopa parece estar muy aguada, destape la olla y deje hervir a fuego lento para reducir a líquido hasta alcanzar la textura deseada.'),
  (214, 1, 'Lightly coat 8x8-inch microwavable glass baking dish with oil or cooking spray.', 'Usando aceite vegetal o aceite de cocina en aerosol, ligeramente rocié o unte el aceite a un recipiente de vidrio de 8x8 pulgadas y apropiado para horno de microondas.'),
  (214, 2, 'Place half of the cabbage in the baking dish.  Sprinkle half of the apple slices over the cabbage.  Place the pork chops in the dish.  Place the remaining cabbage in the dish.   Top with the remaining apple slices.', 'Ponga la mitad del repollo en el recipiente para hornear. Esparza la mitad de las rebanadas de manzana por encima del repollo. Coloque las chuletas en el recipiente. A continuación, ponga el resto del repollo, y cubra todo con el resto de las rebanadas de manzana.'),
  (214, 3, 'Pour broth over meat and vegetables.  Cover with waxed paper and microwave on high for 20-30 minutes.  Turn casserole dish every 7 or 8 minutes.', 'Vierta el consomé por encima de las verduras y carne. Cubra con papel encerado y cocine en el horno de microondas a temperatura alta por 20-30 minutos. Asegurase de voltear/girar el recipiente cada 7 o 8 minutos.'),
  (214, 4, 'Remove dish from microwave and let sit, covered, for 5 minutes.', 'Retire el recipiente del horno de microondas y póngalo a un lado, y déjelo cubierto por 5 minutos.'),
  (214, 5, 'Drizzle each serving with a few drops of honey (optional).', 'Sirva cada porción con unas gotitas de miel (opcional)'),
  (215, 1, 'Preheat oven to 350 degrees.', 'Precalentar el horno a 350 grados.'),
  (215, 2, 'Combine oil, onions, and garlic in a frying pan and cook on medium until tender, 3-5 minutes.  Add meat and brown.  Drain and transfer to a large bowl.', 'Combine aceite, cebollas, y ajo en un sartén y cocine a fuego medio hasta que se ablanden, de 3-5 minutos. Añada la carne y cocine hasta dorarse. Cuele y ponga en un tazón grande.'),
  (215, 3, 'Add vegetables, cooked rice, egg, and 2-3 large spoons of tomato soup. Add pinches of salt and pepper or favorite seasonings.  Stir thoroughly.', 'Añada verdura, arroz cocido, huevo, y 2-3 cucharadas grandes de sopa de tomate. Añada pizcas de sal y pimienta, o su sazón favorito. Revuelva bien.'),
  (215, 4, 'Bring a large pot of lightly salted water to a boil.', 'En una olla grande ponga agua con un poco de sal y deje que hierva.'),
  (215, 5, 'Cut out the entire stem of the cabbage. Carefully peel 8 leaves from the cabbage head.', 'Corte el tallo del repollo en su totalidad. Con cuidado pele 8 hojas del repollo.'),
  (215, 6, 'Add leaves to boiling water and cook for 2-3 minutes, until tender.  Cook just 3-4 leaves at a time, to avoid overcooking.  Drain leaves and pat dry.  Cut and discard the white center stem from each leaf.', 'Ponga las hojas en agua hirviendo y cocine 2-3 minutos, hasta que estén tiernas. Cocine solo 3-4 hojas a la vez para evitar que se cocinen demasiado . Cuele las hojas y séquelas. Corte y tire el tallo blanco de cada hoja.'),
  (215, 7, 'Divide meat mixture into 8 portions.  Place each leaf with stem end toward you, and place a portion of the mixture so that you can roll the leaf away from you, tucking in the sides to make a small stuffed roll.  Use a toothpick to keep each roll together.', 'Divida la mezcla de la carne en 8 porciones. Coloque cada hoja con la parte del "tallo" apuntado hacia usted, y vierta una porción de la mezcla de manera que usted pueda "enrollar" la hoja en dirección opuesta alejándose de usted, metiendo y doblando los extremos para formar un rollo relleno. Use un palillo para evitar que el rollo se desenvuelva.'),
  (215, 8, 'Place rolls in a casserole dish.  Spread remainder of tomato soup on top.', 'Coloque los "rollos" en un recipiente de vidrio para el horno. Vierta el resto de la sopa de tomate por encima.'),
  (215, 9, 'Cover with aluminum foil and bake for 45 minutes.', 'Cubra con papel de aluminio y hornee por 45 minutos.'),
  (216, 1, 'Combine beans and corn in a large pot.  Heat on low for 3-4 minutes.', 'Combinar los frijoles y elote en una olla grande. Cocine a fuego lento de 3-4 minutos.'),
  (216, 2, 'In a different pot, cook the cauliflower pieces (steam, boil, or microwave).', 'En otra olla, cocine los pedazos de coliflor (ya sea al vapor, hervidos o en el horno de microondas).'),
  (216, 3, 'Mix cauliflower, beans, corn, cooked meat, and seasonings.', 'Mezcle la coliflor, frijoles, elote, carne cocida, y sazones.'),
  (216, 4, 'Top with grated cheese, chopped avocado, or sour cream (optional).', 'Cubra con el queso rayado, aguacate picado, o crema agria (opcional)'),
  (217, 1, 'Preheat oven to 450 degrees.', 'Precalentar el horno a 450 grados.'),
  (217, 2, 'In large pan, heat 1 large spoon of oil and cook the onions and other vegetables until they start to get tender.  Remove from pan.', 'En un sartén grande, caliente una cucharada de aceite y cocine las cebollas y otras verduras hasta que se empiecen a poner blandas. Quitar del sartén y hacer a un lado.'),
  (217, 3, 'Add ground meat to the pan and cook until brown.  Drain liquid and season mixture with salt, pepper, or other seasonings.', 'Añada la carne molida al sartén y cocine hasta que se vea doradita. Vacíe el liquido y sazone con sal, pimienta u otros condimentos/sazonadores.'),
  (217, 4, 'Combine the meat mixture and the cooked vegetables.', 'Combine la carne y verduras cocidas.'),
  (217, 5, 'Put vegetable oil or non-stick spray on a baking sheet.  With your fingers, spread out pizza dough into a 15x12 inch rectangle.', 'Ponga aceite vegetal o aceite para cocinar de aerosol sobre una charola para hornear. Usando sus dedos, esparza la masa para pizza hasta formar un rectángulo de 15 x 12 pulgadas.'),
  (217, 6, 'Top dough with tomato sauce. Leave about 1 inch in from the edge.', 'Cubra la masa para pizza con la salsa de tomate. Dejar libre de salsa una franja de aproximadamente 1 pulgada de ancho alrededor de toda la orilla de la masa.'),
  (217, 7, 'Top the sauce with the meat/vegetable mixture.', 'Por encima de la salsa, vierta la mezcla de carne y verduras.'),
  (217, 8, 'Top with the cheese.  Fold edges over to create a thicker crust (optional).', 'Por ultimo, cubra con el queso. Si lo desea, doble las orillas de la masa para crear una "corteza" más gruesa (opcional).'),
  (217, 9, 'Bake for 15 minutes or until crust is golden brown.', 'Cocine en el horno por 15 minutos o hasta que la masa/corteza se vea doradita.'),
  (218, 1, 'Cook rice according to instructions on the package.', 'Cocinar el arroz de acuerdo a las instrucciones del paquete.'),
  (218, 2, 'Cook the cauliflower pieces (steam, boil, or microwave).', 'cocine los pedazos de coliflor (ya sea al vapor, hervidos o en el horno de microondas).'),
  (218, 3, 'Mix together cauliflower, corn, rice, and meat.', 'Mezcle todo junto, la coliflor, elote, arroz y carne cocida.'),
  (218, 4, 'If desired, warm mixture on stove top or in 350 degree oven for 5 minutes.', 'Si lo desea, caliente la "mezcla" en la estufa o en el horno por 5 minutos a una temperatura de 350 grados.'),
  (218, 5, 'Top with grated cheese and, if desired, place in the oven on the top rack, on broil, until cheese melts. (optional)', 'Cubra con el queso rayado, y si lo desea, ponga el recipiente en la primera rejilla del horno y ase hasta que el queso de derrita (opcional).'),
  (219, 1, 'In a large, microwave-safe dish, place oil, carrots, bell pepper, green beans, and garlic. Stir to coat all the vegetables.', 'En un recipiente apropiado y seguro para usar en el horno de microondas, ponga el aceite, zanahorias, pimiento morrón, ejotes, y ajo. Revolver bien para asegurarse que todas las verduras se cubran de aceite.'),
  (219, 2, 'Cover the dish and microwave on high for 5 minutes.', 'Cubra el recipiente y ponga en el horno de microondas a temperatura alta por 5 minutos.'),
  (219, 3, 'Add rice, broth, ketchup, beans, 1 cup water, and a pinch of salt or other favorite seasonings.', 'Añada el arroz, consomé, salsa de tomate, frijoles, 1 taza de agua, y una pizca de sal o cualquier otro condimento/sazonador favorito.'),
  (219, 4, 'Cover the dish and microwave on high until vegetables and rice are tender, about 5 minutes.', 'Cubra el recipiente y ponga de nuevo en el horno de microondas a temperatura alta hasta que el arroz y las verduras estén blandas, alrededor de 5 minutos.'),
  (220, 1, 'In a large, microwave-safe dish, toss onions and oil. Place garlic in the center of the dish. Cover and microwave on high for 5 minutes.', 'En un recipiente apropiado y seguro para usar en el horno de microondas, ponga las cebollas y aceite. Coloque el ajo en el centro del recipiente. Cubra y cocine en el microondas a temperatura alta por 5 minutos.'),
  (220, 2, 'Add bell pepper and ketchup to the onion mixture.  Stir.', 'Añada el pimiento morrón y salsa de tomate "ketchup" a la mezcla de cebolla. Revuelva bien.'),
  (220, 3, 'Rub chicken with salt or pepper and place on vegetables, with thickest part of breast facing edge of dish. Cover and cook on high until chicken is cooked throughout, about 15 minutes.', 'Untarle la sal o pimienta a las pechugas de pollo y colocarlas sobre las verduras, con la parte mas gruesa de la pechuga apuntando hacia la orilla del recipiente. Cubra y cocine en el horno de microondas a temperatura alta hasta que el pollo se cocine por completo, alrededor de 15 minutos.'),
  (220, 4, 'Remove garlic.  Slice off the top and squeeze cooked cloves into a small bowl. Add mayonnaise and lemon juice and mash with a spoon. Stir this mixture into vegetables.', 'Sacar la cabeza de ajo. Corte la parte de arriba y apriete para sacar/exprimir los dientes de ajo en tazón chico. Agregue la mayonesa y jugo de limón y machaque con una cuchara. Vierta esta mezcla en el recipiente de las verduras.'),
  (220, 5, 'Serve vegetables with chicken on top.', 'Sirva colocando el pollo sobre las verduras.'),
  (221, 1, 'Preheat oven to 350 degrees.', 'Precalentar el horno a 350 grados.'),
  (221, 2, 'Wash potatoes, dry them, and poke them all over with a knife.  Put potatoes on a baking sheet and cook for about 1 hour, or until tender. Remove the potatoes from the oven and let them cool.', 'Lave las papas, séquelas, y pínchelas todo alrededor con un cuchillo. Coloque las papas en una charola para hornear y ponga a cocinar en el horno por 1 hora, o hasta que estén blandas.  Retírelas del horno y ponga a un lado a enfriar.'),
  (221, 3, 'While the potatoes are cooking, put the oil in a frying pan and cook the meat and onions over medium heat until the meat is brown and the onions are soft.  Drain the liquid.', 'Mientras las papas se cocinan, ponga el aceite en un sartén y cocine la carne y cebollas a fuego medio hasta que la carne se dore y las cebollas estén blanditas. Cuele el líquido.'),
  (221, 4, 'Cut a thin slice off the top of each cooked potato.  Scoop out the potato, leaving the potato shell.', 'Corte una rebanada delgada de la parte de arriba de cada papa ya cocida. Usando una cuchara, saque el interior de la papa, dejando simplemente la cáscara vacía.'),
  (221, 5, 'Place the insides of the potato in a bowl.  Add yogurt, chilies, salt, pepper, or any favorite seasonings.  Stir well.', 'Ponga "las entrañas" de la papa en un recipiente hondo. Añada el yogur, chiles, sal, pimienta, o cualquier otro condimento/sazonador de su agrado. Mezcle y revuelva bien.'),
  (221, 6, 'Stir in meat mixture and combine well.  Stuff the potato shells.', 'Vierta la mezcla de carne y cebolla y combine bien todo. Rellene las cáscaras de las papas.'),
  (221, 7, 'Place the potatoes on a baking sheet.  Sprinkle the potatoes with cheese.  Bake for 10-15 minutes until heated through.', 'Ponga las papas en una charola para hornear. Espolvoree las papas con el queso. Póngalas en el horno de 10-15 minutos hasta que se calienten completamente.'),
  (222, 1, 'Heat 1 spoon oil in a large pot over medium-high heat.  Sprinkle chicken pieces with salt and pepper. Add chicken to pot and cook quickly until light golden but not cooked through, 1-2 minutes.  Put chicken in a bowl.', 'Calentar una cucharada de aceite en una olla grande a fuego medio-alto. Rocíe los pedazos de pollo con sal y pimienta. Ponga el pollo en la olla y cocine de manera rápida hasta que este dorado pero no completamente cocido, alrededor de 1-2 minutos. Transfiera el pollo a un recipiente hondo.'),
  (222, 2, 'Add 1 spoon oil and onion to pot and cook until soft, 2-3 minutes.  Add garlic and stir 1 minute.', 'Añada una cucharada de aceite y la cebolla a la olla, y cocine hasta que la cebolla se suavice, de 2-3 minutos. Agréguele al ajo y revuelva por un minuto.'),
  (222, 3, 'Add sweet potatoes, parsnips, turnips, rutabaga, broth, and raisins (optional).', 'Añada el camote, nabos, colinabos, pastinacas, consomé, y pasas (opcional).'),
  (222, 4, 'Bring to a boil, cover, and reduce to a simmer.  Cook until vegetables are tender, about 20 minutes.  Add tomatoes and chicken with its juices to the pot.  Simmer until chicken is cooked through and flavors blend, about 5 minutes longer.', 'Permita que hierva, cubra y reduzca la intensidad a fuego lento. Cocine hasta que las verduras estén suaves y tiernas, aproximadamente 20 minutos. Agregue el jitomate y pollo con todo y sus "jugos" a la olla. Siga cocinando a fuego lento hasta que el pollo se cocine completamente y los sabores se mezclen, alrededor de 5 minutos.'),
  (222, 5, 'Can be served over cooked rice.', 'Se puede servir sobre arroz.'),
  (223, 1, 'Peel potatoes and cut into 1-inch pieces.  Boil in lightly-salted water.  Be sure that the water covers all of the potatoes.  Cook until soft, 10-15 minutes.', 'Pele las papas y córtelas en pedazos de aproximadamente 1 pulgada de tamaño. Viértalas en una olla con agua ligeramente salada y déjela que hierva. Asegúrese de que el agua cubra todas las papas. Cocine hasta que las papas estén blandas, de 10-15 minutos.'),
  (223, 2, 'Drain the potatoes and use a fork or potato mashed to smash to desired smoothness.  Season with a pinch of salt and pepper.', 'Cuele las papas y usando un tenedor o un machacador de papas machaque las papas hasta adquirir la suavidad deseada. Sazone con una pizca de sal y pimienta.'),
  (223, 3, 'Put vegetable oil in a frying pan.  Heat the oil and cook the meat, using a wooden spoon or spatula to crumble meat into small pieces, 5-7 minutes.  Drain liquid from the meat mixture.', 'Ponga el aceite en un sartén. Caliente el aceite y cocine la carne de 5-7 minutos. Usando una cuchara o espátula de madera desmenuce la carne en fragmentos pequeños. Cuele el liquido/jugo de la mezcla de carne.'),
  (223, 4, 'Mix potatoes with cooked meat in a bowl.', 'Mezcle las papas con la carne ya cocida en un recipiente hondo.'),
  (223, 5, 'Place generous amount of this mixture in each taco shell.  Top with any of the optional ingredients.', 'Coloque una buena cantidad de la mezcla de carne y papas en cada corteza para tacos ("taco shells"). Déle el toque final agregando cualquiera de los ingredientes opcionales.'),
  (224, 1, 'Preheat oven to 450 degrees.', 'Precalentar el horno a 450 grados.'),
  (224, 2, 'Trim tops and bottoms from parsnips and peel them.  Cut lengthwise into sticks about the size of french fries.', 'Limpie y recorte la parte de arriba y abajo de las pastinacas y pélelas bien. Córtelas a lo largo, en tiritas del tamaño aproximado de papas fritas.'),
  (224, 3, 'Lightly oil a baking sheet with 1 large spoon oil.', 'Usando una cucharada grande de aceite, ligeramente aplique y cubra con el aceite una charola para hornear.'),
  (224, 4, 'Put parsnips in a bowl with about 1 large spoon oil.  Toss parsnips and oil so that parsnips are well coated.  Add salt, pepper, or favorite seasonings.', 'Ponga las pastinacas en un recipiente hondo junto con una cucharada grande de aceite. Revuelva bien asegurándose que las tiritas de pastinacas queden bien cubiertas con el aceite. Añada sal, pimienta, o sazones/condimentos favoritos.'),
  (224, 5, 'Spread parsnips in a single layer on the baking sheet.', 'Coloque las tiritas en la charola para hornear bien distribuidas sin amontonarlas y formando solo una capa.'),
  (224, 6, 'Cook for about 15-20 minutes and turn parsnips.  Return to oven and cook another 10-15 minutes, until parsnips are golden brown.', 'Cocine en el horno de 15-20 minutos. Saque la charola, déle vuelta a las tiritas y ponga de nuevo en horno y cocine por otros 10-15 minutos, hasta que las pastinacas estén doraditas.'),
  (225, 1, 'Preheat oven to 350 degrees.', 'Precalentar el horno a 350 grados.'),
  (225, 2, 'In a medium microwave-safe bowl, combine carrots with 3 large spoons of water.   Cover with plastic wrap and microwave until tender, 4 minutes. Drain carrots.', 'En un recipiente mediano y hondo, apropiado para el horno de microondas, combine las zanahorias con 3 cucharadas grandes de agua. Cubra con plástico adherente ("saran wrap") y cocine en el microondas hasta que las zanahorias estén blanditas, alrededor de 4 minutos. Cuele las zanahorias.'),
  (225, 3, 'In a large bowl, stir together flour, baking powder, baking soda, and salt. Stir in eggs, sugar, and butter until combined. Mix in carrots.', 'En un recipiente grande y hondo, Mezcle la harina, polvo para hornear, bicarbonato de sodio, y sal. Vierta los huevos, azúcar, y mantequilla hasta que todo quede bien revuelto. Añada las zanahorias y revuelva bien.'),
  (225, 4, 'Coat a loaf pan (9” x 5”) with butter or margarine or non-stick spray.  Or, place wax paper to line the pan.  Put mixture into this dish.', 'Cubra un molde para pan de 9"X 5" con la mantequilla o margarina, o con un aerosol/rocío antiadherente. O use papel encerado para cubrir el molde. Vierta la mezcla en el molde.'),
  (225, 5, 'Bake until the top is golden brown and a toothpick inserted in center comes out clean, about 35 minutes. Let cool slightly before serving.', 'Cocine en el horno hasta que la parte de arriba se ponga de color dorado y al introducir y sacar un palillo (pica diente) este salga limpio, alrededor de 35 minutos. Deje que se enfrié ligeramente antes de servir.'),
  (226, 1, 'In a bowl, combine all of the ingredients, except the oil.  Mix well.', 'En un recipiente hondo, combine todos los ingredientes, excepto el aceite. Mezcle bien.'),
  (226, 2, 'Spray frying pan with cooking spray or heat vegetable oil in the pan, at medium heat.', 'Rocié un sartén con el aerosol antiadherente o caliente el aceite, a fuego medio.'),
  (226, 3, 'Drop large spoonfuls of zucchini mixture into the pan.  Cook for 2-3 minutes per side, until golden brown.', 'Vierta unas cucharadas grandes de la mezcla de calabacitas en el sartén. Cocine de 2-3 minutos por lado, hasta que los panqueques estén doraditos.'),
  (226, 4, 'Drain on a baking rack or paper towel.  Serve immediately.', 'Póngalos a escurrir sobre una rejilla para hornear o toallita de papel. Sirva inmediatamente.'),
  (227, 1, 'Heat oven to 325 degrees.', 'Calentar el horno a 325 grados.'),
  (227, 2, 'Heat 2 large spoons of oil in a pan, add onions, stir and cook until brown, about 5 minutes.  Remove onions.', 'Caliente 2 cucharadas grandes de aceite en un sartén, añada las cebollas, revuelva y cocine hasta que las cebollas estén doraditas, alrededor de 5 minutos. Retire las cebollas del sartén.'),
  (227, 3, 'Add ground meat to the pan.  Use a wooden spoon or spatula to break meat apart, and cook until brown.  Add 1 cup of water, salt, and pepper, and bring to a boil.   Lower the heat, cover and simmer until the meat is cooked through, another 5 minutes.  Remove meat from this broth.', 'Agregue la carne molida al sartén. Use una cuchara de madera o espátula para esparcir la carne, y cocine hasta que este doradita. Añada 1 taza de agua, sal, y pimienta, y deje hervir. Reduzca la temperatura, cubra el sartén y deje hirviendo a fuego lento hasta que la carne este cocida completamente, alrededor de 5 minutos. Retire la carne del sartén dejando el líquido en el mismo.'),
  (227, 4, 'Add cooked onions to the broth.', 'Agregue las cebollas al sartén de nuevo.'),
  (227, 5, 'Heat 2 large spoons of oil in a different pan and add the carrot pieces.  Cook gently, stirring until they are lightly browned and tender, adding a little water if needed to keep the carrots wet.  Add raisins and cook gently until they get larger, 2-3 minutes more.', 'Ponga a calentar 2 cucharadas grandes de aceite en otro sartén y agréguele las tiritas de zanahoria. Cocine ligeramente, revolviendo y volteando las tiritas hasta que estén ligeramente blandas y doraditas, agregando un poco de agua si es necesario para mantener las zanahorias mojadas. Añada las pasas y cocine suavemente hasta que las pasas se agranden, alrededor de 2-3 minutos más.'),
  (227, 6, 'Bring 4-5 cups of water to a boil in another pot, add 1 small spoon of salt, and add rice.  When water returns to a boil, cook rice for 2-3 minutes, and drain.', 'En una olla ponga a hervir 4-5 tazas de agua, póngale 1 cucharadita sal, y añada el arroz.  Deje que vuelva a hervir y cocine el arroz de 2-3 minutos más, para después colar todo'),
  (227, 7, 'Mix rice and the onions with broth.  Spread this mixture in a large casserole dish.  Place cooked meat on top of rice, on one side of the dish, and the mixture of carrots and raisins on the other side.  Bake in oven for 25 minutes.', 'Mezcle el arroz y cebollas en el sartén que uso para cocer la carne. Vierta esta mezcla en un recipiente de vidrio con borde grande. Coloque la carne por encima del arroz en un lado del recipiente, y la mezcla de zanahorias y pasas en el otro lado. Cocine en el horno por 25 minutos.'),
  (227, 8, 'To serve, you may want to separate carrot mixture, meat, and rice.  Or, you may want to mix them together.', 'Para servir, usted podría separar la mezcla de zanahoria, carne, y arroz. O si lo prefiere, podría mezclar todo y servirlo junto.'),
  (228, 1, 'Peel potatoes and cut into 1 inch pieces', 'Pele y corte las papas en pedazos chicos de 1 pulgada.'),
  (228, 2, 'Peel carrots and cut into ½ inch pieces', 'Pele y corte las zanahorias en pedacitos de ½ pulgada.'),
  (228, 3, 'Combine potatoes, carrots, and garlic in a pot.  Cover with water.  Add a pinch of salt (optional).  Bring to a boil and simmer until completely tender, about 20 minutes.', 'Combine las papas, zanahorias y ajo en una olla. Añada agua hasta cubrir las verduras. Agregue una pizca de sal (opcional) y cocine hasta que hierva. Disminuya la intensidad del fuego y siga cocinando las verduras hasta que estas estén completamente tiernas (20 minutos aproximadamente).'),
  (228, 4, 'Drain vegetables, saving the cooking water.', 'Cuele las verduras pero no tire el líquido.'),
  (228, 5, 'Add milk and butter to the vegetables.', 'Agregue la leche y mantequilla a las verduras.'),
  (228, 6, 'Use potato masher or fork to mash until smooth.  Add cooking water to get desired texture.', 'Usando un machacador de papas o un tenedor, machaque la mezcla hasta que esta quede suave. Poco a poco agréguele el líquido en que hirvió las verduras hasta conseguir la consistencia deseada.'),
  (228, 7, 'Season with salt, pepper, or other seasonings (optional).', 'Sazone con sal, pimienta o cualquier otro condimento (opcional).'),
  (229, 1, 'Peel the cooked sweet potato. Mash the sweet potato with a potato masher or fork.', 'Pele el camote cocido. Machaque el camote con un machacador de papas o tenedor.'),
  (229, 2, 'Combine the sweet potato with the other ingredients in a blender.', 'Combine el camote con los otros ingredientes en una licuadora.'),
  (229, 3, 'Blend until smooth. Adjust ingredients to taste.', 'Licue/bata hasta que quede suave. Ajuste los ingredientes a su gusto.'),
  (230, 1, 'Heat oven to 375 degrees.', 'Calentar el horno a 375 grados.'),
  (230, 2, 'With 1 spoon oil, grease inside of a casserole dish.', 'Usando una cucharada de aceite, engrase la parte interior de un recipiente de vidrio con orillas apto para el horno.'),
  (230, 3, 'In a small pan over low heat, combine 1 spoon oil, honey, and vinegar.  Stir until mixed.', 'En un sartén chico y a fuego lento, combine 1 cucharada (de cada uno) aceite, miel, y vinagre. Revuelva hasta que todo quede bien mezclado.'),
  (230, 4, 'Combine vegetable and apple pieces in a bowl.  Toss with the honey mixture until all pieces are coated.', 'Combine las tiras de verdura y manzana en un recipiente hondo. Revuelva con la mezcla de miel hasta que todas las tiritas queden cubiertas de la mezcla.'),
  (230, 5, 'Put combination in casserole dish, cover with aluminum foil, and bake until tender, 45-60 minutes.', 'Vierta todo en el recipiente de vidrio, cubra con papel de aluminio, y cocine en el horno hasta que las tiritas estén tiernas, de 45-60 minutos.'),
  (231, 1, 'Preheat oven to 425 degrees.  Grease a baking dish with oil.', 'Precalentar el horno a 425 grados.  Engrase un recipiente para hornear con aceite.'),
  (231, 2, 'Place chicken pieces in the baking dish. Arrange vegetables around chicken pieces, season with salt and pepper. Pour broth over chicken and vegetables.  Bake for 20 minutes.', 'Coloque las piezas de pollo en el recipiente para hornear. Ponga las verduras alrededor de las piezas de pollo, sazone con sal y pimienta. Vierta el consomé sobre el pollo y verduras. Cocine en el horno por 20 minutos.'),
  (231, 3, 'In the meantime, in a pan, melt butter and stir in maple syrup.  Brush mixture over chicken and vegetables and bake for another 15-20 minutes, until chicken is cooked all the way through. Brush chicken frequently with maple-butter mix.', 'Mientras tanto, en un sartén, ponga a derretir la mantequilla y agregue el jarabe de arce. Usando una brochita, aplique la mezcla de mantequilla y jarabe al pollo y verduras y hornee por otros 15-20 minutos, hasta que el pollo se cueza completamente. Unte la mezcla de mantequilla y jarabe al pollo de manera frecuente, mientras se cocina.'),
  (231, 4, 'Remove chicken and vegetables from pan. With a spoon, skim fat from liquid.  Pour remainder of liquid over chicken.', 'Retire el pollo y verduras del recipiente. Usando una cuchara, quite la grasa del líquido. Vierta el resto de la emulsión sobre el pollo.'),
  (232, 1, 'Heat oil in a pan, cook onion and pepper slices until they are tender, stirring occasionally, 5-7 minutes.', 'Caliente el aceite en un sartén, cocine las rebanadas de cebolla y pimientos hasta que estén tiernas, agitando/revolviendo ocasionalmente, de 5-7 minutos.'),
  (232, 2, 'Reduce heat to low and add the corn and meat.  Cook until the mixture is hot and bubbling.', 'Reduzca la temperatura a fuego lento y añada el elote/maíz y carne. Cocine hasta que la mezcla este caliente y "burbujeando".'),
  (232, 3, 'Spoon about a 1/3 cup of meat mixture in the center of each tortilla.  Fold tortillas around the filling.', 'Vierta aproximadamente un 1/3 de taza de la mezcla en el centro de cada tortilla. Doble las tortillas "envolviendo" la mezcla.'),
  (232, 4, 'Serve with bowl of the remaining meat mixture, and bowls of sauce or sliced olives, so diners can top their fajitas or add to the filling, as they wish.', 'Sirva el resto de la mezcla de carne, así como las aceitunas y salsa en recipientes hondos chicos, para que las personas puedan terminar de preparar sus fajitas, a su gusto.'),
  (233, 1, 'Preheat oven to 350 degrees.', 'Precalentar el horno a 350 grados.'),
  (233, 2, 'Boil green beans in a pot of water until tender, about 5 minutes. Drain', 'Ponga los ejotes en una olla con agua y hierva hasta que estén tiernitos, alrededor de 5 minutos. Cuélelos.'),
  (233, 3, 'In a bowl, mix together cooked chicken, condensed soup, green beans, corn, onions, garlic, and salt and pepper.', 'En un recipiente hondo, mezcle el pollo ya cocido, la crema de pollo condensada, ejotes, elote, cebollas, ajo, y sal y pimienta.'),
  (233, 4, 'In a baking dish (9x13 inches) spread out the chicken and vegetable mixture. Top with prepared stuffing.  Sprinkle with cheese.', 'En un recipiente para hornear de 9"X13" pulgadas de tamaño, coloque el pollo y mezcla de verduras, distribuyendo todo. Cubra con el relleno preparado. Espolvoreé el queso por encima de todo.'),
  (233, 5, 'Cover tightly with aluminum foil and bake for 20 minutes.  Remove cover and bake for another 10 minutes or until cheese is melted and browned.', 'Cubra firmemente con papel de aluminio y ponga en el horno por 20 minutos. Quítele el papel de aluminio y cocine por 10 minutos adicionales o hasta que el queso se derrita y este doradito.'),
  (234, 1, 'Preheat oven to 350 degrees.', 'Precalentar el horno a 350 grados.'),
  (234, 2, 'Remove and discard green leaves from bottom of cauliflower.  Cut cauliflower in half from top to bottom.  Cut away the tough stem from both halves.  Chop remaining cauliflower into bite-size pieces.', 'Quitar y desechar las hojas verdes de la cabeza de la coliflor. Corte la coliflor por la mitad en dirección de arriba abajo. Quitar el tallo duro del centro de ambas mitades. Corte el resto de la coliflor en trozos chicos.'),
  (234, 3, 'Combine cauliflower pieces, onion, lemon juice, and oil. Season with a pinch of salt and pepper.', 'Combine los pedazos de coliflor, cebolla, jugo de limón, y aceite. Sazone con una pizca de sal y pimienta.'),
  (234, 4, 'Coat a baking dish with oil or line with aluminum foil.', 'Cubra el interior del recipiente para hornear con aceite o forre con papel de aluminio.'),
  (234, 5, 'Spread mixture onto baking dish.', 'Esparza y distribuya la mezcla en el recipiente.'),
  (234, 6, 'Bake for 20 minutes. Stir and bake for another 20 minutes. (40 minutes total.)', 'Cocine en el horno por 20 minutos. Revuelva todo y cocine por otros 20 minutos. (40 minutos en total).'),
  (234, 7, 'Stir in the chicken and sour cream.  Sprinkle top with cheese. Bake for another 5 minutes or until cheese has melted.', 'Vierta los pedazos de pollo ya cocidos y la crema agria. Distribuya el queso por encima. Cocine por otros 5 minutos o hasta que el queso se derrita.'),
  (235, 1, 'Wash chicken and pat dry.  Cut into bite size pieces.', 'Lavar el pollo y secarlo con un trapo o tallita de papel. Parta el pollo en trozos chicos, tamaño bocado.'),
  (235, 2, 'Cut large cauliflower florets in half.', 'Corte los floretes/brotes de coliflor por la mitad.'),
  (235, 3, 'Place flour, salt, and pepper in a plastic bag.  Add chicken pieces and shake to coat.', 'Coloque la harina, sal, y pimienta en una bolsa de plástico. Añada los pedazos de pollo, cierre la bolsa y agítela hasta que estos queden completamente cubiertos por la mezcla.'),
  (235, 4, 'Add oil to a large frying pan or skillet over medium heat.  Brown chicken pieces 
