INSERT INTO recipe_note (recipe_id, position, text_en, text_es) VALUES
  (34, 1, 'Note: You can add any vegetables to this soup.', 'Nota: Usted puede agregar cualquier otro tipo de verduras a esta sopa'),
  (100, 1, '**Note: For People with diabetes, check barbecue sauce label for sugar**', '**Nota: Para gente con diabetes, revisar la etiqueta de la salsa de barbacoa por el contenido de azucar**'),
  (212, 1, 'Options for sauce: Tomato, marinara; Alfredo, or other pasta sauce', 'Opciones de Salsas: Salsa de Tomate, Salsa estilo Marinara; Salsa Alfredo, o cualquier otra salsa para pastas.'),
  (212, 2, 'Options for toppings:  Raw or cooked vegetables (broccoli, zucchini, cauliflower, mushrooms, bell peppers, sliced olives, sliced jalapeno, onions, or other vegetables); cooked ground meat (beef, turkey, or pork).', 'Opciones de Ingreddientes/"toppings":  Verduras crudas o cocidas (brócoli, calabacitas, coliflor, hongos, pimiento morrón, aceitunas rebanadas, jalapeños rebanados, cebolla, o cualquier otra verdura); carne molida cocida (res, pavo, o puerco).'),
  (212, 3, 'Options for cheese:  Mozzarella, cheddar, Swiss, or Monterey jack, or other cheese.', 'Opciones de Queso:  Estilo mozarela, estilo cheddar, estilo Suizo (gruyere), o queso blanco estilo Monterey, o cualquier otro queso predilecto.'),
  (218, 1, 'Note: Cooking time will be less with instant rice.', 'Nota: El tiempo para cocinar será menor si se usa arroz instantáneo.'),
