INSERT INTO secret (id, display_number, category_id, active, headline_en, headline_es, why_it_works_en, why_it_works_es, image_path_en, image_path_es, cover_image_en, cover_image_es, attachment_en, attachment_es) VALUES
  (2, 5603, 1, true, 'Be a breakfast eater.', 'Coma desayuno todos los días.', 'Breakfast is the most important meal of the day because it will help your family’s energy level and performance in school and at work.  Researchers have shown that without breakfast, you and your family are more likely to eat unhealthy foods later in the day. 
